function totpBase32Encode(string $bytes): string {
    $alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $out = ''; $v = 0; $bits = 0;
    for ($i = 0; $i < strlen($bytes); $i++) {
        $v = ($v << 8) | ord($bytes[$i]); $bits += 8;
        while ($bits >= 5) { $out .= $alpha[($v >> ($bits - 5)) & 31]; $bits -= 5; }
    }
    if ($bits > 0) $out .= $alpha[($v << (5 - $bits)) & 31];
    return $out;
}
function totpBase32Decode(string $b32): string {
    $alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $b32 = strtoupper(preg_replace('/[^A-Z2-7]/', '', $b32));
    $out = ''; $v = 0; $bits = 0;
    for ($i = 0; $i < strlen($b32); $i++) {
        $p = strpos($alpha, $b32[$i]); if ($p === false) continue;
        $v = ($v << 5) | $p; $bits += 5;
        if ($bits >= 8) { $out .= chr(($v >> ($bits - 8)) & 0xFF); $bits -= 8; }
    }
    return $out;
}
function totpGenSecret(): string { return totpBase32Encode(random_bytes(20)); }
function totpCode(string $secret, int $timeSlot): string {
    $key = totpBase32Decode($secret);
    $t   = pack('J', $timeSlot);
    $hmac = hash_hmac('sha1', $t, $key, true);
    $offset = ord($hmac[19]) & 0x0F;
    $otp = ((ord($hmac[$offset]) & 0x7F) << 24) | ((ord($hmac[$offset+1]) & 0xFF) << 16)
         | ((ord($hmac[$offset+2]) & 0xFF) << 8) | (ord($hmac[$offset+3]) & 0xFF);
    return str_pad((string)($otp % 1000000), 6, '0', STR_PAD_LEFT);
}
function totpVerify(string $secret, string $code, int $window = 1): bool {
    if (!$secret || !ctype_digit($code)) return false;
    $now = (int) floor(time() / 30);
    for ($i = -$window; $i <= $window; $i++)
        if (hash_equals(totpCode($secret, $now + $i), str_pad($code, 6, '0', STR_PAD_LEFT))) return true;
    return false;
}
function totpUri(string $secret, string $email, string $issuer = 'Free Church ChMS'): string {
    return 'otpauth://totp/' . rawurlencode($issuer . ':' . $email)
         . '?secret=' . $secret . '&issuer=' . rawurlencode($issuer) . '&algorithm=SHA1&digits=6&period=30';
}





function getDB(): PDO {
    static $db = null;
    if ($db) return $db;
    $db = new PDO('sqlite:' . DB_PATH, null, null, [PDO::ATTR_TIMEOUT => 10]);
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    $db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
    
    
    
    
    try { $db->exec('PRAGMA busy_timeout=10000; PRAGMA synchronous=NORMAL; PRAGMA cache_size=-16000; PRAGMA temp_store=MEMORY;'); } catch (\Throwable $e) {}
    setupDB($db);
    return $db;
}
