    foreach ([['ai','AI features (Assistant, Studio, Insights AI)'],['giving','Giving & donor intelligence'],['workflows','Automated workflows'],['communications','Email & SMS communications'],['integrations','Integrations & sync'],['streaming','Live streaming (beta)'],['public_kb','Public Knowledge Base']] as [$k,$l])
        $db->prepare('INSERT OR IGNORE INTO feature_flags (key,label,enabled) VALUES (?,?,1)')->execute([$k,$l]);
}

function flag(string $key): bool {
    $st = getDB()->prepare('SELECT enabled FROM feature_flags WHERE key=?'); $st->execute([$key]);
    $v = $st->fetchColumn(); return $v === false ? true : (bool)$v;
}

function getSetting(string $key): string {
    $st = getDB()->prepare('SELECT value FROM settings WHERE key=?');
    $st->execute([$key]);
    return (string)($st->fetchColumn() ?: '');
}
function setSetting(string $key, string $value): void {
    getDB()->prepare('INSERT OR REPLACE INTO settings (key,value) VALUES (?,?)')->execute([$key, $value]);
}
function h(?string $s): string { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }

function currentLang(): string {
    static $l = null; if ($l !== null) return $l;
    $allow = ['en','de','fr','it','es'];
    $g = $_GET['lang'] ?? '';
    if (in_array($g, $allow, true)) { $_SESSION['lang'] = $g; @setcookie('aclang', $g, time()+31536000, '/'); return $l = $g; }
    $c = $_SESSION['lang'] ?? ($_COOKIE['aclang'] ?? 'en');
    return $l = in_array($c, $allow, true) ? $c : 'en';
}
