function t(string $en): string {
    $l = currentLang(); if ($l === 'en') return $en;
    $T = translations(); return $T[$l][$en] ?? $en;
}
function langName(string $code): string { return ['en'=>'English','de'=>'Deutsch','fr'=>'Francais','it'=>'Italiano','es'=>'Español'][$code] ?? $code; }

function themeList(): array {
    
    return [
        'base'  => ['Default',   '#2E5BFF', '#6f3de8'],
        'green' => ['Soft Green', '#16a34a', '#0c8038'],
        'rose'  => ['Warm Rose',  '#e11d48', '#c91a41'],
        'lemon' => ['Lemon',      '#fde047', '#f5c400'],
        'blue'  => ['Lush Cerulean Blue', '#0ea5e9', '#0a7baa'],
        'dark'  => ['Dark Mode',  '#3b4a6b', '#0d1424'],
    ];
}
function currentTheme(): string {
    static $th = null; if ($th !== null) return $th;
    $allow = array_keys(themeList());
    $g = $_GET['theme'] ?? '';
    if (in_array($g, $allow, true)) { $_SESSION['theme'] = $g; @setcookie('actheme', $g, time()+31536000, '/'); return $th = $g; }
    $c = $_SESSION['theme'] ?? ($_COOKIE['actheme'] ?? 'base');
    return $th = in_array($c, $allow, true) ? $c : 'base';
}

function themePicker(): string {
    $cur = currentTheme(); $out = '<div class="theme-picker">';
    foreach (themeList() as $k=>[$label,$c1,$c2]) {
        $out .= '<button type="button" class="theme-dot'.($cur===$k?' selected':'').'" data-tk="'.$k.'" title="'.h(t($label)).'" onclick="setTheme(\''.$k.'\')" style="--d1:'.$c1.';--d2:'.$c2.'"><span></span><em>'.h(t($label)).'</em></button>';
    }
    return $out.'</div>';
}

function themeDots(): string {
    $cur = currentTheme(); $out = '<div class="theme-mini" role="group" aria-label="'.h(t('Theme')).'">';
    foreach (themeList() as $k=>[$label,$c1,$c2]) {
        $out .= '<button type="button" class="theme-mini-dot'.($cur===$k?' selected':'').'" data-tk="'.$k.'" data-name="'.h(t($label)).'" aria-label="'.h(t($label)).'" onclick="setTheme(\''.$k.'\')" style="--d1:'.$c1.';--d2:'.$c2.'"></button>';
    }
    return $out.'</div>';
}
function fmt(float $n): string { return '$' . number_format($n, 2); }
function fmtK(float $n): string {
    if ($n >= 1000000) return '$' . number_format($n/1000000, 1) . 'M';
    if ($n >= 1000)    return '$' . number_format($n/1000, 1) . 'K';
    return '$' . number_format($n, 0);
}
function csrfToken(): string {
    if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(16));
    return $_SESSION['csrf'];
}

