}






function clientIp(): string {
    $remote = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
    $remoteIsProxy = $remote !== '' && !filter_var($remote, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE);
    if ($remoteIsProxy && !empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        $hops = array_map('trim', explode(',', (string)$_SERVER['HTTP_X_FORWARDED_FOR']));
        for ($i = count($hops) - 1; $i >= 0; $i--) {           
            if (filter_var($hops[$i], FILTER_VALIDATE_IP)) return $hops[$i];
        }
    }
    return filter_var($remote, FILTER_VALIDATE_IP) ? $remote : '0.0.0.0';
}

function rateCount(string $bucket, int $windowSec): int {
    try { $s = getDB()->prepare('SELECT COUNT(*) FROM rate_limits WHERE bucket=? AND created_at>=?');
        $s->execute([$bucket, time() - $windowSec]); return (int)$s->fetchColumn();
    } catch (\Throwable $e) { return 0; }
}

function rateHit(string $bucket): void {
    try { $db = getDB();
        $db->prepare('INSERT INTO rate_limits (bucket,created_at) VALUES (?,?)')->execute([$bucket, time()]);
        if (random_int(1, 50) === 1) $db->prepare('DELETE FROM rate_limits WHERE created_at < ?')->execute([time() - 86400]);
    } catch (\Throwable $e) {}
}

function rateClear(string $bucket): void {
    try { getDB()->prepare('DELETE FROM rate_limits WHERE bucket=?')->execute([$bucket]); } catch (\Throwable $e) {}
}

function isLoggedIn(): bool   { return !empty($_SESSION['user_id']); }
function isAdmin(): bool      { return in_array($_SESSION['user_role'] ?? '', ['admin','superadmin'], true); }
function isSuperAdmin(): bool { return ($_SESSION['user_role'] ?? '') === 'superadmin'; }
function requireLogin(): void { if (!isLoggedIn()) { header('Location: ?page=login'); exit; } }
function requireAdmin(): void { if (!isAdmin()) { http_response_code(403); header('Location: ?page=dashboard&err=' . urlencode('Administrators only.')); exit; } }
function auditLog(string $action, string $detail = ''): void {
    try { getDB()->prepare('INSERT INTO audit_log (user_id,user_email,action,detail,ip) VALUES (?,?,?,?,?)')
        ->execute([$_SESSION['user_id'] ?? null, $_SESSION['user_email'] ?? ($_SESSION['user_name'] ?? ''), $action, mb_substr($detail,0,300), $_SERVER['REMOTE_ADDR'] ?? '']); } catch (\Throwable $e) {}
}

function plans(): array {
    return [
        'free'=>['Free','$0','The entire platform · unlimited members & staff · all integrations · community support (Office Helper + Knowledge Base) — free for every church, forever.'],
    ];
}
function currentUser(): ?array {
    if (!isLoggedIn()) return null;
    $st = getDB()->prepare('SELECT * FROM users WHERE id=?');
    $st->execute([$_SESSION['user_id']]);
    return $st->fetch() ?: null;
}
function _doLogin(array $user): void {
    session_regenerate_id(true);
    $_SESSION['user_id']    = $user['id'];
    $_SESSION['user_name']  = $user['name'];
    $_SESSION['user_email'] = $user['email'] ?? '';
    $_SESSION['user_role']  = $user['role'];
    $_SESSION['login_at']   = time();
    $_SESSION['last_seen']  = time();
    try { getDB()->prepare('UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?')->execute([$user['id']]); } catch (\Throwable $e) {}
    auditLog('login', $user['email'] ?? '');
    header('Location: ?page=dashboard'); exit;
}






function smtpSend(string $to, string $subject, string $htmlBody, string &$err = ''): bool {
    $host = getSetting('smtp_host'); $port = (int)(getSetting('smtp_port') ?: 587);
    $user = getSetting('smtp_user'); $pass = getSetting('smtp_pass');
    $from = getSetting('smtp_from') ?: $user;
    $fromName = getSetting('smtp_from_name') ?: (getSetting('church_name') ?: 'Free Church ChMS');
    $secure = getSetting('smtp_secure') ?: ($port === 465 ? 'ssl' : 'tls');
    if (!$host || !$from) { $err = 'SMTP not configured.'; return false; }
    
    $clean = fn($s) => preg_replace('/[\r\n\x00].*/s', '', trim((string)$s));
    $to = $clean($to); $from = $clean($from); $subject = $clean($subject);
    if ($to === '' || strpos($to, '@') === false) { $err = 'Invalid recipient address.'; return false; }

    $remote = ($secure === 'ssl' ? 'ssl://' : '') . $host . ':' . $port;
    $ctx = stream_context_create(['ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'SNI_enabled'=>true,'peer_name'=>$host]]);
    $fp = @stream_socket_client($remote, $errno, $errstr, 15, STREAM_CLIENT_CONNECT, $ctx);
    if (!$fp) { $err = "Connection failed: $errstr ($errno)"; return false; }
    stream_set_timeout($fp, 15);
    $read = function() use ($fp) { $d = ''; while ($line = fgets($fp, 600)) { $d .= $line; if (isset($line[3]) && $line[3] === ' ') break; } return $d; };
    $cmd  = function($c) use ($fp, $read) { fwrite($fp, $c . "\r\n"); return $read(); };
    $ehlo = 'EHLO ' . ($_SERVER['SERVER_NAME'] ?? 'localhost');
    $read();
    $cmd($ehlo);
    if ($secure === 'tls') {
        $cmd('STARTTLS');
        if (!stream_socket_enable_crypto($fp, true, STREAM_CRYPTO_METHOD_TLS_CLIENT)) { $err = 'STARTTLS failed.'; fclose($fp); return false; }
        $cmd($ehlo);
    }
    if ($user) {
        $cmd('AUTH LOGIN'); $cmd(base64_encode($user)); $r = $cmd(base64_encode($pass));
        if (strpos($r, '235') === false) { $err = 'Auth failed: ' . trim($r); fclose($fp); return false; }
    }
    $cmd("MAIL FROM:<$from>");
    $cmd("RCPT TO:<$to>");
    $r = $cmd('DATA');
    if (strpos($r, '354') === false) { $err = 'DATA rejected: ' . trim($r); fclose($fp); return false; }
    $enc = '=?UTF-8?B?' . base64_encode($fromName) . '?=';
    $headers  = "From: $enc <$from>\r\nTo: <$to>\r\n";
    $headers .= 'Subject: =?UTF-8?B?' . base64_encode($subject) . "?=\r\n";
    $headers .= "MIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n";
    $body = preg_replace('/^\./m', '..', $htmlBody);
    $r = $cmd($headers . "\r\n" . $body . "\r\n.");
    $cmd('QUIT'); fclose($fp);
    if (strpos($r, '250') === false) { $err = 'Send rejected: ' . trim($r); return false; }
    return true;
}


function twilioSend(string $to, string $body, string &$err = ''): bool {
    $sid = getSetting('twilio_sid'); $tok = getSetting('twilio_token'); $from = getSetting('twilio_from');
    if (!$sid || !$tok || !$from) { $err = 'Twilio not configured.'; return false; }
    $ch = curl_init("https://api.twilio.com/2010-04-01/Accounts/$sid/Messages.json");
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_USERPWD=>"$sid:$tok",
        CURLOPT_POSTFIELDS=>http_build_query(['From'=>$from,'To'=>$to,'Body'=>$body]), CURLOPT_TIMEOUT=>20,
    ]);
    $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($code >= 200 && $code < 300) return true;
    $e = json_decode((string)$res, true); $err = $e['message'] ?? "Twilio error $code"; return false;
}


function aiComplete(string $system, $messages, int $maxTokens = 1600, string &$err = ''): string {
    $key = getSetting('anthropic_api_key');
    if (!$key) { $err = 'No Anthropic API key set (Settings → AI).'; return ''; }
    if (is_string($messages)) $messages = [['role'=>'user','content'=>$messages]];
    $payload = json_encode([
        'model'=>getSetting('ai_model') ?: 'claude-opus-4-8',
        'max_tokens'=>$maxTokens, 'system'=>$system, 'messages'=>$messages,
    ]);
    $ch = curl_init('https://api.anthropic.com/v1/messages');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$payload,
        CURLOPT_HTTPHEADER=>['x-api-key: '.$key,'anthropic-version: 2023-06-01','content-type: application/json'],
        CURLOPT_TIMEOUT=>60,
    ]);
    $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($code !== 200) { $e = json_decode((string)$res, true); $err = $e['error']['message'] ?? "API error $code"; return ''; }
    return json_decode((string)$res, true)['content'][0]['text'] ?? '';
}


function audienceMembers(string $audience): array {
    $db = getDB();
    switch ($audience) {
        case 'at_risk':    return $db->query("SELECT * FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active'")->fetchAll();
        case 'visitors':   return $db->query("SELECT * FROM members WHERE status='visitor'")->fetchAll();
        case 'volunteers': return $db->query("SELECT m.* FROM members m JOIN volunteers v ON v.member_id=m.id WHERE v.active=1 GROUP BY m.id")->fetchAll();
        case 'givers':     return $db->query("SELECT DISTINCT m.* FROM members m JOIN giving g ON g.member_id=m.id")->fetchAll();
        case 'active':
        case 'all':
        default:           return $db->query("SELECT * FROM members WHERE status='active'")->fetchAll();
    }
}


function mergeFields(string $body, array $m): string {
    $db = getDB();
    $ytd = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE member_id=".(int)$m['id']." AND strftime('%Y',date)=strftime('%Y','now')")->fetchColumn();
    $map = [
        '{first_name}'=>$m['first_name'] ?? '', '{last_name}'=>$m['last_name'] ?? '',
        '{church_name}'=>getSetting('church_name'), '{pastor_name}'=>getSetting('pastor_name'),
        '{last_attendance_date}'=>$m['last_attended'] ?? 'a while ago',
        '{giving_year_to_date}'=>fmt($ytd),
    ];
    return strtr($body, $map);
}


function safeOutboundUrl(string $url): bool {
    $p = parse_url($url);
    if (!$p || empty($p['scheme']) || !in_array(strtolower($p['scheme']), ['http','https'], true) || empty($p['host'])) return false;
    $host = trim($p['host'], '[]'); 
    $ips = filter_var($host, FILTER_VALIDATE_IP) ? [$host] : (@gethostbynamel($host) ?: []);
    if (!$ips) return false;
    foreach ($ips as $ip) {
        if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) return false;
    }
    return true;
}


function fireWebhook(string $event, array $payload): void {
    $url = getSetting('webhook_outbound_url'); if (!$url || !safeOutboundUrl($url)) return;
    $body = json_encode(['event'=>$event, 'data'=>$payload, 'sent_at'=>date('c')]);
    $hdr = ['Content-Type: application/json'];
    $secret = getSetting('webhook_outbound_secret');
    if ($secret) $hdr[] = 'X-AIChurch-Signature: sha256=' . hash_hmac('sha256', $body, $secret);
    $ch = curl_init($url);
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$body, CURLOPT_HTTPHEADER=>$hdr, CURLOPT_TIMEOUT=>8,
        CURLOPT_FOLLOWLOCATION=>false, CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS]);
    curl_exec($ch); curl_close($ch);
}


function ntfyPush(string $title, string $message): void {
    $topic = getSetting('ntfy_topic'); if (!$topic) return;
    $base = rtrim(getSetting('ntfy_base_url') ?: 'https://ntfy.sh', '/');
    if (!safeOutboundUrl("$base/$topic")) return;
    $hdr = ['Title: ' . $title]; $tok = getSetting('ntfy_token'); if ($tok) $hdr[] = "Authorization: Bearer $tok";
    $ch = curl_init("$base/$topic");
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$message, CURLOPT_HTTPHEADER=>$hdr, CURLOPT_TIMEOUT=>6,
        CURLOPT_FOLLOWLOCATION=>false, CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS]);
    curl_exec($ch); curl_close($ch);
}


function logCommunication(?int $memberId, string $channel, string $subject, string $body, string $status): void {
    getDB()->prepare('INSERT INTO communication_log (member_id,channel,subject,body,status) VALUES (?,?,?,?,?)')
           ->execute([$memberId, $channel, $subject, mb_substr($body, 0, 500), $status]);
}


function engagementTier(int $score): string {
    $watch = (int)(getSetting('engage_threshold_watch') ?: 70);
    $risk  = (int)(getSetting('engage_threshold_risk') ?: 45);
    $crit  = (int)(getSetting('engage_threshold_critical') ?: 25);
    if ($score < $crit)  return 'critical';
    if ($score < $risk)  return 'at_risk';
    if ($score < $watch) return 'watch';
    return 'healthy';
}


function recomputeEngagement(): array {
    $db = getDB();
    $members = $db->query("SELECT * FROM members WHERE status IN ('active','visitor')")->fetchAll();
    $now = time(); $updated = 0; $risk = 0;
    $upd = $db->prepare('UPDATE members SET engagement_score=?, engagement_tier=?, last_attended=? WHERE id=?');
    $hist = $db->prepare('INSERT INTO engagement_history (member_id,score,tier,signals) VALUES (?,?,?,?)');
    foreach ($members as $m) {
        $mid = (int)$m['id']; $sig = [];
        
        $la = $db->prepare("SELECT MAX(s.date) FROM attendance a JOIN services s ON s.id=a.service_id WHERE a.member_id=?");
        $la->execute([$mid]); $lastAtt = $la->fetchColumn();
        
        $ac = $db->prepare("SELECT COUNT(*) FROM attendance a JOIN services s ON s.id=a.service_id WHERE a.member_id=? AND s.date>=date('now','-90 days')");
        $ac->execute([$mid]); $att90 = (int)$ac->fetchColumn();
        
        $lg = $db->prepare("SELECT MAX(date) FROM giving WHERE member_id=?"); $lg->execute([$mid]); $lastGift = $lg->fetchColumn();
        $gc = $db->prepare("SELECT COUNT(*) FROM giving WHERE member_id=? AND date>=date('now','-90 days')"); $gc->execute([$mid]); $give90 = (int)$gc->fetchColumn();
        $vol = (int)$db->query("SELECT COUNT(*) FROM volunteers WHERE active=1 AND member_id=$mid")->fetchColumn();
        $grp = (int)$db->query("SELECT COUNT(*) FROM group_members WHERE member_id=$mid")->fetchColumn();

        
        $score = 0;
        
        if ($lastAtt && ($attTs = strtotime((string)$lastAtt)) !== false) { 
            $days = (int)floor(($now - $attTs) / 86400);
            $score += max(0, 35 - intdiv($days, 7) * 5); $sig['days_since_attended'] = $days;
        }
        
        $score += min(20, $att90 * 2); $sig['attendance_90d'] = $att90;
        
        if ($lastGift && ($giftTs = strtotime((string)$lastGift)) !== false) { 
            $gdays = (int)floor(($now - $giftTs) / 86400);
            $score += max(0, 15 - intdiv($gdays, 15) * 3); $sig['days_since_gift'] = $gdays;
        }
        
        $score += min(12, $give90 * 3); $sig['giving_90d'] = $give90;
        
        $score += $vol ? 10 : 0; $score += min(8, $grp * 4);
        $sig['volunteer'] = $vol; $sig['groups'] = $grp;

        
        if (!$lastAtt && !$lastGift && !$vol && !$grp) $score = 60;
        $score = max(0, min(100, (int)round($score)));
        $tier  = engagementTier($score);
        if ($tier === 'at_risk' || $tier === 'critical') $risk++;

        $upd->execute([$score, $tier, $lastAtt ?: ($m['last_attended'] ?? null), $mid]);
        $hist->execute([$mid, $score, $tier, json_encode($sig)]);
        $updated++;
    }
    return ['updated'=>$updated, 'at_risk'=>$risk];
}


function donorSegments(): array {
    $db = getDB();
    $seg = [];
    $seg['first_time'] = $db->query("SELECT m.id,m.first_name,m.last_name,MIN(g.date) d, SUM(g.amount) total FROM giving g JOIN members m ON m.id=g.member_id GROUP BY g.member_id HAVING COUNT(*)=1")->fetchAll();
    $seg['consistent'] = $db->query("SELECT m.id,m.first_name,m.last_name,COUNT(*) c, SUM(g.amount) total FROM giving g JOIN members m ON m.id=g.member_id WHERE g.date>=date('now','-90 days') GROUP BY g.member_id HAVING c>=3 ORDER BY total DESC")->fetchAll();
    $seg['lapsing']    = $db->query("SELECT m.id,m.first_name,m.last_name,MAX(g.date) last_gift, SUM(g.amount) total FROM giving g JOIN members m ON m.id=g.member_id GROUP BY g.member_id HAVING last_gift < date('now','-45 days') AND COUNT(*)>=2 ORDER BY total DESC")->fetchAll();
    $seg['high_potential'] = $db->query("SELECT m.id,m.first_name,m.last_name,m.engagement_score, COALESCE(SUM(g.amount),0) total FROM members m LEFT JOIN giving g ON g.member_id=m.id WHERE m.engagement_score>=70 AND m.status='active' GROUP BY m.id HAVING total < 100 ORDER BY m.engagement_score DESC LIMIT 25")->fetchAll();
    $seg['major']      = $db->query("SELECT m.id,m.first_name,m.last_name,m.engagement_score, SUM(g.amount) total FROM giving g JOIN members m ON m.id=g.member_id WHERE strftime('%Y',g.date)=strftime('%Y','now') GROUP BY g.member_id HAVING total>=1000 ORDER BY total DESC LIMIT 25")->fetchAll();
    return $seg;
}


function runWorkflow(int $wid): array {
    @set_time_limit(0); 
    $db = getDB();
    $st = $db->prepare('SELECT * FROM workflows WHERE id=?'); $st->execute([$wid]);
    $wf = $st->fetch(); if (!$wf) return ['error'=>'Workflow not found'];
    
    switch ($wf['trigger_type']) {
        case 'first_time_visitor': $targets = $db->query("SELECT * FROM members WHERE status='visitor'")->fetchAll(); break;
        case 'engagement_below':   $v=(int)($wf['trigger_value']?:45); $targets=$db->query("SELECT * FROM members WHERE engagement_score<$v AND status='active'")->fetchAll(); break;
        case 'lapsed_giver':       $targets=$db->query("SELECT m.* FROM members m JOIN giving g ON g.member_id=m.id GROUP BY m.id HAVING MAX(g.date)<date('now','-45 days')")->fetchAll(); break;
        case 'birthday':           $targets=$db->query("SELECT * FROM members WHERE strftime('%m-%d',birthdate)=strftime('%m-%d','now')")->fetchAll(); break;
        default:                   $targets = [];
    }
    $actions = json_decode($wf['actions'] ?: '[]', true) ?: [];
    $templates = [
        'welcome'=>['So glad you joined us!','Hi {first_name}, it was wonderful to have you with us at {church_name}. We would love to help you find your place here — reply any time. — {pastor_name}'],
        'we_miss_you'=>['We have been thinking of you','Hi {first_name}, we have missed seeing you at {church_name}. No pressure at all — we just wanted you to know you matter to us. — {pastor_name}'],
        'giving_impact'=>['Thank you for your generosity','Hi {first_name}, your giving has made a real difference at {church_name}. We are grateful for you. — {pastor_name}'],
        'pastor_call'=>['Pastoral follow-up','Personal check-in call for {first_name}.'],
    ];
    $sent = 0; $failed = 0; $log = [];
    foreach ($targets as $m) {
        foreach ($actions as $a) {
            $tpl = $templates[$a['template'] ?? ''] ?? ['Hello','Hi {first_name}, reaching out from {church_name}.'];
            $subject = mergeFields($tpl[0], $m); $body = mergeFields($tpl[1], $m);
            $ch = $a['channel'] ?? 'email'; $err = '';
            if ($ch === 'email' && !empty($m['email'])) {
                $ok = smtpSend($m['email'], $subject, nl2br(h($body)), $err);
                logCommunication((int)$m['id'], 'email', $subject, $body, $ok?'sent':'failed');
                $ok ? $sent++ : $failed++;
            } elseif ($ch === 'sms' && !empty($m['phone'])) {
                $ok = twilioSend($m['phone'], $body, $err);
                logCommunication((int)$m['id'], 'sms', $subject, $body, $ok?'sent':'failed');
                $ok ? $sent++ : $failed++;
            } else { 
                logCommunication((int)$m['id'], $ch, $subject, $body, 'queued');
            }
        }
        $db->prepare('INSERT INTO workflow_runs (workflow_id,member_id,status,log) VALUES (?,?,?,?)')
           ->execute([$wid, (int)$m['id'], 'executed', "Touched ".count($actions)." action(s)"]);
    }
    $db->prepare('UPDATE workflows SET run_count=run_count+?, last_run=CURRENT_TIMESTAMP WHERE id=?')
       ->execute([count($targets), $wid]);
    return ['targets'=>count($targets),'sent'=>$sent,'failed'=>$failed];
}


function upsertMember(array $f, string $source): string {
    $db = getDB();
    $row = null;
    if (!empty($f['external_id'])) {
        $s = $db->prepare('SELECT id FROM members WHERE source=? AND external_id=?'); $s->execute([$source, $f['external_id']]); $row = $s->fetch();
    }
    if (!$row && !empty($f['email'])) { $s = $db->prepare('SELECT id FROM members WHERE email=?'); $s->execute([$f['email']]); $row = $s->fetch(); }
    if ($row) {
        $db->prepare('UPDATE members SET first_name=?,last_name=?,email=COALESCE(NULLIF(?,\'\'),email),phone=COALESCE(NULLIF(?,\'\'),phone),source=?,external_id=? WHERE id=?')
           ->execute([$f['first_name']??'',$f['last_name']??'',$f['email']??'',$f['phone']??'',$source,$f['external_id']??'',$row['id']]);
        return 'updated';
    }
    $db->prepare('INSERT INTO members (first_name,last_name,email,phone,status,source,external_id) VALUES (?,?,?,?,?,?,?)')
       ->execute([$f['first_name']??'',$f['last_name']??'',$f['email']??'',$f['phone']??'',$f['status']??'active',$source,$f['external_id']??'']);
    return 'imported';
}
function logSync(string $source, int $imported, int $updated, string $status, string $msg=''): void {
