        $groupIds=[];
        foreach ($groups as [$gn,$gd,$gt,$gday,$gtime,$gloc]) {
            $leader = $activeIds[array_rand($activeIds)]['id'];
            $db->prepare('INSERT INTO groups (name,description,leader_id,type,meeting_day,meeting_time,location,active,is_demo) VALUES (?,?,?,?,?,?,?,1,1)')
               ->execute([$gn,$gd,$leader,$gt,$gday,$gtime,$gloc]);
            $gid=(int)$db->lastInsertId(); $groupIds[]=$gid;
            $gmIns=$db->prepare('INSERT INTO group_members (group_id,member_id,role,is_demo) VALUES (?,?,?,1)');
            $gmIns->execute([$gid,$leader,'leader']);
            $picks=(array)array_rand(array_flip($allIds), min(mt_rand(7,14),count($allIds)));
            foreach ($picks as $mid) if ($mid!=$leader) $gmIns->execute([$gid,(int)$mid,'member']);
        }

        
        $svcIns=$db->prepare('INSERT INTO services (name,date,type,head_count,is_demo) VALUES (?,?,?,?,1)');
        $attIns=$db->prepare('INSERT OR IGNORE INTO attendance (service_id,member_id,checked_in,is_demo) VALUES (?,?,1,1)');
        $lastSunday = strtotime('last sunday', $today);
        for ($w=25; $w>=0; $w--) {
            $sd=$ymd(strtotime("-$w weeks",$lastSunday));
            $present=[]; foreach ($activeIds as $m) if (mt_rand(1,100) <= mt_rand(48,72)) $present[]=$m['id'];
            $head=count($present)+mt_rand(20,55); 
            $svcIns->execute(["Sunday Mass — ".date('M j',strtotime($sd)), $sd, 'sunday', $head]);
            $sid=(int)$db->lastInsertId();
            foreach ($present as $mid) $attIns->execute([$sid,$mid]);
        }

        
        $gIns=$db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,notes,source,is_demo) VALUES (?,?,?,?,?,?,?,1)');
        $methods=['online','online','online','check','check','cash','card'];
        $giftCount=0; $giverBase=[];
        foreach ($members as $m) $giverBase[$m['id']] = [25,40,50,75,100,125,150,200,250][array_rand([25,40,50,75,100,125,150,200,250])];
        
        $regular = array_slice(array_column($activeIds,'id'), 0, 40);
        for ($w=51; $w>=0; $w--) {
            $date=$ymd(strtotime("-$w weeks", $today));
            foreach ($regular as $mid) {
                if (mt_rand(1,100) > 62) continue; 
                $base=$giverBase[$mid]; $amt=max(10,(int)round($base*(mt_rand(70,160)/100)));
                $fund = mt_rand(1,100)<=68 ? $funds['General Fund'] : $fundIds[array_rand($fundIds)];
                $gIns->execute([$mid,$fund,$amt,$date,$rt($methods),'', 'demo']); $giftCount++;
            }
            
            if (mt_rand(1,100)<=22) { $mid=$regular[array_rand($regular)]; $gIns->execute([$mid,$funds['Building Fund'],mt_rand(1000,5000),$date,'check','Major gift — Building Fund','demo']); $giftCount++; }
        }

        
        $pIns=$db->prepare('INSERT INTO pledges (member_id,fund_id,amount,start_date,end_date,frequency,is_demo) VALUES (?,?,?,?,?,?,1)');
        foreach (array_slice($regular,0,16) as $mid) {
            $f = mt_rand(0,1) ? $funds['Building Fund'] : $funds['Missions'];
            $pIns->execute([$mid,$f,[1200,2400,3600,5000][array_rand([1200,2400,3600,5000])], $ymd(strtotime('-'.mt_rand(1,8).' months',$today)), $ymd(strtotime('+'.mt_rand(4,18).' months',$today)), $rt(['weekly','monthly','quarterly','annually'])]);
        }

        
        $vIns=$db->prepare('INSERT INTO volunteers (member_id,ministry,role,active,is_demo) VALUES (?,?,?,1,1)');
        $ministries=[['Worship & Music','Cantor'],['Worship & Music','Choir'],['Hospitality','Greeter'],['Hospitality','Usher'],['Children','Catechist'],['Youth','Mentor'],['Outreach','Coordinator'],['Tech','A/V Operator'],['Liturgy','Lector'],['Liturgy','Eucharistic Minister']];
        foreach (array_rand(array_flip($allIds), 24) as $mid) { $m=$rt($ministries); $vIns->execute([(int)$mid,$m[0],$m[1]]); }

        
        $eIns=$db->prepare('INSERT INTO events (name,description,start_date,end_date,location,type,capacity,is_demo) VALUES (?,?,?,?,?,?,?,1)');
        $events=[
            ['Parish Festival','Annual food, faith & fellowship celebration', '+18 days','Parish Grounds',600],
            ['Lenten Reflection Evening','Soup supper & guided reflection', '+6 days','Fellowship Hall',120],
            ['Youth Service Day','Edge group serves the local shelter', '+11 days','Community Shelter',40],
            ['First Communion Retreat','Preparation for the sacrament', '+25 days','Sanctuary',60],
            ['Men\'s Prayer Breakfast','Fellowship & Scripture', '+3 days','Fellowship Hall',50],
            ['Choir Concert','Sacred music for the season', '+30 days','Sanctuary',300],
            ['Vacation Bible School','A week of faith & fun for kids', '+45 days','Youth Center',150],
            ['Parish Council Meeting','Monthly leadership meeting', '+8 days','Conference Room',25],
            ['Harvest Food Drive','Collecting for the food pantry', '-5 days','Narthex',0],
            ['Baptism Preparation Class','For new parents', '+14 days','Room 12',30],
        ];
        foreach ($events as [$en,$ed,$off,$eloc,$cap]) { $sd=$ymd(strtotime($off,$today)); $eIns->execute([$en,$ed,$sd.' 18:00',$sd.' 20:00',$eloc,'church',$cap]); }

        
        $prIns=$db->prepare('INSERT INTO prayer_requests (member_id,subject,body,status,private,is_demo) VALUES (?,?,?,?,?,1)');
        $prayers=[['Healing for my mother','Surgery next week — prayers appreciated','active',0],['Safe travels','Mission trip to Guatemala','active',0],['New job','Discernment and provision','active',0],['Marriage','For patience and grace','active',1],['Grief','Loss of a dear friend','active',1],['Expecting a child','Health of mother & baby','active',0],['Employment','Husband seeking work','active',0],['Faith','Returning to the Church','active',1],['Recovery','Sobriety milestone','active',1],['Vocation','Discerning religious life','active',0],['Reconciliation','Healing in our family','active',1],['Thanksgiving','Answered prayer — gratitude!','answered',0]];
        foreach ($prayers as [$ps,$pb,$pst,$ppriv]) $prIns->execute([$allIds[array_rand($allIds)],$ps,$pb,$pst,$ppriv]);

        
        $uid = $_SESSION['user_id'] ?? null;
        $pnIns=$db->prepare('INSERT INTO pastoral_notes (member_id,user_id,note,category,is_demo) VALUES (?,?,?,?,1)');
        $notes=[['Visited in hospital — recovering well','visit'],['Followed up after Mass, wants to join a small group','followup'],['Discussed baptism for newborn','sacrament'],['Bereavement support offered','care'],['New family — connected to Young Families group','welcome'],['Requested help from Benevolence fund','benevolence'],['Interested in becoming a lector','ministry'],['Marriage prep scheduled','sacrament']];
        foreach ($notes as [$nt,$nc]) $pnIns->execute([$activeIds[array_rand($activeIds)]['id'],$uid,$nt,$nc]);

        
        $cIns=$db->prepare("INSERT INTO communications (subject,body,type,audience,status,sent_count,sent_at,is_demo) VALUES (?,?,?,?,'sent',?,?,1)");
        $cIns->execute(['Welcome to Holy Cross!','We are so glad you joined us this Sunday...','email','visitors',12,$ymd(strtotime('-9 days',$today))]);
        $cIns->execute(['This Week at Holy Cross','Mass times, events and the week ahead.','email','all',78,$ymd(strtotime('-3 days',$today))]);
        $cIns->execute(['Reminder: Parish Festival','Join us next weekend!','sms','all',64,$ymd(strtotime('-2 days',$today))]);

        
        $db->prepare('INSERT INTO users (name,email,password,role,status,is_demo) VALUES (?,?,?,?,?,1)')
           ->execute(['Demo User · Holy Cross','demo@holycross.church',password_hash('demo1234',PASSWORD_DEFAULT),'admin','active']);

        $db->commit();
    } catch (\Throwable $e) {
        $db->rollBack();
        return ['ok'=>false, 'error'=>$e->getMessage()];
    }
    
    try { recomputeEngagement(); } catch (\Throwable $e) {}
    return [
        'ok'=>true,
        'members'=> (int)$db->query('SELECT COUNT(*) FROM members WHERE is_demo=1')->fetchColumn(),
        'gifts'=>   (int)$db->query('SELECT COUNT(*) FROM giving WHERE is_demo=1')->fetchColumn(),
        'services'=>(int)$db->query('SELECT COUNT(*) FROM services WHERE is_demo=1')->fetchColumn(),
        'groups'=>  (int)$db->query('SELECT COUNT(*) FROM groups WHERE is_demo=1')->fetchColumn(),
    ];
}


