function computeMetrics(): array {
    $db = getDB();
    $q  = fn(string $sql) => $db->query($sql)->fetchColumn();
    $today = new DateTime('today');
    $doy   = (int)$today->format('z') + 1;            
    $yearFrac = max(0.01, $doy / (365 + (int)$today->format('L')));
    $yr  = $today->format('Y'); $prev = (string)((int)$yr - 1);
    $mmdd = $today->format('m-d');

    $active   = (int)$q("SELECT COUNT(*) FROM members WHERE status='active'");
    $inactive = (int)$q("SELECT COUNT(*) FROM members WHERE status='inactive'");
    $total    = (int)$q("SELECT COUNT(*) FROM members");
    $vols     = (int)$q("SELECT COUNT(*) FROM volunteers WHERE active=1");
    $ytd      = (float)$q("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)='$yr'");
    $prevYtd  = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)='$prev' AND substr(date,6) <= '$mmdd'")->fetchColumn();
    $giftCnt  = (int)$q("SELECT COUNT(*) FROM giving WHERE strftime('%Y',date)='$yr'");
    $donors   = (int)$q("SELECT COUNT(DISTINCT member_id) FROM giving WHERE strftime('%Y',date)='$yr' AND member_id>0");
    $lapsed   = (int)$q("SELECT COUNT(*) FROM (SELECT member_id, MAX(date) m FROM giving WHERE member_id>0 GROUP BY member_id HAVING m < date('now','-60 days') AND COUNT(*)>=2)");
    $engAvg   = (float)$q("SELECT COALESCE(AVG(engagement_score),0) FROM members WHERE status='active'");

    
    $asaRows = $db->query("SELECT head_count FROM services WHERE type='sunday' ORDER BY date DESC LIMIT 8")->fetchAll(PDO::FETCH_COLUMN);
    $asa = $asaRows ? array_sum($asaRows)/count($asaRows) : 0;

    
    $tr = array_reverse($db->query("SELECT head_count FROM services ORDER BY date DESC LIMIT 12")->fetchAll(PDO::FETCH_COLUMN));
    $slope = 0; $n = count($tr);
    if ($n >= 2) {
        $sx=$sy=$sxy=$sxx=0;
        foreach ($tr as $i=>$y) { $sx+=$i; $sy+=$y; $sxy+=$i*$y; $sxx+=$i*$i; }
        $den = ($n*$sxx - $sx*$sx); $slope = $den ? round(($n*$sxy - $sx*$sy)/$den, 2) : 0;
    }

    
    $priorActive = (int)$q("SELECT COUNT(DISTINCT a.member_id) FROM attendance a JOIN services s ON s.id=a.service_id WHERE s.date BETWEEN date('now','-180 days') AND date('now','-90 days')");
    $retained    = (int)$q("SELECT COUNT(DISTINCT a.member_id) FROM attendance a JOIN services s ON s.id=a.service_id WHERE s.date >= date('now','-90 days') AND a.member_id IN (SELECT DISTINCT a2.member_id FROM attendance a2 JOIN services s2 ON s2.id=a2.service_id WHERE s2.date BETWEEN date('now','-180 days') AND date('now','-90 days'))");
    $retention = $priorActive ? ($retained/$priorActive*100) : 0;

    $proj = $ytd / $yearFrac;
    $growth = $prevYtd > 0 ? (($ytd - $prevYtd)/$prevYtd*100) : 0;

    $pct = fn($n) => round($n,1).'%';
    $G = [];
    $G[] = ['Engagement & retention', [
        ['engagement_avg','Avg engagement score', round($engAvg).' / 100', 'Average engagement score across your active members', '70+ healthy'],
        ['retention_90d','90-day retention', $pct($retention), 'Share of recent attenders who also came in the previous 90 days', '80%+ strong'],
        ['attrition','Attrition (inactive share)', $pct($total? $inactive/$total*100:0), 'Share of all members marked inactive', 'under 15%'],
        ['attendance_slope','Attendance trend', ($slope>0?'+':'').$slope.' /service', 'Direction of attendance across your last 12 services', 'positive = growing'],
    ]];
    $G[] = ['Attendance', [
        ['asa','Avg Sunday attendance (ASA)', round($asa), 'Average headcount of your last 8 Sunday services', 'track vs. membership'],
        ['active_members','Active members', (string)$active, 'Members currently marked active', ''],
        ['vol_ratio','Volunteer participation', $pct($active? $vols/$active*100:0), 'Share of active members who serve as volunteers', '10%+ healthy'],
        ['member_vol_ratio','Members per volunteer', $vols? round($active/$vols,1):'—', 'Active members for every volunteer', 'lower = more serving'],
    ]];
    $G[] = ['Giving health', [
        ['ytd','Giving YTD', fmt($ytd), "Total giving received so far in $yr", ''],
        ['proj_annual','Projected annual giving', fmt($proj), 'This year so far, projected to a full year at the current pace', 'vs. budget'],
        ['growth','Giving growth YoY', ($growth>=0?'+':'').$pct($growth), 'Change versus the same point last year', 'positive'],
        ['per_capita','Giving per active member', fmt($active? $ytd/$active:0), 'Giving this year divided by active members', ''],
        ['participation','Giving participation', $pct($active? $donors/$active*100:0), 'Share of active members who have given this year', '60%+ strong'],
        ['avg_gift','Average gift', fmt($giftCnt? $ytd/$giftCnt:0), 'Total giving divided by the number of gifts', ''],
        ['give_per_attender','Giving per attender', fmt($asa? $ytd/($asa*max(1,$doy/7)):0), 'Giving this year per weekly attender', ''],
        ['lapsed','Lapsed givers', (string)$lapsed, 'Regular givers with no gift in 60+ days', 'lower = better'],
    ]];
    return $G;
}


function pulseData(): array {
    $db = getDB();
    $months = [];
    for ($i = 11; $i >= 0; $i--) $months[] = date('Y-m', strtotime(date('Y-m-01') . " -$i month"));
    $skel = array_fill_keys($months, 0.0);
    $fill = function (string $sql) use ($db, $skel) {
        $out = $skel;
        foreach ($db->query($sql)->fetchAll() as $r) { $m = $r['m'] ?? ''; if (isset($out[$m])) $out[$m] = (float)$r['v']; }
        return array_values($out);
    };

    
    $givingSpark  = $fill("SELECT strftime('%Y-%m',date) m, ROUND(SUM(amount),0) v FROM giving WHERE date>=date('now','-1 year','-1 month') GROUP BY m");
    $giversSpark  = $fill("SELECT strftime('%Y-%m',date) m, COUNT(DISTINCT member_id) v FROM giving WHERE member_id>0 AND date>=date('now','-1 year','-1 month') GROUP BY m");
    $joinsSpark   = $fill("SELECT strftime('%Y-%m',created_at) m, COUNT(*) v FROM members WHERE created_at>=date('now','-1 year','-1 month') GROUP BY m");
    $attSpark     = array_values(array_map('intval', array_reverse($db->query("SELECT head_count FROM services WHERE type='sunday' ORDER BY date DESC LIMIT 12")->fetchAll(PDO::FETCH_COLUMN))));

    
    $base = (int)$db->query("SELECT COUNT(*) FROM members WHERE created_at < '" . $months[0] . "-01'")->fetchColumn();
    $cum = []; $run = $base;
    foreach ($months as $idx => $m) { $run += (int)$joinsSpark[$idx]; $cum[] = $run; }

    
    $active    = (int)$db->query("SELECT COUNT(*) FROM members WHERE status='active'")->fetchColumn();
    $asa4      = (float)$db->query("SELECT COALESCE(AVG(head_count),0) FROM services WHERE date>=date('now','-28 days')")->fetchColumn();
    $asaPrev   = (float)$db->query("SELECT COALESCE(AVG(head_count),0) FROM services WHERE date>=date('now','-56 days') AND date<date('now','-28 days')")->fetchColumn();
    $join90    = (int)$db->query("SELECT COUNT(*) FROM members WHERE created_at>=date('now','-90 days')")->fetchColumn();
    $joinPrev  = (int)$db->query("SELECT COUNT(*) FROM members WHERE created_at>=date('now','-180 days') AND created_at<date('now','-90 days')")->fetchColumn();
    $givM      = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y-%m',date)=strftime('%Y-%m','now')")->fetchColumn();
    $givMLast  = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y-%m',date)=strftime('%Y-%m',date('now','-1 year'))")->fetchColumn();
    $givers90  = (int)$db->query("SELECT COUNT(DISTINCT member_id) FROM giving WHERE member_id>0 AND date>=date('now','-90 days')")->fetchColumn();
    $giversPrv = (int)$db->query("SELECT COUNT(DISTINCT member_id) FROM giving WHERE member_id>0 AND date>=date('now','-180 days') AND date<date('now','-90 days')")->fetchColumn();
    $donorsYtd = (int)$db->query("SELECT COUNT(DISTINCT member_id) FROM giving WHERE member_id>0 AND strftime('%Y',date)=strftime('%Y','now')")->fetchColumn();
    $atRisk    = (int)$db->query("SELECT COUNT(*) FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active'")->fetchColumn();
    $engAvg    = (float)$db->query("SELECT COALESCE(AVG(engagement_score),0) FROM members WHERE status='active'")->fetchColumn();
    $priorAtt  = (int)$db->query("SELECT COUNT(DISTINCT a.member_id) FROM attendance a JOIN services s ON s.id=a.service_id WHERE s.date BETWEEN date('now','-180 days') AND date('now','-90 days')")->fetchColumn();
    $retained  = (int)$db->query("SELECT COUNT(DISTINCT a.member_id) FROM attendance a JOIN services s ON s.id=a.service_id WHERE s.date>=date('now','-90 days') AND a.member_id IN (SELECT DISTINCT a2.member_id FROM attendance a2 JOIN services s2 ON s2.id=a2.service_id WHERE s2.date BETWEEN date('now','-180 days') AND date('now','-90 days'))")->fetchColumn();
    $retention = $priorAtt ? $retained / $priorAtt * 100 : 0;
    $participation = $active ? $donorsYtd / $active * 100 : 0;

    $pct = fn($a, $b) => $b > 0 ? round(($a - $b) / $b * 100, 1) : ($a > 0 ? 100.0 : 0.0);
    $trend = function (float $delta, bool $goodUp, string $up, string $down) {
        if (abs($delta) < 0.5) return 'Holding steady.';
        $good = ($delta > 0) === $goodUp;
        return ($delta > 0 ? 'Up ' : 'Down ') . abs($delta) . '% — ' . ($good ? $up : $down) . '.';
    };
    $band = function (float $v, float $strong, float $watch) {
        return $v >= $strong ? ['strong', 'Strong'] : ($v >= $watch ? ['watch', 'Worth watching'] : ['action', 'Needs attention']);
    };

    $M = [];
    
    $dAsa = $pct($asa4, $asaPrev);
    $M[] = ['key'=>'asa','label'=>'Weekly attendance','icon'=>'fa-person-praying','accent'=>'blue','kind'=>'spark',
        'value'=>number_format(round($asa4)),'raw'=>round($asa4),'unit'=>'people','sub'=>'average of the last 4 weeks',
        'goodUp'=>true,'delta'=>$dAsa,'deltaLabel'=>'vs the prior 4 weeks','spark'=>$attSpark,
        'note'=>$trend($dAsa,true,'more people are gathering','attendance is softening')];
    
    $dJoin = $pct($join90, $joinPrev);
    $M[] = ['key'=>'active','label'=>'Active members','icon'=>'fa-users','accent'=>'green','kind'=>'spark',
        'value'=>number_format($active),'raw'=>$active,'unit'=>'members','sub'=>$join90.' joined in the last 90 days',
        'goodUp'=>true,'delta'=>$dJoin,'deltaLabel'=>'new-member pace vs prior 90 days','spark'=>$cum,
        'note'=>$trend($dJoin,true,'your welcome is working','fewer people are joining lately')];
    
    $dNew = $pct($join90, $joinPrev);
    $M[] = ['key'=>'new_people','label'=>'New people (90 days)','icon'=>'fa-hand-holding-heart','accent'=>'violet','kind'=>'spark',
        'value'=>number_format($join90),'raw'=>$join90,'unit'=>'people','sub'=>'first-timers &amp; new members',
        'goodUp'=>true,'delta'=>$dNew,'deltaLabel'=>'vs the prior 90 days','spark'=>$joinsSpark,
        'note'=>$trend($dNew,true,'fresh faces are coming','the front door has slowed')];
    
    [$rC,$rL] = $band($retention, 80, 60);
    $M[] = ['key'=>'retention','label'=>'Member retention','icon'=>'fa-arrows-rotate','accent'=>'teal','kind'=>'gauge',
        'value'=>round($retention,1).'%','raw'=>round($retention,1),'unit'=>'%','sub'=>'still showing up after 90 days',
        'goodUp'=>true,'gaugePct'=>round($retention),'bandClass'=>$rC,'bandLabel'=>$rL,
        'note'=>$retention>=80?'Most of your people are sticking — keep it up.':($retention>=60?'A healthy core stays; a few are drifting.':'Many recent attenders have not returned.')];
    
    $atRiskPct = $active ? $atRisk/$active*100 : 0;
    [$aC,$aL] = $band(100-$atRiskPct, 90, 80); 
    $M[] = ['key'=>'at_risk','label'=>'At-risk members','icon'=>'fa-heart-pulse','accent'=>'amber','kind'=>'gauge',
        'value'=>number_format($atRisk),'raw'=>$atRisk,'unit'=>'members','sub'=>round($atRiskPct,1).'% of active members',
        'goodUp'=>false,'gaugePct'=>round(min(100,$atRiskPct)),'gaugeInvert'=>true,'bandClass'=>$aC,'bandLabel'=>$aL,
        'note'=>$atRiskPct<10?'Very few people are slipping away.':($atRiskPct<20?'A handful need a shepherd\'s call this week.':'A growing group needs personal follow-up now.')];
    
    $dGiv = $pct($givM, $givMLast);
    $M[] = ['key'=>'giving_month','label'=>'Giving this month','icon'=>'fa-dollar-sign','accent'=>'green','kind'=>'spark',
        'value'=>fmtK($givM),'raw'=>round($givM,2),'unit'=>'USD','sub'=>'received so far this month',
        'goodUp'=>true,'delta'=>$dGiv,'deltaLabel'=>'vs the same month last year','spark'=>$givingSpark,
        'note'=>$trend($dGiv,true,'generosity is up year-on-year','giving is behind last year')];
    
    $dPart = $pct($givers90, $giversPrv);
    $M[] = ['key'=>'participation','label'=>'Giving participation','icon'=>'fa-hand-holding-dollar','accent'=>'blue','kind'=>'spark',
        'value'=>round($participation,1).'%','raw'=>round($participation,1),'unit'=>'%','sub'=>$donorsYtd.' of '.$active.' active gave this year',
        'goodUp'=>true,'delta'=>$dPart,'deltaLabel'=>'active givers vs prior 90 days','spark'=>$giversSpark,
        'note'=>$trend($dPart,true,'more households are giving','fewer households are giving')];
    
    [$eC,$eL] = $band($engAvg, 70, 45);
    $M[] = ['key'=>'engagement','label'=>'Engagement score','icon'=>'fa-seedling','accent'=>'navy','kind'=>'gauge',
        'value'=>round($engAvg).' / 100','raw'=>round($engAvg),'unit'=>'/100','sub'=>'average across active members',
        'goodUp'=>true,'gaugePct'=>round($engAvg),'bandClass'=>$eC,'bandLabel'=>$eL,
        'note'=>$engAvg>=70?'Your people are connected and active.':($engAvg>=45?'Engagement is moderate — room to deepen.':'Connection is low — invest in belonging.')];

    
    
    
    $today = new DateTime('today');
    $doy = (int)$today->format('z') + 1;
    $yearFrac = max(0.02, $doy / (365 + (int)$today->format('L')));
    $ytdAll   = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)=strftime('%Y','now')")->fetchColumn();
    $lastYear = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)=strftime('%Y',date('now','-1 year'))")->fetchColumn();

    
    
    $gv = $givingSpark; $n = count($gv);
    $sx=$sy=$sxy=$sxx=0; foreach ($gv as $i=>$y){ $sx+=$i; $sy+=$y; $sxy+=$i*$y; $sxx+=$i*$i; }
    $den = ($n*$sxx - $sx*$sx); $gslope = $den ? ($n*$sxy - $sx*$sy)/$den : 0;
    $gmean = $n ? $sy/$n : 0;
    $trend12 = max(0, $gmean * 12 + $gslope * 6);          
    $paceProj = $ytdAll / $yearFrac;                        
    $proj = round(($trend12 * 0.5) + ($paceProj * 0.5));    
    $projDelta = $lastYear > 0 ? round(($proj - $lastYear) / $lastYear * 100, 1) : 0.0;

    
    
    $atRiskGiving = (float)$db->query("SELECT COALESCE(SUM(g.amount),0) FROM giving g WHERE g.member_id>0 AND g.date>=date('now','-1 year')
        AND g.member_id IN (SELECT member_id FROM giving WHERE member_id>0 GROUP BY member_id HAVING COUNT(*)>=3 AND MAX(date) < date('now','-60 days'))")->fetchColumn();
    $atRiskDonors = (int)$db->query("SELECT COUNT(*) FROM (SELECT member_id FROM giving WHERE member_id>0 GROUP BY member_id HAVING COUNT(*)>=3 AND MAX(date) < date('now','-60 days'))")->fetchColumn();

    
    $donorTotals = $db->query("SELECT COALESCE(SUM(amount),0) tot FROM giving WHERE member_id>0 AND strftime('%Y',date)=strftime('%Y','now') GROUP BY member_id ORDER BY tot DESC")->fetchAll(PDO::FETCH_COLUMN);
    $dCount = count($donorTotals); $dSum = array_sum($donorTotals);
    $topN = max(1, (int)ceil($dCount * 0.10));
    $topSum = array_sum(array_slice($donorTotals, 0, $topN));
    $conc = $dSum > 0 ? round($topSum / $dSum * 100, 1) : 0.0;

    
    $av = $attSpark; $an = count($av);
    $asx=$asy=$asxy=$asxx=0; foreach ($av as $i=>$y){ $asx+=$i; $asy+=$y; $asxy+=$i*$y; $asxx+=$i*$i; }
    $aden = ($an*$asxx - $asx*$asx); $aslope = $aden ? ($an*$asxy - $asx*$asy)/$aden : 0;
    $curAsa = $an ? $av[$an-1] : 0;
    $attProj = max(0, round($curAsa + $aslope * 8));
    $attDelta = $curAsa > 0 ? round(($attProj - $curAsa) / $curAsa * 100, 1) : 0.0;

    $money = fn($v) => fmtK((float)$v);
    $F = [];
    $F[] = ['key'=>'forecast_giving','label'=>'Year-end giving forecast','icon'=>'fa-chart-line','accent'=>'green','goodUp'=>true,
        'value'=>$money($proj),'sub'=>'projected total for '.$today->format('Y'),'delta'=>$projDelta,'deltaLabel'=>'vs last year ('.$money($lastYear).')',
        'note'=>$lastYear<=0 ? 'Building your first full-year baseline.' : ($projDelta>=0 ? 'On pace to finish ahead of last year — stay the course.' : 'Tracking behind last year; a year-end appeal could close the gap.')];
    $F[] = ['key'=>'giving_at_risk','label'=>'Giving at risk','icon'=>'fa-triangle-exclamation','accent'=>'amber','goodUp'=>false,
        'value'=>$money($atRiskGiving),'sub'=>$atRiskDonors.' regular givers have gone quiet (60+ days)','delta'=>null,'deltaLabel'=>'',
        'note'=>$atRiskGiving<=0 ? 'No established givers have lapsed. Wonderful.' : 'This much recurring giving could disappear. A personal call this week often brings it back.'];
    $F[] = ['key'=>'donor_concentration','label'=>'Donor concentration','icon'=>'fa-chart-pie','accent'=>'violet','goodUp'=>false,
        'value'=>$conc.'%','sub'=>'of giving comes from your top '.$topN.' donor'.($topN===1?'':'s'),'delta'=>null,'deltaLabel'=>'',
        'note'=>$conc>=60 ? 'Heavily concentrated — broadening participation protects the budget.' : ($conc>=40 ? 'Moderately concentrated; healthy but worth widening.' : 'Giving is broadly shared across the body. Resilient.')];
    $F[] = ['key'=>'forecast_attendance','label'=>'Attendance forecast','icon'=>'fa-people-arrows','accent'=>'blue','goodUp'=>true,
        'value'=>number_format($attProj),'sub'=>'projected weekly attendance in 8 weeks','delta'=>$attDelta,'deltaLabel'=>'vs today ('.number_format($curAsa).')',
        'note'=>$attDelta>=0 ? 'The trend points upward — keep welcoming and following up.' : 'The trend points down; reach out to recent no-shows before it compounds.'];

    
    $funds   = $db->query("SELECT f.name, COALESCE(SUM(g.amount),0) total FROM funds f LEFT JOIN giving g ON g.fund_id=f.id AND strftime('%Y',g.date)=strftime('%Y','now') GROUP BY f.id ORDER BY total DESC")->fetchAll();
    $engDist = $db->query("SELECT engagement_tier cat, COUNT(*) cnt FROM members WHERE status='active' GROUP BY engagement_tier")->fetchAll();
    $methods = $db->query("SELECT method, SUM(amount) total FROM giving WHERE strftime('%Y',date)=strftime('%Y','now') GROUP BY method")->fetchAll();

    return [
        'church'      => getSetting('church_name') ?: 'Our Church',
        'generated'   => date('F j, Y'),
        'metrics'     => $M,
        'forecast'    => $F,
        'months'      => $months,
        'series'      => ['giving'=>$givingSpark,'givers'=>$giversSpark,'joins'=>$joinsSpark,'membership'=>$cum,'attendance'=>$attSpark],
        'fund_breakdown' => $funds,
        'engagement_dist'=> $engDist,
        'giving_methods' => $methods,
    ];
}




function getStats(): array {
    $db = getDB();
    return [
        'members'    => (int)$db->query("SELECT COUNT(*) FROM members WHERE status='active'")->fetchColumn(),
        'ytd_giving' => (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)=strftime('%Y','now')")->fetchColumn(),
        'services'   => (int)$db->query("SELECT COUNT(*) FROM services WHERE strftime('%Y',date)=strftime('%Y','now')")->fetchColumn(),
        'at_risk'    => (int)$db->query("SELECT COUNT(*) FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active'")->fetchColumn(),
        'groups'     => (int)$db->query("SELECT COUNT(*) FROM groups WHERE active=1")->fetchColumn(),
        'avg_attend' => (float)$db->query("SELECT COALESCE(AVG(head_count),0) FROM services WHERE date>=date('now','-90 days')")->fetchColumn(),
        'this_month' => (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y-%m',date)=strftime('%Y-%m','now')")->fetchColumn(),
        'volunteers' => (int)$db->query("SELECT COUNT(*) FROM volunteers WHERE active=1")->fetchColumn(),
        'visitors'   => (int)$db->query("SELECT COUNT(*) FROM members WHERE status='visitor'")->fetchColumn(),
        'families'   => (int)$db->query("SELECT COUNT(*) FROM families")->fetchColumn(),
    ];
}




function handleAction(string $page, string $action): void {
    $db = getDB();

    
    
    if ($action === 'cron') {
        $ip = clientIp();
        if (rateCount('cronfail:'.$ip, 900) >= 15) { http_response_code(429); echo 'rate limited'; exit; }
        $token = getSetting('cron_token');
        if (!$token || !hash_equals($token, (string)($_GET['token'] ?? $_POST['token'] ?? ''))) { rateHit('cronfail:'.$ip); http_response_code(403); echo 'forbidden'; exit; }
        header('Content-Type: application/json');
        $eng = recomputeEngagement();
        $wf = 0; foreach ($db->query("SELECT id FROM workflows WHERE active=1")->fetchAll() as $w) { runWorkflow((int)$w['id']); $wf++; }
        echo json_encode(['ok'=>true,'engagement'=>$eng,'workflows_run'=>$wf,'at'=>date('c')]); exit;
    }

    
    if ($action === 'manifest') {
        header('Content-Type: application/manifest+json');
        echo json_encode([
            'name'=>getSetting('church_name')?:'Free Church ChMS', 'short_name'=>'Free Church ChMS',
            'description'=>'Free AI church-intelligence platform', 'start_url'=>'./app.php?page=dashboard',
            'scope'=>'./', 'display'=>'standalone', 'orientation'=>'any',
            'background_color'=>'#0f1f4e', 'theme_color'=>'#2E5BFF',
            'icons'=>[
                ['src'=>'assets/icon-192.png','sizes'=>'192x192','type'=>'image/png','purpose'=>'any maskable'],
                ['src'=>'assets/icon-512.png','sizes'=>'512x512','type'=>'image/png','purpose'=>'any maskable'],
            ],
        ]); exit;
    }
    if ($action === 'sw') {
        header('Content-Type: application/javascript');
        echo <<<'JS'
const C='aichurch-v3';const SHELL=['assets/aurora.webp','assets/icon-192.png'];
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(C).then(c=>c.addAll(SHELL).catch(()=>{})))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k)))));self.clients.claim()});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET')return;
  if(/\.(webp|png|jpg|jpeg|svg|css|woff2?)$/.test(u.pathname)){e.respondWith(caches.open(C).then(c=>c.match(e.request).then(r=>r||fetch(e.request).then(x=>{c.put(e.request,x.clone());return x}))));}
});
JS;
        exit;
    }

    
    
    
    
    
    if ($action === 'api') {
        header('Content-Type: application/json');
        header('Access-Control-Allow-Origin: *');
        header('Access-Control-Allow-Headers: Authorization, Content-Type');
        header('Access-Control-Allow-Methods: GET, POST, OPTIONS');
        if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') { http_response_code(204); exit; }
        $ip = clientIp();
        
        if (rateCount('api:'.$ip, 60) >= 240) { http_response_code(429); header('Retry-After: 30'); echo json_encode(['error'=>'Rate limit exceeded — slow down.']); exit; }
        rateHit('api:'.$ip);
        
        if (rateCount('apifail:'.$ip, 900) >= 20) { http_response_code(429); echo json_encode(['error'=>'Too many failed attempts — try again later.']); exit; }
        $key = getSetting('api_key');
        
        
        $auth = $_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? '';
        $given = preg_match('/Bearer\s+(\S+)/i', $auth, $mm) ? $mm[1] : '';
        if (!$key || $given === '' || !hash_equals($key, $given)) { rateHit('apifail:'.$ip); http_response_code(401); echo json_encode(['error'=>'Unauthorized — send your key in the Authorization: Bearer header (Settings → Automation / API).']); exit; }
        $res = $_GET['resource'] ?? ''; $id = (int)($_GET['id'] ?? 0); $method = $_SERVER['REQUEST_METHOD'];
        
        if ($method === 'POST' && getSetting('api_readonly') === '1') { http_response_code(403); echo json_encode(['error'=>'API is in read-only mode — enable writes in Admin → Config & Flags → Security & Access.']); exit; }
        
        $MCOLS = 'id,first_name,last_name,email,phone,address,city,state,zip,birthdate,gender,status,family_id,membership_date,photo_url,engagement_score,engagement_tier,last_attended,source,external_id,created_at';
        $in = json_decode((string)file_get_contents('php://input'), true); if (!is_array($in)) $in = $_POST;
        try {
            switch ($method . ':' . $res) {
                case 'GET:stats': jsonOut(['data'=>getStats()]);
                case 'GET:members':
                    if ($id) { $s=$db->prepare("SELECT $MCOLS FROM members WHERE id=?"); $s->execute([$id]); $r=$s->fetch(); jsonOut($r ?: ['error'=>'Member not found']); }
                    $q='%'.($_GET['q']??'').'%'; $lim=max(1,min(500,(int)($_GET['limit']??100)));
                    $s=$db->prepare("SELECT $MCOLS FROM members WHERE first_name LIKE ? OR last_name LIKE ? OR email LIKE ? ORDER BY last_name,first_name LIMIT $lim");
                    $s->execute([$q,$q,$q]); jsonOut(['data'=>$s->fetchAll()]);
                case 'GET:member': $s=$db->prepare("SELECT $MCOLS FROM members WHERE id=?"); $s->execute([$id]); $r=$s->fetch(); jsonOut($r ?: ['error'=>'Member not found']);
                case 'POST:members':
                    $r = upsertMember(['first_name'=>$in['first_name']??'','last_name'=>$in['last_name']??'','email'=>$in['email']??'','phone'=>$in['phone']??'','status'=>$in['status']??'active','external_id'=>$in['external_id']??''], $in['source'] ?? 'api');
                    fireWebhook('member.created', $in); jsonOut(['ok'=>true,'result'=>$r]);
                case 'GET:giving':
                    $lim=max(1,min(500,(int)($_GET['limit']??100)));
                    jsonOut(['data'=>$db->query("SELECT g.*, m.first_name, m.last_name FROM giving g LEFT JOIN members m ON m.id=g.member_id ORDER BY g.date DESC, g.id DESC LIMIT $lim")->fetchAll()]);
                case 'POST:giving':
                    if (empty($in['amount'])) { http_response_code(422); jsonOut(['error'=>'amount required']); }
                    $db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,source) VALUES (?,?,?,?,?,?)')
                       ->execute([(int)($in['member_id']??0),(int)($in['fund_id']??1),(float)$in['amount'],$in['date']??date('Y-m-d'),$in['method']??'api','api']);
                    fireWebhook('giving.recorded', $in); jsonOut(['ok'=>true,'id'=>(int)$db->lastInsertId()]);
                case 'GET:metrics': jsonOut(['data'=>computeMetrics()]);
                case 'GET:at_risk': jsonOut(['data'=>$db->query("SELECT id,first_name,last_name,email,phone,engagement_score,engagement_tier,last_attended FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active' ORDER BY engagement_score ASC")->fetchAll()]);
                case 'GET:segments': jsonOut(['data'=>donorSegments()]);
                case 'GET:events': jsonOut(['data'=>$db->query("SELECT * FROM events ORDER BY start_date DESC LIMIT 200")->fetchAll()]);
                case 'POST:events':
                    $db->prepare('INSERT INTO events (name,description,start_date,end_date,location,type,capacity) VALUES (?,?,?,?,?,?,?)')
                       ->execute([$in['name']??'Event',$in['description']??'',$in['start_date']??'',$in['end_date']??'',$in['location']??'',$in['type']??'church',(int)($in['capacity']??0)]);
                    jsonOut(['ok'=>true,'id'=>(int)$db->lastInsertId()]);
                case 'POST:engagement_recompute': jsonOut(['ok'=>true,'data'=>recomputeEngagement()]);
                case 'POST:workflow_run': jsonOut(['ok'=>true,'data'=>runWorkflow($id)]);
                case 'GET:verse':
                    $ref=$_GET['ref']??'John 3:16'; $tr=getSetting('bible_api_translation')?:'web';
                    $ch=curl_init('https://bible-api.com/'.rawurlencode($ref).'?translation='.urlencode($tr));
                    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>'AIChurchSDK']);
                    $r=curl_exec($ch); curl_close($ch); $d=json_decode((string)$r,true)?:[];
                    jsonOut(['reference'=>$d['reference']??$ref,'text'=>trim($d['text']??''),'translation'=>$d['translation_name']??$tr]);
                default: http_response_code(404); jsonOut(['error'=>'Unknown endpoint','resource'=>$res,'method'=>$method,'docs'=>APP_URL.'/sdk/']);
            }
        } catch (\Throwable $e) { http_response_code(500); jsonOut(['error'=>$e->getMessage()]); }
    }

    
    if ($action === 'ics') {
        $ip = clientIp();
        if (rateCount('icsfail:'.$ip, 900) >= 20) { http_response_code(429); echo 'rate limited'; exit; }
        $token = getSetting('ics_feed_token');
        if (!$token || !hash_equals($token, (string)($_GET['token'] ?? ''))) { rateHit('icsfail:'.$ip); http_response_code(403); echo 'forbidden'; exit; }
        header('Content-Type: text/calendar; charset=utf-8');
        header('Content-Disposition: inline; filename="aichurch.ics"');
        $cn = getSetting('church_name') ?: 'Free Church ChMS';
        $esc = fn($s) => preg_replace('/([,;\\\\])/', '\\\\$1', str_replace("\n", '\\n', (string)$s));
        $out = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Free Church ChMS//EN\r\nCALSCALE:GREGORIAN\r\nX-WR-CALNAME:" . $esc($cn) . "\r\n";
        foreach ($db->query("SELECT * FROM events ORDER BY start_date DESC LIMIT 200")->fetchAll() as $e) {
            $dt = function($d){ $t = $d ? strtotime((string)$d) : false; return date('Ymd\THis', $t !== false ? $t : time()); }; 
            $out .= "BEGIN:VEVENT\r\nUID:event-{$e['id']}@aichurch\r\nDTSTAMP:" . date('Ymd\THis') . "\r\n";
            $out .= "DTSTART:" . $dt($e['start_date']) . "\r\n";
            if (!empty($e['end_date'])) $out .= "DTEND:" . $dt($e['end_date']) . "\r\n";
            $out .= "SUMMARY:" . $esc($e['name']) . "\r\n";
            if (!empty($e['location'])) $out .= "LOCATION:" . $esc($e['location']) . "\r\n";
            if (!empty($e['description'])) $out .= "DESCRIPTION:" . $esc($e['description']) . "\r\n";
            $out .= "END:VEVENT\r\n";
        }
        echo $out . "END:VCALENDAR\r\n"; exit;
    }

    
    if ($action === 'login') {
        $email = trim($_POST['email'] ?? ''); $pass = $_POST['password'] ?? '';
        $ip = clientIp(); $bIp = 'login_ip:'.$ip;
        if (rateCount($bIp, 900) >= 10) {
            auditLog('login.blocked', $email.' from '.$ip);
            header('Location: ?page=login&err=locked'); exit;
        }
        $st = $db->prepare('SELECT * FROM users WHERE email=?'); $st->execute([$email]); $user = $st->fetch();
        if ($user && ($user['status'] ?? 'active') === 'disabled') { rateHit($bIp); header('Location: ?page=login&err=bad'); exit; }
        
        
        if ($user && in_array($user['email'], ['admin@aichurch.com','admin@sermonassist.com',OWNER_EMAIL], true) && password_verify('admin123', $user['password'])) {
            rateHit($bIp); auditLog('login.default_blocked', $user['email']);
            header('Location: ?page=login&err=default'); exit;
        }
        if ($user && password_verify($pass, $user['password'])) {
            rateClear($bIp);
            if ($user['totp_enabled']) { $_SESSION['totp_pending_user'] = $user['id']; header('Location: ?page=login&stage=2fa'); exit; }
            _doLogin($user);
        }
        rateHit($bIp);
        header('Location: ?page=login&err=bad'); exit;
    }
    if ($action === 'verify_2fa') {
        $ip = clientIp(); $b2 = '2fa:'.$ip;
        if (rateCount($b2, 900) >= 10) { auditLog('2fa.blocked', $ip); header('Location: ?page=login&stage=2fa&err=code'); exit; }
        $uid = $_SESSION['totp_pending_user'] ?? 0; $code = trim($_POST['code'] ?? '');
        if ($uid) {
            $st = $db->prepare('SELECT * FROM users WHERE id=?'); $st->execute([$uid]); $user = $st->fetch();
            if ($user && totpVerify($user['totp_secret'], $code)) { rateClear($b2); unset($_SESSION['totp_pending_user']); _doLogin($user); }
        }
        rateHit($b2);
        header('Location: ?page=login&stage=2fa&err=code'); exit;
    }
    if ($action === 'logout') {
        
        $ltok = (string)($_GET['csrf'] ?? $_POST['csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '');
        if (empty($_SESSION['csrf']) || !hash_equals($_SESSION['csrf'], $ltok)) { header('Location: ?page=dashboard'); exit; }
        $_SESSION = [];
        if (ini_get('session.use_cookies')) { $pp = session_get_cookie_params(); setcookie(session_name(), '', time() - 42000, $pp['path'] ?: '/', $pp['domain'] ?? '', !empty($pp['secure']), true); }
        session_destroy();
        header('Location: ?page=login'); exit;
    }
    if ($action === 'setup_account') {
        $firstRun = isFirstRun();
        $name     = trim($_POST['name'] ?? '');
        $cname    = trim($_POST['church_name'] ?? '');
        $email    = trim($_POST['email'] ?? '');
        $pass     = $_POST['password'] ?? '';
        $pass2    = $_POST['password2'] ?? '';
        $skipOtp  = !empty($_POST['skip_otp']);
        $redirect = $firstRun ? '?page=login&err=' : '?page=login&stage=setup&err=';
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) { header('Location: '.$redirect.'setup_email'); exit; }
        if (strlen($pass) < 8)  { header('Location: '.$redirect.'setup_short'); exit; }
        if ($pass !== $pass2)   { header('Location: '.$redirect.'setup_pw'); exit; }
        
        if (isProtectedOwner($email) && !$firstRun) { header('Location: '.$redirect.'setup_exists'); exit; }
        
        
        if (!$firstRun && getSetting('allow_self_registration') !== '1') {
            header('Location: ?page=login'); exit; 
        }
        
        $existing = $db->prepare('SELECT id FROM users WHERE email=? AND email NOT IN (?,?,?)');
        $existing->execute([$email,'admin@aichurch.com','admin@sermonassist.com',OWNER_EMAIL]); if ($existing->fetch()) { header('Location: '.$redirect.'setup_exists'); exit; }
        if ($firstRun) {
            if ($cname) setSetting('church_name', $cname);
            $db->prepare('DELETE FROM users WHERE email=?')->execute(['admin@aichurch.com']);
        }
        
        $role = $firstRun ? 'superadmin' : 'staff'; 
        $db->prepare('INSERT OR REPLACE INTO users (name,email,password,role,status) VALUES (?,?,?,?,?)')
           ->execute([$name, $email, password_hash($pass, PASSWORD_DEFAULT), $role, 'active']);
        $st = $db->prepare('SELECT * FROM users WHERE email=?'); $st->execute([$email]); $user = $st->fetch();
        auditLog('setup_account', "$name <$email> role=$role");
        
        if ($skipOtp && $firstRun) {
            $_SESSION['user_id'] = $user['id'];
            $_SESSION['user_email'] = $user['email'];
            $_SESSION['user_role'] = $user['role'];
            getDB()->prepare('UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?')->execute([$user['id']]);
            header('Location: ?page=dashboard'); exit;
        }
        
        $secret = totpGenSecret();
        $_SESSION['setup_pending_id']  = (int)$user['id'];
        $_SESSION['setup_totp_secret'] = $secret;
        $_SESSION['setup_totp_uri']    = totpUri($secret, $email, $churchName ?: 'Free Church ChMS');
        $_SESSION['setup_allow_skip']  = $firstRun ? 1 : 0; 
        header('Location: ?page=login&stage=setup_otp'); exit;
    }
    if ($action === 'setup_otp_confirm') {
        $bo = 'otpsetup:'.clientIp();
        if (rateCount($bo, 900) >= 12) { header('Location: ?page=login&stage=setup_otp&err=code'); exit; }
        $uid    = (int)($_SESSION['setup_pending_id']  ?? 0);
        $secret = (string)($_SESSION['setup_totp_secret'] ?? '');
        $code   = trim($_POST['totp_code'] ?? '');
        if (!$uid || !$secret) { header('Location: ?page=login'); exit; }
        if (!totpVerify($secret, $code)) { rateHit($bo); header('Location: ?page=login&stage=setup_otp&err=code'); exit; }
        $db->prepare('UPDATE users SET totp_secret=?,totp_enabled=1 WHERE id=?')->execute([$secret, $uid]);
        $st = $db->prepare('SELECT * FROM users WHERE id=?'); $st->execute([$uid]); $user = $st->fetch();
        unset($_SESSION['setup_pending_id'], $_SESSION['setup_totp_secret'], $_SESSION['setup_totp_uri'], $_SESSION['setup_allow_skip']);
        auditLog('setup_otp_enabled', ($user['email'] ?? ''));
        _doLogin($user);
    }
    if ($action === 'setup_otp_skip') {
        $uid = (int)($_SESSION['setup_pending_id'] ?? 0);
        
        if (!$uid || empty($_SESSION['setup_allow_skip'])) { header('Location: ?page=login&stage=setup_otp'); exit; }
        $st = $db->prepare('SELECT * FROM users WHERE id=?'); $st->execute([$uid]); $user = $st->fetch();
        unset($_SESSION['setup_pending_id'], $_SESSION['setup_totp_secret'], $_SESSION['setup_totp_uri'], $_SESSION['setup_allow_skip']);
        if ($user) _doLogin($user);
        header('Location: ?page=login'); exit;
    }

    
    
    if ($action === 'selfcheckin') {
        $tok = (string)($_GET['t'] ?? $_POST['t'] ?? '');
        $sid = (int)($_GET['service'] ?? $_POST['service'] ?? 0);
        $kioskMode = !empty($_GET['kiosk']) || !empty($_POST['kiosk']);  
        $GLOBALS['ac_kiosk'] = $kioskMode;
        $stored = (string)getSetting('checkin_token');
        $tokenOk = ($stored !== '' && hash_equals($stored, $tok));
        $svc = null;
        if ($tokenOk && $sid) { $q=$db->prepare('SELECT * FROM services WHERE id=?'); $q->execute([$sid]); $svc=$q->fetch() ?: null; }
        
        
        if ($tokenOk && !$sid) {
            $today = date('Y-m-d');
            $q=$db->prepare('SELECT * FROM services WHERE date=? ORDER BY id DESC LIMIT 1'); $q->execute([$today]); $svc=$q->fetch() ?: null;
            if (!$svc) {
                $wd = date('l');
                try {
                    $db->prepare("INSERT INTO services (name,date,type,head_count,created_at) VALUES (?,?,?,0,datetime('now'))")
                       ->execute([$wd.' Service', $today, ($wd==='Sunday'?'sunday':'service')]);
                    $q=$db->prepare('SELECT * FROM services WHERE id=?'); $q->execute([(int)$db->lastInsertId()]); $svc=$q->fetch() ?: null;
                } catch (\Throwable $e) {}
            }
        }
        $sid = $svc ? (int)$svc['id'] : 0;
        $church = getSetting('church_name') ?: 'Our Church';
        $logo = getSetting('church_logo_url');
        $svcDate = $svc ? date('l, F j', strtotime((string)$svc['date']) ?: time()) : '';
        $pg = function(string $inner) use ($church,$logo,$svc,$svcDate) {
            $brand = $logo ? '<img src="'.h($logo).'" alt="" style="max-height:58px;max-width:220px;object-fit:contain;margin:0 auto 10px">' : '';
            if (!headers_sent()) header('Content-Type: text/html; charset=utf-8');
            echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Check in · '.h($church).'</title>'
               .'<link href="?asset=inter_css" rel="stylesheet"><link href="?asset=fa_css" rel="stylesheet">'
               .'<style>*{box-sizing:border-box;margin:0}body{font-family:Inter,system-ui,sans-serif;background:linear-gradient(160deg,#0f1f4e,#2347d9 62%,#6f3de8);min-height:100vh;min-height:100dvh;display:flex;align-items:center;justify-content:center;padding:20px;color:#0f172a}'
               .'.card{background:#fff;border-radius:24px;box-shadow:0 24px 70px rgba(0,0,0,.35);width:min(100%,440px);padding:30px 26px;text-align:center}'
               .'.svc{color:#2E5BFF;font-weight:800;font-size:13px;letter-spacing:.04em;text-transform:uppercase}.dt{color:#6b7280;font-size:13px;margin-top:2px}'
               .'h1{font-size:25px;font-weight:900;letter-spacing:-.02em;margin:14px 0 6px;color:#0f172a}p{color:#4b5563;font-size:15px;line-height:1.6}'
               .'label{display:block;text-align:left;font-size:13px;font-weight:700;color:#374151;margin:12px 0 5px}'
               .'input{width:100%;padding:13px 14px;border:1.5px solid #e5e7eb;border-radius:12px;font-size:16px;font-family:inherit;color:#111827}input:focus{outline:none;border-color:#2E5BFF}'
               .'.row{display:flex;gap:10px}.row>div{flex:1}'
               .'.btn{display:block;width:100%;margin-top:18px;padding:15px;border:none;border-radius:14px;background:linear-gradient(135deg,#2E5BFF,#6f3de8);color:#fff;font-size:16px;font-weight:800;cursor:pointer}'
               .'.tick{width:74px;height:74px;border-radius:50%;background:#10B981;color:#fff;font-size:38px;display:flex;align-items:center;justify-content:center;margin:4px auto 16px}'
               .'.muted{font-size:12px;color:#9ca3af;margin-top:16px}.muted a{color:#2E5BFF}.err{background:#fee2e2;color:#b91c1c;border-radius:10px;padding:10px;font-size:14px;margin-bottom:6px;font-weight:600}'
               .'.hp{position:absolute!important;left:-9999px;width:1px;height:1px}.btn-alt{background:#eef4ff;color:#2347d9;box-shadow:none}.chk{display:flex;gap:9px;align-items:flex-start;text-align:left;font-size:14px;font-weight:600;color:#374151;margin-top:14px;cursor:pointer}.chk input{width:auto;margin-top:2px}.opt{color:#9ca3af;font-weight:400}</style></head><body><div class="card">'
               .$brand
               .($svc ? '<div class="svc">'.h($church).'</div><div class="dt">'.h($svc['name']).' · '.h($svcDate).'</div>' : '<div class="svc">'.h($church).'</div>')
               .$inner.'</div></body></html>';
            exit;
        };
        if (!$tokenOk || !$svc) {
            $pg('<h1>Check-in unavailable</h1><p>This check-in link is invalid or has expired. Please ask a greeter for help. 🙏</p>');
        }
        $known = null;
        if (!$kioskMode && !empty($_COOKIE['ac_chkin'])) {
            $parts = explode('.', (string)$_COOKIE['ac_chkin'], 2); $cid=(int)($parts[0]??0); $sig=$parts[1]??'';
            if ($cid && hash_equals(substr(hash_hmac('sha256', $cid.'|'.$stored, $stored), 0, 16), (string)$sig)) {
                $q=$db->prepare('SELECT id,first_name FROM members WHERE id=?'); $q->execute([$cid]); $known=$q->fetch() ?: null;
            }
        }
        if ($_SERVER['REQUEST_METHOD'] === 'POST' && !empty($_POST['do'])) {
            if (!empty($_POST['website'])) $pg('<h1>Thank you!</h1><p>You\'re all set.</p>'); 
            if (rateCount('selfchk:'.clientIp(), 3600) > 60) $pg('<h1>One moment 🙏</h1><p>We\'ve had a lot of check-ins from this connection. Please ask a greeter to add you.</p>');
            rateHit('selfchk:'.clientIp());
            $mode = $_POST['mode'] ?? 'visitor';
            $mid = 0; $first = ''; $msg = '';
            if ($mode === 'known') {
                $pmid = (int)($_POST['member_id'] ?? 0);
                if ($pmid && $known && (int)$known['id'] === $pmid) { $mid = $pmid; $first = (string)$known['first_name']; }
            } elseif ($mode === 'member') {
                $lookup = trim((string)($_POST['lookup'] ?? ''));
                if ($lookup === '') $pg(selfCheckinForm($svc,$tok,null,'member','Please enter your email or full name.',['lookup'=>''],$church));
                if (strpos($lookup, '@') !== false) { $q=$db->prepare('SELECT id,first_name FROM members WHERE lower(email)=lower(?) LIMIT 1'); $q->execute([$lookup]); }
                else { $p=preg_split('/\s+/', $lookup, 2); $q=$db->prepare('SELECT id,first_name FROM members WHERE lower(first_name)=lower(?) AND lower(last_name)=lower(?) LIMIT 1'); $q->execute([cleanName($p[0]??''), cleanName($p[1]??'')]); }
                if ($r=$q->fetch()) { $mid=(int)$r['id']; $first=(string)$r['first_name']; }
                else $pg(selfCheckinForm($svc,$tok,null,'visitor','We couldn\'t find your record — please check in as a guest below.',[],$church));
            } else { 
                $fn = cleanName((string)($_POST['first_name'] ?? '')); $ln = cleanName((string)($_POST['last_name'] ?? ''));
                $em = strtolower(trim((string)($_POST['email'] ?? ''))); $ph = trim(preg_replace('/\s+/',' ',(string)($_POST['phone'] ?? '')) ?? '');
                $join = !empty($_POST['join']) ? 1 : 0;
                if ($fn === '' || $ln === '') $pg(selfCheckinForm($svc,$tok,null,'visitor','Please enter your first and last name.',['first_name'=>$fn,'last_name'=>$ln,'email'=>$em,'phone'=>$ph],$church));
                if ($em !== '') { $q=$db->prepare('SELECT id,first_name FROM members WHERE lower(email)=lower(?) LIMIT 1'); $q->execute([$em]); if($r=$q->fetch()){$mid=(int)$r['id'];$first=(string)$r['first_name'];} }
                if (!$mid) { $q=$db->prepare('SELECT id,first_name FROM members WHERE lower(first_name)=lower(?) AND lower(last_name)=lower(?) LIMIT 1'); $q->execute([$fn,$ln]); if($r=$q->fetch()){$mid=(int)$r['id'];$first=(string)$r['first_name'];} }
                if (!$mid) {
                    
                    $db->prepare('INSERT INTO members (first_name,last_name,email,phone,status,source,membership_date,needs_review,wants_membership) VALUES (?,?,?,?,?,?,date(\'now\'),1,?)')->execute([$fn,$ln,$em,$ph,'visitor','self_checkin',$join]);
                    $mid=(int)$db->lastInsertId(); $first=$fn;
                    $msg = $join ? 'Thank you! We\'d love to have you — someone from '.h($church).' will reach out about becoming a member.' : 'You can put your phone away. Someone may stop by to say hello and welcome you!';
                } else {
                    $db->prepare('UPDATE members SET email=CASE WHEN COALESCE(email,\'\')=\'\' THEN ? ELSE email END, phone=CASE WHEN COALESCE(phone,\'\')=\'\' THEN ? ELSE phone END'.($join?', wants_membership=1, needs_review=1':'').' WHERE id=?')->execute([$em,$ph,$mid]);
                }
            }
            if (!$mid) $pg(selfCheckinForm($svc,$tok,$known,'choose','Sorry — something went wrong. Please try again.',[],$church));
            $db->prepare('INSERT OR IGNORE INTO attendance (service_id,member_id) VALUES (?,?)')->execute([$sid,$mid]);
            $db->prepare('UPDATE services SET head_count=(SELECT COUNT(*) FROM attendance WHERE service_id=?) WHERE id=?')->execute([$sid,$sid]);
            $db->prepare('UPDATE members SET last_attended=date(\'now\') WHERE id=?')->execute([$mid]);
            if (!$kioskMode) @setcookie('ac_chkin', $mid.'.'.substr(hash_hmac('sha256',$mid.'|'.$stored,$stored),0,16), time()+60*60*24*120, '/', '', !empty($_SERVER['HTTPS']), false);
            if ($kioskMode) {
                $kHome = '?action=selfcheckin&service='.$sid.'&kiosk=1&t='.rawurlencode($tok);
                $reset = '<a class="btn btn-alt" href="'.h($kHome).'"><i class="fa-solid fa-arrow-rotate-right"></i> Check in the next person</a>'
                       .'<div class="muted">Returning to the welcome screen…</div>'
                       .'<script>setTimeout(function(){location.href='.json_encode($kHome).';},6000);</script>';
            } else {
                $reset = '<div class="muted">Recorded to '.h($svc['name']).'.</div>';
            }
            $pg('<div class="tick">✓</div><h1>You\'re checked in'.($first?', '.h($first):'').'!</h1><p>'.($msg ?: 'Welcome — so glad you\'re here today. 🙌').'</p>'.$reset);
        }
        if ($known && !isset($_GET['new']) && !isset($_GET['as'])) $pg(selfCheckinForm($svc, $tok, $known, 'choose', '', [], $church));
        $step = in_array($_GET['as'] ?? '', ['member','visitor'], true) ? $_GET['as'] : 'choose';
        $pg(selfCheckinForm($svc, $tok, null, $step, '', [], $church));
    }

    requireLogin();

    
    
    
    
    
    $tok = (string)($_POST['csrf'] ?? $_GET['csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '');
    if (empty($_SESSION['csrf']) || !hash_equals($_SESSION['csrf'], $tok)) {
        http_response_code(403);
        if (in_array($action, ['ai_chat','ai_generate_content','generate_report','ai_explain_metrics','analytics_data','pulse_data','ai_pulse_insight','witness_ai','save_claude','save_integration','save_comm','console_exec','set_theme','mute_pastoral_alerts','upload_church_logo','remove_church_logo','test_anthropic','bible_verse'], true) || preg_match('/^(sync_|test_)/', $action)) jsonOut(['error'=>'Session expired — please refresh the page.']);
        exit('CSRF check failed — refresh the page and try again.');
    }

    
    
    
    if (preg_match('/^(sync_|test_)/', $action)) { requireAdmin(); @set_time_limit(120); } 

    
    if ($action === 'totp_setup_init') {
        $secret = totpGenSecret(); $_SESSION['totp_pending_secret'] = $secret;
        header('Location: ?page=settings#twofa'); exit;
    }
    if ($action === 'totp_setup_confirm') {
        $code = trim($_POST['totp_code'] ?? $_POST['code'] ?? ''); $secret = $_SESSION['totp_pending_secret'] ?? '';
        if (!$secret || !totpVerify($secret, $code)) { header('Location: ?page=settings&err=' . urlencode('Code incorrect — try again.') . '#twofa'); exit; }
        $db->prepare('UPDATE users SET totp_secret=?,totp_enabled=1 WHERE id=?')->execute([$secret, $_SESSION['user_id']]);
        unset($_SESSION['totp_pending_secret']);
        header('Location: ?page=settings&ok=' . urlencode('Two-factor authentication enabled.')); exit;
    }
    if ($action === 'totp_disable') {
        $user = currentUser();
        if ($user && password_verify($_POST['password'] ?? '', $user['password'])) {
            $db->prepare('UPDATE users SET totp_secret=NULL,totp_enabled=0 WHERE id=?')->execute([$_SESSION['user_id']]);
            header('Location: ?page=settings&ok=' . urlencode('2FA disabled.')); exit;
        }
        header('Location: ?page=settings&err=' . urlencode('Incorrect password.')); exit;
    }

    
    if ($action === 'save_member') {
        $id = (int)($_POST['id'] ?? 0);
        $f = ['first_name','last_name','email','phone','address','city','state','zip','birthdate','gender','status','membership_date','notes'];
        $data = []; foreach ($f as $k) $data[$k] = trim($_POST[$k] ?? '');
        if ($id) {
            $sets = implode(',', array_map(fn($k)=>"$k=?", $f)); $vals = array_values($data); $vals[] = $id;
            $db->prepare("UPDATE members SET $sets WHERE id=?")->execute($vals);
        } else {
            $cols = implode(',', $f); $phs = implode(',', array_fill(0, count($f), '?'));
            $db->prepare("INSERT INTO members ($cols) VALUES ($phs)")->execute(array_values($data));
        }
        header('Location: ?page=members&ok=' . urlencode('Member saved.')); exit;
    }
    if ($action === 'delete_member') { $db->prepare('DELETE FROM members WHERE id=?')->execute([(int)$_POST['id']]); header('Location: ?page=members&ok=Deleted'); exit; }
    if ($action === 'upload_member_photo') {
        $id = (int)$_POST['id'];
        if ($id && !empty($_FILES['photo']['tmp_name']) && is_uploaded_file($_FILES['photo']['tmp_name'])) {
            $dir = __DIR__ . '/uploads/members'; @mkdir($dir, 0775, true);
            $info = @getimagesize($_FILES['photo']['tmp_name']);
            $extMap = [IMAGETYPE_JPEG=>'jpg', IMAGETYPE_PNG=>'png', IMAGETYPE_WEBP=>'webp', IMAGETYPE_GIF=>'gif'];
            if ($info && isset($extMap[$info[2]]) && $_FILES['photo']['size'] <= 6*1024*1024) {
                $fn = 'm' . $id . '_' . bin2hex(random_bytes(5)) . '.' . $extMap[$info[2]];
                if (move_uploaded_file($_FILES['photo']['tmp_name'], "$dir/$fn"))
                    $db->prepare('UPDATE members SET photo_url=? WHERE id=?')->execute(['uploads/members/'.$fn, $id]);
            } else { header('Location: ?page=members&edit='.$id.'&err=' . urlencode('Use a JPG/PNG/WEBP/GIF under 6 MB.')); exit; }
        }
        header('Location: ?page=members&edit='.$id.'&ok=Photo+updated'); exit;
    }

    
    if ($action === 'upload_church_logo') {
        requireAdmin();
        $ajax = ($_POST['ajax'] ?? '') === '1';
        if (!empty($_FILES['logo']['tmp_name']) && is_uploaded_file($_FILES['logo']['tmp_name'])) {
            $dir = __DIR__ . '/uploads/branding'; @mkdir($dir, 0775, true);
            $info = @getimagesize($_FILES['logo']['tmp_name']);
            $extMap = [IMAGETYPE_JPEG=>'jpg', IMAGETYPE_PNG=>'png', IMAGETYPE_WEBP=>'webp', IMAGETYPE_GIF=>'gif'];
            if ($info && isset($extMap[$info[2]]) && $_FILES['logo']['size'] <= 4*1024*1024) {
                $fn = 'logo_' . bin2hex(random_bytes(6)) . '.' . $extMap[$info[2]];
                if (move_uploaded_file($_FILES['logo']['tmp_name'], "$dir/$fn")) {
                    $url = 'uploads/branding/'.$fn; setSetting('church_logo_url', $url); auditLog('branding.logo', $fn);
                    if ($ajax) jsonOut(['ok'=>true,'url'=>$url]);
                }
            } else { if ($ajax) jsonOut(['ok'=>false,'error'=>'Use a PNG/JPG/WEBP/GIF under 4 MB.']); header('Location: ?page=settings&err=' . urlencode('Use a PNG/JPG/WEBP/GIF under 4 MB.')); exit; }
        }
        if ($ajax) jsonOut(['ok'=>false,'error'=>'No file received.']);
        header('Location: ?page=settings&ok=Logo+updated'); exit;
    }
    if ($action === 'remove_church_logo') {
        requireAdmin(); setSetting('church_logo_url',''); auditLog('branding.logo','removed');
        if (($_POST['ajax'] ?? '') === '1') jsonOut(['ok'=>true]);
        header('Location: ?page=settings&ok=Logo+removed'); exit;
    }

    
    if ($action === 'add_pastoral_note') {
        $db->prepare('INSERT INTO pastoral_notes (member_id,user_id,note,category) VALUES (?,?,?,?)')
           ->execute([(int)$_POST['member_id'], $_SESSION['user_id'], trim($_POST['note'] ?? ''), $_POST['category'] ?? 'general']);
        header('Location: ?page=pastoral&ok=Note+added'); exit;
    }
    if ($action === 'save_prayer') {
        $db->prepare('INSERT INTO prayer_requests (member_id,subject,body,private) VALUES (?,?,?,?)')
           ->execute([(int)($_POST['member_id'] ?: 0), trim($_POST['subject'] ?? ''), trim($_POST['body'] ?? ''), isset($_POST['private'])?1:0]);
        header('Location: ?page=pastoral&ok=Prayer+request+added'); exit;
    }

    
    if ($action === 'save_giving') {
        $db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,check_number,notes) VALUES (?,?,?,?,?,?,?)')
           ->execute([(int)$_POST['member_id'], (int)$_POST['fund_id'], (float)$_POST['amount'], $_POST['date'], $_POST['method']??'check', $_POST['check_number']??'', $_POST['notes']??'']);
        header('Location: ?page=giving&ok=Gift+recorded'); exit;
    }
