    if ($action === 'send_communication') {
        
        
        
        @set_time_limit(0); ignore_user_abort(true);
        $id = (int)$_POST['id'];
        $c = $db->prepare('SELECT * FROM communications WHERE id=?'); $c->execute([$id]); $msg = $c->fetch();
        if (!$msg) { header('Location: ?page=communications&err=Not+found'); exit; }
        $recips = audienceMembers($msg['audience'] ?: 'all'); $sent=0; $fail=0; $i=0;
        $db->prepare("UPDATE communications SET status='sending' WHERE id=?")->execute([$id]);
        $dedup = $db->prepare("SELECT 1 FROM communication_log WHERE member_id=? AND subject=? AND status='sent' LIMIT 1");
        foreach ($recips as $m) {
            $body = mergeFields($msg['body'], $m); $subj = mergeFields($msg['subject'], $m); $err='';
            $dedup->execute([(int)$m['id'], $subj]); if ($dedup->fetchColumn()) { continue; } 
            if ($msg['type'] === 'sms') {
                if (empty($m['phone'])) { continue; }
                $ok = twilioSend($m['phone'], strip_tags($body), $err);
                logCommunication((int)$m['id'],'sms',$subj,$body,$ok?'sent':'failed');
            } else {
                if (empty($m['email'])) { continue; }
                $ok = smtpSend($m['email'], $subj, nl2br(h($body)), $err); 
                logCommunication((int)$m['id'],'email',$subj,$body,$ok?'sent':'failed');
            }
            $ok ? $sent++ : $fail++;
            if ((++$i % 25) === 0) $db->prepare('UPDATE communications SET sent_count=?,fail_count=? WHERE id=?')->execute([$sent,$fail,$id]); 
        }
        $db->prepare('UPDATE communications SET status=?,sent_count=?,fail_count=?,sent_at=CURRENT_TIMESTAMP WHERE id=?')->execute(['sent',$sent,$fail,$id]);
        header('Location: ?page=communications&ok=' . urlencode("Sent to $sent recipient(s)" . ($fail?", $fail failed":'') . '.')); exit;
    }
