        $ok = smtpSend($to, 'Free Church ChMS test email', '<p>This is a test email from your Free Church ChMS platform. SMTP is working. ✅</p>', $err);
        if ($ajax) jsonOut(['ok'=>$ok, 'message'=>"Sent to $to", 'error'=>$err ?: 'Send failed — check your SMTP settings.']);
