        if (!$key) jsonOut(['ok'=>false,'error'=>'Enter your Anthropic API key first.']);
        $payload = json_encode(['model'=>$model,'max_tokens'=>16,'messages'=>[['role'=>'user','content'=>'Reply with exactly one word: connected']]]);
        $ch = curl_init('https://api.anthropic.com/v1/messages');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$payload,
            CURLOPT_HTTPHEADER=>['x-api-key: '.$key,'anthropic-version: 2023-06-01','content-type: application/json'], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code === 200) { $d = json_decode((string)$res, true); jsonOut(['ok'=>true,'model'=>$d['model']??$model,'reply'=>trim($d['content'][0]['text']??'connected')]); }
        $e = json_decode((string)$res, true);
        jsonOut(['ok'=>false,'error'=>$e['error']['message'] ?? ("Anthropic API error $code" . ($code===401?' — check your key.':''))]);
