        auditLog('pastoral_alerts.'.($muted==='1'?'muted':'unmuted'), '');
        jsonOut(['ok'=>true, 'muted'=>$muted==='1']);
    }
    
    if ($action === 'save_claude') {
        requireAdmin();
        $key = trim($_POST['key'] ?? '');
        $model = trim($_POST['model'] ?? '');
        if ($key !== '') setSetting('anthropic_api_key', $key);
        if ($model !== '') setSetting('ai_model', $model);
        jsonOut(['ok'=>true, 'saved'=>($key!==''), 'model'=>$model ?: getSetting('ai_model')]);
    }
    
    if ($action === 'save_integration') {
        requireAdmin();
        $allowed = integrationKeys();      
        $n = 0;
        foreach ($allowed as $k) { if (array_key_exists($k, $_POST)) { setSetting($k, trim((string)$_POST[$k])); $n++; } }
        jsonOut(['ok'=>true, 'saved'=>$n]);
    }
    
    if ($action === 'save_comm') {
        requireAdmin();
        $allowed = ['smtp_host','smtp_port','smtp_user','smtp_pass','smtp_from','smtp_from_name','smtp_secure','twilio_sid','twilio_token','twilio_from'];
        $n = 0;
        foreach ($allowed as $k) { if (array_key_exists($k, $_POST)) { setSetting($k, trim((string)$_POST[$k])); $n++; } }
        jsonOut(['ok'=>true, 'saved'=>$n]);
    }
    
    if ($action === 'revoke_claude') {
        requireAdmin();
        setSetting('anthropic_api_key', '');
        auditLog('claude_key.released', '');
        jsonOut(['ok'=>true]);
    }
    
    
    
    if ($action === 'console_exec') {
        requireAdmin();
        $line = trim((string)($_POST['cmd'] ?? ''));
        if ($line === '') jsonOut(['ok'=>true,'kind'=>'text','text'=>'']);
        $sp   = strpos($line, ' ');
        $cmd  = strtolower($sp === false ? $line : substr($line, 0, $sp));
        $arg  = $sp === false ? '' : trim(substr($line, $sp + 1));
        $mask = fn($v) => (strlen((string)$v) <= 6 ? '••••••' : substr($v,0,3).'••••••'.substr($v,-3));
        $isSecret = fn($k) => (bool)preg_match('/(key|secret|token|pass|password|sid|hash|salt)/i', (string)$k);
        $tables = fn() => array_column($db->query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")->fetchAll(), 'name');
        try {
            switch ($cmd) {
              case 'help': case '?':
                jsonOut(['ok'=>true,'kind'=>'text','text'=>
                  "Free Church ChMS Console — safe, read-only. It runs a fixed set of whitelisted commands\n"
                 ."in-process; it is NOT a shell and cannot run arbitrary code.\n\n"
                 ."  help                  this list\n"
                 ."  version               app / PHP / SQLite versions\n"
                 ."  whoami                the signed-in user\n"
                 ."  tables                every table + row count\n"
                 ."  schema [table]        CREATE statement(s) for a table (or all)\n"
                 ."  indexes               every index and its table\n"
                 ."  count <table>         rows in one table\n"
                 ."  select <query>        run ONE read-only SELECT (auto-capped at 200 rows)\n"
                 ."  settings              all settings (secrets masked)\n"
                 ."  setting <key>         one setting (masked if secret)\n"
                 ."  stats                 live church statistics\n"
                 ."  diagnostics           backend capability check\n"
                 ."  integrations          integration catalog + configured?\n"
                 ."  pages                 every app route\n"
                 ."  php                   PHP version, limits & loaded extensions\n"
                 ."  clear                 clear the screen"]);
              case 'version':
                jsonOut(['ok'=>true,'kind'=>'text','text'=>"Free Church ChMS v".APP_VERSION."\nPHP ".PHP_VERSION."\nSQLite ".$db->query('SELECT sqlite_version()')->fetchColumn()]);
              case 'whoami':
                $u = currentUser() ?: []; jsonOut(['ok'=>true,'kind'=>'text','text'=>($u['name']??'?')." <".($u['email']??'?')."> — role: ".($u['role']??'?')]);
              case 'tables':
                $rows = []; foreach ($tables() as $t) $rows[] = [$t, (int)$db->query('SELECT COUNT(*) FROM "'.$t.'"')->fetchColumn()];
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['table','rows'],'rows'=>$rows,'note'=>count($rows).' tables']);
              case 'schema':
                if ($arg !== '') {
                    if (!in_array($arg, $tables(), true)) jsonOut(['ok'=>false,'error'=>"Unknown table: $arg"]);
                    jsonOut(['ok'=>true,'kind'=>'text','text'=>(string)$db->query("SELECT sql FROM sqlite_master WHERE name=".$db->quote($arg)." AND type='table'")->fetchColumn()]);
                }
                $all = $db->query("SELECT sql FROM sqlite_master WHERE type='table' AND sql IS NOT NULL ORDER BY name")->fetchAll(PDO::FETCH_COLUMN);
                jsonOut(['ok'=>true,'kind'=>'text','text'=>implode(";\n\n", $all).';']);
              case 'indexes':
                $rows = []; foreach ($db->query("SELECT name,tbl_name FROM sqlite_master WHERE type='index' ORDER BY tbl_name,name")->fetchAll() as $r) $rows[] = [$r['name'], $r['tbl_name']];
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['index','table'],'rows'=>$rows,'note'=>count($rows).' indexes']);
              case 'count':
                if (!in_array($arg, $tables(), true)) jsonOut(['ok'=>false,'error'=>"Unknown table: ".($arg ?: '(none given)')]);
                jsonOut(['ok'=>true,'kind'=>'text','text'=>$arg.': '.(int)$db->query('SELECT COUNT(*) FROM "'.$arg.'"')->fetchColumn().' rows']);
              case 'select': case 'sql': case 'query':
                $q = trim(preg_replace('/^(sql|query)\s+/i', '', $line)); 
                if ($q === '' || preg_match('/^select\s*$/i', $q)) jsonOut(['ok'=>false,'error'=>'Usage: select <query>   e.g. select first_name,last_name from members']);
                if (!preg_match('/^select\b/i', $q)) jsonOut(['ok'=>false,'error'=>'Only SELECT queries are allowed in the console.']);
                if (strpos($q, ';') !== false) jsonOut(['ok'=>false,'error'=>'One statement only — remove the semicolon.']);
                if (preg_match('/\b(attach|detach|pragma|insert|update|delete|drop|alter|create|replace|vacuum|reindex|load_extension)\b/i', $q)) jsonOut(['ok'=>false,'error'=>'That keyword is not permitted in the read-only console.']);
                if (!preg_match('/\blimit\b/i', $q)) $q .= ' LIMIT 200';
                $data = $db->query($q)->fetchAll(PDO::FETCH_ASSOC);
                if (!$data) jsonOut(['ok'=>true,'kind'=>'text','text'=>'(0 rows)']);
                $cols = array_keys($data[0]); $rows = [];
                foreach ($data as $r) { $row = []; foreach ($cols as $c) { $v = (string)($r[$c] ?? ''); if ($isSecret($c) && $v !== '') $v = $mask($v); if (strlen($v) > 140) $v = substr($v,0,137).'…'; $row[] = $v; } $rows[] = $row; }
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>$cols,'rows'=>$rows,'note'=>count($data).' row(s)']);
              case 'settings':
                $rows = []; foreach ($db->query("SELECT key,value FROM settings ORDER BY key")->fetchAll() as $r) { $v = (string)$r['value']; if ($isSecret($r['key']) && $v !== '') $v = $mask($v); if (strlen($v) > 140) $v = substr($v,0,137).'…'; $rows[] = [$r['key'], $v]; }
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['key','value'],'rows'=>$rows,'note'=>count($rows).' keys']);
              case 'setting':
                if ($arg === '') jsonOut(['ok'=>false,'error'=>'Usage: setting <key>']);
                $v = (string)getSetting($arg);
                if ($v === '') jsonOut(['ok'=>true,'kind'=>'text','text'=>"$arg = (empty)"]);
                jsonOut(['ok'=>true,'kind'=>'text','text'=>"$arg = ".($isSecret($arg) ? $mask($v) : $v)]);
              case 'stats':
                $rows = []; foreach (getStats() as $k=>$v) if (is_scalar($v)) $rows[] = [$k, (string)$v];
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['metric','value'],'rows'=>$rows]);
              case 'diagnostics': case 'health':
                $rows = []; foreach (systemDiagnostics() as $d) $rows[] = [(string)($d[0]??''), !empty($d[1]) ? 'OK' : 'MISSING', (string)($d[2]??'')];
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['capability','status','detail'],'rows'=>$rows]);
              case 'integrations':
                $rows = []; foreach (integrationCatalog() as $cat=>$items) foreach ($items as $it) { $conf = 'no'; foreach (array_column($it[6],0) as $k) { if ((string)getSetting($k) !== '') { $conf = 'yes'; break; } } $rows[] = [(string)$it[1], (string)$cat, $conf]; }
                jsonOut(['ok'=>true,'kind'=>'table','cols'=>['integration','category','configured'],'rows'=>$rows,'note'=>count($rows).' integrations']);
              case 'pages': case 'routes':
                jsonOut(['ok'=>true,'kind'=>'text','text'=>"App routes (?page=…):\n  ".wordwrap(implode(', ', ['dashboard','analytics','insights','members','groups','attendance','events','volunteers','pastoral','pipeline','giving','donors','pledges','communications','workflows','aistudio','ai','streaming','checkin','worship','accounting','reports','tools','integrations','resources','kb','settings','console','migrate','admin','admin_requests','admin_users','admin_churches','admin_licenses','admin_config','admin_audit']), 74, "\n  ")]);
              case 'php':
                $ext = get_loaded_extensions(); sort($ext);
                jsonOut(['ok'=>true,'kind'=>'text','text'=>"PHP ".PHP_VERSION." on ".PHP_OS."\nmemory_limit=".ini_get('memory_limit')."  max_execution_time=".ini_get('max_execution_time')."  upload_max_filesize=".ini_get('upload_max_filesize')."  post_max_size=".ini_get('post_max_size')."\n\nLoaded extensions (".count($ext)."):\n  ".wordwrap(implode(', ', $ext), 74, "\n  ")]);
              case 'clear':
                jsonOut(['ok'=>true,'kind'=>'clear']);
              default:
                jsonOut(['ok'=>false,'error'=>"Unknown command: $cmd   — type 'help' for the list."]);
            }
        } catch (\Throwable $e) {
            jsonOut(['ok'=>false,'error'=>'Error: '.$e->getMessage()]);
        }
    }
    if ($action === 'change_password') {
        $user = currentUser();
        if (strlen($_POST['new_password'] ?? '') < 8) { header('Location: ?page=settings&err=' . urlencode('New password must be at least 8 characters.')); exit; }
        if ($user && password_verify($_POST['current_password'] ?? '', $user['password'])) {
            $db->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['new_password'], PASSWORD_DEFAULT), $user['id']]);
            header('Location: ?page=settings&ok=' . urlencode('Password updated.')); exit;
        }
        header('Location: ?page=settings&err=' . urlencode('Current password incorrect.')); exit;
    }

    
    if (str_starts_with($action, 'admin_')) {
        requireAdmin();
        if ($action === 'admin_save_security') {
            setSetting('allow_self_registration', !empty($_POST['allow_self_registration']) ? '1' : '0');
            setSetting('api_readonly', !empty($_POST['api_readonly']) ? '1' : '0');
            auditLog('security.policy', 'self_reg='.(!empty($_POST['allow_self_registration'])?'on':'off').' api_readonly='.(!empty($_POST['api_readonly'])?'on':'off'));
            header('Location: ?page=admin_config&ok='.urlencode('Security settings saved.')); exit;
        }
        if ($action === 'admin_rotate_api_key') {
            $new = 'sk_church_'.bin2hex(random_bytes(20));
            setSetting('api_key', $new);
            auditLog('api_key.rotated', '');
            header('Location: ?page=settings&ok='.urlencode('API key rotated — update your integrations with the new key.').'#apikey'); exit;
        }
        
        if ($action === 'admin_approve_request') {
            $rid=(int)($_POST['id']??0);
            $r=$db->prepare('SELECT * FROM access_requests WHERE id=?'); $r->execute([$rid]); $req=$r->fetch();
            if(!$req){ header('Location: ?page=admin_requests&err='.urlencode('Request not found.')); exit; }
            
            $role=in_array($_POST['role']??'staff',['admin','staff','readonly'],true)?$_POST['role']:'staff';
            $email=$req['email']; $name=$req['name'];
            $ex=$db->prepare('SELECT id FROM users WHERE email=?'); $ex->execute([$email]);
            if($ex->fetch()){
                $db->prepare("UPDATE access_requests SET status='approved',reviewed_at=CURRENT_TIMESTAMP,reviewed_by=? WHERE id=?")->execute([$_SESSION['user_id'],$rid]);
                header('Location: ?page=admin_requests&ok='.urlencode("$email already has an account — request marked approved.")); exit;
            }
            $tmp=bin2hex(random_bytes(5)); 
            $db->prepare('INSERT INTO users (name,email,password,role,status,created_by) VALUES (?,?,?,?,?,?)')
               ->execute([$name,$email,password_hash($tmp,PASSWORD_DEFAULT),$role,'active',$_SESSION['user_id']]);
            $db->prepare("UPDATE access_requests SET status='approved',reviewed_at=CURRENT_TIMESTAMP,reviewed_by=? WHERE id=?")->execute([$_SESSION['user_id'],$rid]);
            auditLog('access.approve',"$email role=$role");
            
            $sent=false;
            if(getSetting('smtp_host')){ $e2=''; $body="Hello $name,\n\nYour Free Church ChMS account is ready.\n\nSign in: ".APP_URL."/app.php\nEmail: $email\nTemporary password: $tmp\n\nPlease change your password after signing in.\n\nSoli Deo Gloria."; $sent=smtpSend($email,'Your Free Church ChMS access is ready', nl2br(h($body)), $e2); }
            
            $_SESSION['provisioned']=['email'=>$email,'pw'=>$tmp,'role'=>$role,'sent'=>$sent];
            header('Location: ?page=admin_requests&ok=provisioned'); exit;
        }
        if ($action === 'admin_deny_request') {
            $db->prepare("UPDATE access_requests SET status='denied',reviewed_at=CURRENT_TIMESTAMP,reviewed_by=? WHERE id=?")->execute([$_SESSION['user_id'],(int)($_POST['id']??0)]);
            auditLog('access.deny','#'.(int)($_POST['id']??0));
            header('Location: ?page=admin_requests&ok='.urlencode('Request declined.')); exit;
        }
        if ($action === 'admin_delete_request') {
            $db->prepare('DELETE FROM access_requests WHERE id=?')->execute([(int)($_POST['id']??0)]);
            header('Location: ?page=admin_requests&ok='.urlencode('Request removed.')); exit;
        }
        if ($action === 'admin_save_user') {
            $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $email=trim($_POST['email']??'');
            $role=in_array($_POST['role']??'staff',['superadmin','admin','staff','readonly'],true)?$_POST['role']:'staff';
            $status=($_POST['status']??'active')==='disabled'?'disabled':'active';
            if(!$name||!$email){ header('Location: ?page=admin_users&err='.urlencode('Name and email are required.')); exit; }
            
            $targetEmail = $id ? (string)($db->query('SELECT email FROM users WHERE id='.$id)->fetchColumn() ?: '') : $email;
            if(isProtectedOwner($targetEmail)){ $email=OWNER_EMAIL; $role='superadmin'; $status='active'; }
            
            
            if(!isSuperAdmin()){
                $targetIsSuper = $id ? (($db->query('SELECT role FROM users WHERE id='.$id)->fetchColumn() ?: '')==='superadmin') : false;
                if($role==='superadmin' || $targetIsSuper){ header('Location: ?page=admin_users&err='.urlencode('Only a super-admin can assign or modify the super-admin role.')); exit; }
            }
            if($id){
                $db->prepare('UPDATE users SET name=?,email=?,role=?,status=? WHERE id=?')->execute([$name,$email,$role,$status,$id]);
                if(!empty($_POST['password'])) $db->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$id]);
                auditLog('user.update',$email);
            } else {
                $pw=$_POST['password']?:bin2hex(random_bytes(5));
                try{ $db->prepare('INSERT INTO users (name,email,password,role,status,created_by) VALUES (?,?,?,?,?,?)')->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role,$status,$_SESSION['user_id']]); auditLog('user.create',$email); }
                catch(\Throwable $e){ header('Location: ?page=admin_users&err='.urlencode('That email already exists.')); exit; }
            }
            header('Location: ?page=admin_users&ok=User+saved'); exit;
        }
        if ($action === 'admin_delete_user') {
            $id=(int)$_POST['id'];
            if($id===(int)$_SESSION['user_id']){ header('Location: ?page=admin_users&err='.urlencode('You cannot delete your own account.')); exit; }
            $delEmail=(string)($db->query('SELECT email FROM users WHERE id='.$id)->fetchColumn() ?: '');
            if(isProtectedOwner($delEmail)){ header('Location: ?page=admin_users&err='.urlencode('The owner super-admin account is permanent and cannot be deleted.')); exit; }
            if(!isSuperAdmin() && ($db->query('SELECT role FROM users WHERE id='.$id)->fetchColumn() ?: '')==='superadmin'){ header('Location: ?page=admin_users&err='.urlencode('Only a super-admin can remove a super-admin account.')); exit; }
            $db->prepare('DELETE FROM users WHERE id=?')->execute([$id]); auditLog('user.delete','#'.$id);
            header('Location: ?page=admin_users&ok=User+removed'); exit;
        }
        if ($action === 'admin_toggle_user') {
            $id=(int)$_POST['id'];
            $togEmail=(string)($db->query('SELECT email FROM users WHERE id='.$id)->fetchColumn() ?: '');
            if(isProtectedOwner($togEmail)){ header('Location: ?page=admin_users&err='.urlencode('The owner super-admin account cannot be disabled.')); exit; }
            if(!isSuperAdmin() && ($db->query('SELECT role FROM users WHERE id='.$id)->fetchColumn() ?: '')==='superadmin'){ header('Location: ?page=admin_users&err='.urlencode('Only a super-admin can disable a super-admin account.')); exit; }
            if($id!==(int)$_SESSION['user_id']) $db->prepare("UPDATE users SET status=CASE WHEN status='active' THEN 'disabled' ELSE 'active' END WHERE id=?")->execute([$id]);
            auditLog('user.toggle','#'.$id); header('Location: ?page=admin_users&ok=Updated'); exit;
        }
        if ($action === 'admin_save_tenant') {
            $id=(int)($_POST['id']??0); $name=trim($_POST['name']??'');
            $plan=in_array($_POST['plan']??'free',array_keys(plans()),true)?$_POST['plan']:'free';
            $status=in_array($_POST['status']??'active',['active','trial','suspended'],true)?$_POST['status']:'active';
            if(!$name){ header('Location: ?page=admin_churches&err='.urlencode('Church name is required.')); exit; }
            if($id) $db->prepare('UPDATE tenants SET name=?,contact_email=?,plan=?,status=?,notes=? WHERE id=?')->execute([$name,$_POST['contact_email']??'',$plan,$status,$_POST['notes']??'',$id]);
            else $db->prepare('INSERT INTO tenants (name,slug,contact_email,plan,status,license_key,notes) VALUES (?,?,?,?,?,?,?)')->execute([$name,strtolower(preg_replace('/[^a-z0-9]+/i','-',$name)),$_POST['contact_email']??'',$plan,$status,'LIC-'.strtoupper(bin2hex(random_bytes(8))),$_POST['notes']??'']);
            auditLog('tenant.save',$name); header('Location: ?page=admin_churches&ok=Church+saved'); exit;
        }
        if ($action === 'admin_toggle_tenant') {
            $db->prepare("UPDATE tenants SET status=CASE WHEN status='suspended' THEN 'active' ELSE 'suspended' END WHERE id=?")->execute([(int)$_POST['id']]);
            auditLog('tenant.toggle','#'.(int)$_POST['id']); header('Location: ?page=admin_churches&ok=Updated'); exit;
        }
        if ($action === 'admin_delete_tenant') { $db->prepare('DELETE FROM tenants WHERE id=?')->execute([(int)$_POST['id']]); auditLog('tenant.delete','#'.(int)$_POST['id']); header('Location: ?page=admin_churches&ok=Removed'); exit; }
        if ($action === 'admin_gen_license') { $db->prepare('UPDATE tenants SET license_key=? WHERE id=?')->execute(['LIC-'.strtoupper(bin2hex(random_bytes(8))),(int)$_POST['id']]); auditLog('tenant.license','#'.(int)$_POST['id']); header('Location: ?page=admin_licenses&ok=License+key+regenerated'); exit; }
        if ($action === 'admin_save_flags') {
            foreach ($db->query('SELECT key FROM feature_flags')->fetchAll(PDO::FETCH_COLUMN) as $k)
                $db->prepare('UPDATE feature_flags SET enabled=? WHERE key=?')->execute([isset($_POST['ff_'.$k])?1:0,$k]);
            auditLog('flags.save',''); header('Location: ?page=admin_config&ok=Feature+flags+saved'); exit;
        }
        if ($action === 'admin_seed_demo') { header('Location: ?page=admin_config'); exit; }
        if ($action === 'admin_clear_demo') {
            clearDemoData(); setSetting('demo_mode','0');
            auditLog('demo.clear',''); header('Location: ?page=admin_config&ok=Demo+data+cleared'); exit;
        }
        header('Location: ?page=admin&err=Unknown+admin+action'); exit;
    }

    
    if ($action === 'ai_chat') {
        $msg = trim($_POST['message'] ?? '');
        $sid = $_SESSION['ai_session'] ?? uniqid('ai_', true); $_SESSION['ai_session'] = $sid;
        if (!$msg) jsonOut(['error'=>'Empty message.']);
        $s = getStats();
        $sys = "You are the Free Church ChMS Assistant — a warm, insightful AI for pastors and administrators at " . getSetting('church_name') . ".\n"
             . "Live data — Active members: {$s['members']} | YTD giving: " . fmt($s['ytd_giving']) . " | At-risk members: {$s['at_risk']} | Services this year: {$s['services']}.\n"
             . "Help with member engagement, giving insight, sermon outlines, follow-up strategy, volunteer coordination, devotionals and analytics. Be warm, pastoral, specific and actionable.";
        $history = [];
        $st = $db->prepare('SELECT role,content FROM ai_conversations WHERE session_id=? ORDER BY id DESC LIMIT 20'); $st->execute([$sid]);
        foreach (array_reverse($st->fetchAll()) as $r) $history[] = ['role'=>$r['role'],'content'=>$r['content']];
        $history[] = ['role'=>'user','content'=>$msg];
        $err = ''; $reply = aiComplete($sys, $history, 1500, $err);
        if ($err) jsonOut(['error'=>$err]);
        $db->prepare('INSERT INTO ai_conversations (user_id,role,content,session_id) VALUES (?,?,?,?)')->execute([$_SESSION['user_id'],'user',$msg,$sid]);
        $db->prepare('INSERT INTO ai_conversations (user_id,role,content,session_id) VALUES (?,?,?,?)')->execute([$_SESSION['user_id'],'assistant',$reply,$sid]);
        jsonOut(['reply'=>$reply]);
    }

    
    if ($action === 'helper_ai') {
        $q = trim($_POST['q'] ?? '');
        if ($q === '') jsonOut(['error'=>'Empty question.']);
        if (!getSetting('anthropic_api_key')) jsonOut(['error'=>'no_key']);
        
        $kb = ''; $mf = @file_get_contents(__DIR__ . '/kb/manifest.json');
        if ($mf) { $j = json_decode($mf, true); foreach (($j['articles'] ?? []) as $a) $kb .= "- {$a['title']} ({$a['category']}): {$a['summary']} [kb/#{$a['slug']}]\n"; }
        $sys = "You are the Free Church ChMS Office Helper — a warm, concise in-app help desk for a church administrator using Free Church ChMS (a free, self-hosted church platform: members, attendance, giving, donor intelligence, communications email/SMS, workflows, AI Studio, insights, reports, integrations, events, volunteers, pastoral care, check-in, worship planning, accounting, admin console, knowledge base). "
             . "Answer the how-to question in 2–5 short, friendly steps or sentences — practical and specific. Point to the matching Knowledge Base guide when one fits (write it as kb/#slug). Never invent features that aren't listed. Support is the Office Helper and Knowledge Base only (no email/phone).\n\nKnowledge Base articles:\n" . $kb;
        $err = ''; $ans = aiComplete($sys, $q, 700, $err);
        if ($err) jsonOut(['error'=>$err]);
        jsonOut(['answer'=>$ans]);
    }

    
    if ($action === 'ai_generate_content') {
        $type = $_POST['type'] ?? 'newsletter'; $topic = trim($_POST['topic'] ?? '');
        $voice = getSetting('church_voice') ?: 'warm, pastoral, hopeful';
        $cname = getSetting('church_name'); $pastor = getSetting('pastor_name');
        $prompts = [
            'sermon'=>"Write a clear, faithful sermon outline (title, key scripture, 3 main points each with a sub-idea and an application, and a closing) on: $topic",
            'newsletter'=>"Write a warm church email newsletter (HTML-friendly, with a greeting and 3 short sections) for $cname about: $topic",
            'social'=>"Write 3 short social posts (one each for Facebook, Instagram, X) for $cname about: $topic. Include tasteful emoji and a call to action.",
            'letter'=>"Write a personal pastoral letter from $pastor at $cname about: $topic. Warm, specific, encouraging.",
            'bulletin'=>"Write concise Sunday bulletin copy for $cname covering: $topic",
            'giving_statement'=>"Write a heartfelt year-end giving thank-you letter template (use {first_name} and {giving_year_to_date} merge fields) for $cname.",
        ];
        $sys = "You are a gifted church communications writer. Write in this church's voice: $voice. Output clean, ready-to-use copy. Never invent facts about the church.";
        $err=''; $body = aiComplete($sys, $prompts[$type] ?? $prompts['newsletter'], 1800, $err);
        if ($err) jsonOut(['error'=>$err]);
        $db->prepare('INSERT INTO ai_content (user_id,type,title,prompt,body) VALUES (?,?,?,?,?)')
           ->execute([$_SESSION['user_id'],$type,$topic ?: ucfirst($type),$topic,$body]);
        jsonOut(['body'=>$body]);
    }

    
    if ($action === 'ai_explain_metrics') {
        $lines = [];
        foreach (computeMetrics() as [$title,$ms]) { $lines[] = "## $title"; foreach ($ms as [$k,$l,$v]) $lines[] = "- $l: $v"; }
        $sys = "You are a wise church-health analyst for " . getSetting('church_name') . ". Given these exact, already-computed metrics, give a brief (150-220 word) pastoral reading: what's healthy, what to watch, and 2-3 concrete next actions. Do not invent numbers; only interpret these.";
        $err=''; $text = aiComplete($sys, implode("\n", $lines), 700, $err);
        if ($err) jsonOut(['error'=>$err]);
        jsonOut(['text'=>$text]);
    }
    
    if ($action === 'ai_pulse_insight') {
        $p = pulseData();
        
        $focus = trim((string)($_POST['focus'] ?? ''));
        if ($focus !== '') {
            $m = null; foreach (array_merge($p['metrics'], $p['forecast']) as $x) { if (($x['key'] ?? '') === $focus) { $m = $x; break; } }
            if (!$m) jsonOut(['error'=>'Unknown metric.']);
            $chg = (isset($m['delta']) && $m['delta'] !== null) ? (($m['delta']>=0?'+':'').$m['delta'].'% '.($m['deltaLabel']??'')) : ($m['bandLabel'] ?? '');
            $ctx = "Metric: {$m['label']}\nCurrent value: {$m['value']} — {$m['sub']}\nChange: {$chg}\nQuick reading: {$m['note']}";
            $sys = "You are a warm, wise church-health analyst for " . getSetting('church_name') . ". A church leader is looking closely at ONE metric. In 90-150 words and plain language: explain what this number really means for their church right now, whether it is encouraging or worth concern, and 1-2 specific, doable actions to take this week. Do not invent numbers; interpret only what is given. Hopeful, faithful, concrete.";
            $err=''; $text = aiComplete($sys, $ctx, 500, $err);
            if ($err) jsonOut(['error'=>$err]);
            jsonOut(['text'=>$text]);
        }
        $lines = ['# Membership vital signs'];
        foreach ($p['metrics'] as $m) {
            $chg = ($m['kind']==='spark') ? (($m['delta']>=0?'+':'').$m['delta'].'% '.$m['deltaLabel']) : ($m['bandLabel'].' band');
            $lines[] = "- {$m['label']}: {$m['value']} ({$chg})";
        }
        $lines[] = "\n# Forecast & financial outlook";
        foreach ($p['forecast'] as $f) {
            $chg = (isset($f['delta']) && $f['delta']!==null) ? ' ('.($f['delta']>=0?'+':'').$f['delta'].'% '.$f['deltaLabel'].')' : '';
            $lines[] = "- {$f['label']}: {$f['value']} — {$f['sub']}{$chg}";
        }
        $sys = "You are a warm, wise church-health analyst for " . getSetting('church_name') . ". You are given exact, already-computed membership vital signs and financial forecasts. Write a brief (180-260 word) pastoral reading in plain language: (1) one sentence on the overall picture — growing or slipping; (2) what is healthy; (3) what to watch, especially any financial risk; (4) 2-3 concrete, encouraging next actions a pastor can take this week. Do not invent numbers; interpret only what is given. Hopeful, faithful tone.";
        $err=''; $text = aiComplete($sys, implode("\n", $lines), 900, $err);
        if ($err) jsonOut(['error'=>$err]);
        jsonOut(['text'=>$text]);
    }

    
    if ($action === 'witness_ai') {
        $ref  = trim((string)($_POST['ref'] ?? ''));
        $trad = (($_POST['trad'] ?? '') === 'orthodox') ? 'Orthodox' : 'Catholic';
        $base = null; foreach (witnessVerses() as $v) { if ($v['ref'] === $ref) { $base = $v; break; } }
        if (!$base) jsonOut(['error'=>'Unknown verse.']);
        $b = ($trad === 'Orthodox') ? $base['orthodox'] : $base['catholic'];
        $church = getSetting('church_name') ?: 'our church';
        $voice  = getSetting('church_voice') ?: 'warm, pastoral, hopeful';
        $sys = "You are helping {$church}, a {$trad} Christian church, create a warm witness handout that helps people discover the faith. "
             . "Stay doctrinally accurate to the {$trad} Christian tradition, deeply reverent, and never polemical or comparative. "
             . "Write in very plain, friendly language a 12-year-old (and a reader with low vision) can follow easily — short sentences, gentle warmth. "
             . "Stay grounded in the given verse and gently invite the reader toward Christ and his Church. Match this church's voice: {$voice}.";
        $usr = "Verse: {$base['ref']} — \"{$base['verseText']}\"\n\nHere is a starting reflection you may build on (keep its spirit and accuracy):\n{$b['reflection']}\n\n"
             . "Write one fresh reflection of about 110-150 words for {$church} to print and share. Return ONLY the reflection text — no title, no preamble.";
        $err=''; $text = aiComplete($sys, $usr, 700, $err);
        if ($err) jsonOut(['error'=>$err]);
        jsonOut(['ok'=>true,'text'=>$text]);
    }

    
    if ($action === 'generate_report') {
        $type = $_POST['type'] ?? 'giving';
        switch ($type) {
            case 'giving': jsonOut(['title'=>'Monthly Giving','rows'=>$db->query("SELECT strftime('%Y-%m',date) month, ROUND(SUM(amount),2) total, COUNT(*) gifts, ROUND(AVG(amount),2) avg_gift FROM giving GROUP BY strftime('%Y-%m',date) ORDER BY month DESC LIMIT 12")->fetchAll()]);
            case 'attendance': jsonOut(['title'=>'Attendance History','rows'=>$db->query("SELECT s.date, s.name, s.head_count, COUNT(a.id) registered FROM services s LEFT JOIN attendance a ON a.service_id=s.id GROUP BY s.id ORDER BY s.date DESC LIMIT 20")->fetchAll()]);
            case 'members': jsonOut(['title'=>'Member Status','total'=>(int)$db->query("SELECT COUNT(*) FROM members")->fetchColumn(),'rows'=>$db->query("SELECT status, COUNT(*) count FROM members GROUP BY status")->fetchAll()]);
            case 'disengagement': jsonOut(['title'=>'At-Risk Members','rows'=>$db->query("SELECT first_name,last_name,email,phone,engagement_score,engagement_tier,last_attended FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active' ORDER BY engagement_score ASC")->fetchAll()]);
            case 'top_donors': jsonOut(['title'=>'Top Donors YTD','rows'=>$db->query("SELECT m.first_name,m.last_name,SUM(g.amount) total,COUNT(*) gifts FROM giving g JOIN members m ON m.id=g.member_id WHERE strftime('%Y',g.date)=strftime('%Y','now') GROUP BY g.member_id ORDER BY total DESC LIMIT 20")->fetchAll()]);
            case 'giving_by_fund': jsonOut(['title'=>'Giving by Fund YTD','rows'=>$db->query("SELECT f.name fund, SUM(g.amount) total, COUNT(*) gifts FROM giving g JOIN funds f ON f.id=g.fund_id WHERE strftime('%Y',g.date)=strftime('%Y','now') GROUP BY g.fund_id ORDER BY total DESC")->fetchAll()]);
        }
        jsonOut(['error'=>'Unknown report type']);
    }

    
    if ($action === 'recalc_engagement') {
        $r = recomputeEngagement();
        header('Location: ?page=' . ($_POST['return'] ?? 'dashboard') . '&ok=' . urlencode("Engagement recalculated for {$r['updated']} members ({$r['at_risk']} at risk).")); exit;
    }

    
    if ($action === 'save_workflow') {
        $id = (int)($_POST['id'] ?? 0);
        $actions = [];
        $chans = $_POST['act_channel'] ?? []; $tpls = $_POST['act_template'] ?? []; $delays = $_POST['act_delay'] ?? [];
        foreach ($chans as $i=>$ch) if ($ch) $actions[] = ['channel'=>$ch,'template'=>$tpls[$i]??'welcome','delay'=>(int)($delays[$i]??0)];
        $aj = json_encode($actions ?: [['channel'=>'email','template'=>'welcome','delay'=>0]]);
        if ($id) $db->prepare('UPDATE workflows SET name=?,description=?,trigger_type=?,trigger_value=?,actions=? WHERE id=?')->execute([$_POST['name'],$_POST['description']??'',$_POST['trigger_type'],$_POST['trigger_value']??'',$aj,$id]);
        else $db->prepare('INSERT INTO workflows (name,description,trigger_type,trigger_value,actions,active) VALUES (?,?,?,?,?,1)')->execute([$_POST['name'],$_POST['description']??'',$_POST['trigger_type'],$_POST['trigger_value']??'',$aj]);
        header('Location: ?page=workflows&ok=Workflow+saved'); exit;
    }
    if ($action === 'toggle_workflow') { $db->prepare('UPDATE workflows SET active=1-active WHERE id=?')->execute([(int)$_POST['id']]); header('Location: ?page=workflows&ok=Updated'); exit; }
    if ($action === 'delete_workflow') { $db->prepare('DELETE FROM workflows WHERE id=?')->execute([(int)$_POST['id']]); header('Location: ?page=workflows&ok=Deleted'); exit; }
    if ($action === 'run_workflow') {
        $r = runWorkflow((int)$_POST['id']);
        $m = isset($r['error']) ? 'err=' . urlencode($r['error']) : 'ok=' . urlencode("Ran on {$r['targets']} member(s): {$r['sent']} sent" . ($r['failed']?", {$r['failed']} failed":'') . '.');
        header("Location: ?page=workflows&$m"); exit;
    }

    
    if ($action === 'import_csv') {
        @set_time_limit(300); 
        $ret  = ($_POST['return'] ?? '') === 'tools' ? 'tools' : 'integrations';
        $type = in_array($_POST['import_type'] ?? 'members', ['members','giving','attendance'], true) ? $_POST['import_type'] : 'members';
        if (empty($_FILES['csv_file']['tmp_name'])) { header("Location: ?page=$ret&err=No+file"); exit; }
        $tmp = $_FILES['csv_file']['tmp_name']; $name = strtolower($_FILES['csv_file']['name'] ?? '');
        $isX = str_ends_with($name, '.xlsx');
        $rows = $isX ? parseXlsx($tmp) : parseCsvFile($tmp);
        if (!$rows) { header("Location: ?page=$ret&err=" . urlencode('Could not read the file (empty or unsupported).')); exit; }
        $header = array_shift($rows);
        if (isset($header[0])) $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string)$header[0]); 
        $map = []; foreach ($header as $i=>$col) $map[strtolower(trim(str_replace([' ','-'],'_',(string)$col)))] = $i;
        $src = $isX ? 'excel' : 'csv';
        $imp=0; $upd=0; $skip=0;

        if ($type === 'giving') {
            
            $db->beginTransaction();
            foreach ($rows as $row) {
                $get = fn($k)=>isset($map[$k]) ? trim((string)($row[$map[$k]] ?? '')) : '';
                $amount = (float)preg_replace('/[^0-9.\-]/','', $get('amount') ?: $get('gift') ?: $get('total'));
                if ($amount <= 0) { $skip++; continue; }
                $email = $get('email'); $fn = $get('first_name')?:$get('firstname')?:$get('first'); $ln = $get('last_name')?:$get('lastname')?:$get('last');
                $mid = null;
                if ($email) { $s=$db->prepare('SELECT id FROM members WHERE email=?'); $s->execute([$email]); $mid=$s->fetchColumn() ?: null; }
                if (!$mid && ($fn||$ln)) { $s=$db->prepare('SELECT id FROM members WHERE first_name=? AND last_name=?'); $s->execute([$fn,$ln]); $mid=$s->fetchColumn() ?: null; }
                if (!$mid && ($fn||$ln||$email)) { 
                    $db->prepare('INSERT INTO members (first_name,last_name,email,status,source) VALUES (?,?,?,?,?)')->execute([$fn?:'Unknown',$ln?:'Donor',$email,'active',$src]);
                    $mid=(int)$db->lastInsertId();
                }
                if (!$mid) { $skip++; continue; }
                
                $fundName = $get('fund') ?: $get('fund_name') ?: $get('designation');
                $fid = null;
                if ($fundName) { $s=$db->prepare('SELECT id FROM funds WHERE LOWER(name)=LOWER(?)'); $s->execute([$fundName]); $fid=$s->fetchColumn() ?: null;
                    if (!$fid) { $db->prepare('INSERT INTO funds (name,active) VALUES (?,1)')->execute([$fundName]); $fid=(int)$db->lastInsertId(); } }
                if (!$fid) $fid = (int)($db->query('SELECT id FROM funds ORDER BY id LIMIT 1')->fetchColumn() ?: 0);
                $date = $get('date') ?: date('Y-m-d');
                $ts = strtotime($date); if ($ts) $date = date('Y-m-d', $ts);
                $db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,check_number,notes,source) VALUES (?,?,?,?,?,?,?,?)')
                   ->execute([$mid,$fid?:null,$amount,$date,$get('method')?:'import',$get('check_number')?:$get('check'),$get('notes'),$src]);
                $imp++;
            }
            $db->commit();
            logSync($src.'_giving', $imp, 0, 'ok', "$skip skipped");
            header("Location: ?page=$ret&ok=" . urlencode("Giving import complete: $imp gifts added" . ($skip?", $skip rows skipped":'') . '.')); exit;
        }

        if ($type === 'attendance') {
            
            $db->beginTransaction();
            foreach ($rows as $row) {
                $get = fn($k)=>isset($map[$k]) ? trim((string)($row[$map[$k]] ?? '')) : '';
                $svcName = $get('service') ?: $get('service_name') ?: 'Imported Service';
                $svcDate = $get('date') ?: date('Y-m-d'); $ts=strtotime($svcDate); if($ts)$svcDate=date('Y-m-d',$ts);
                $s=$db->prepare('SELECT id FROM services WHERE name=? AND date=?'); $s->execute([$svcName,$svcDate]); $sid=$s->fetchColumn() ?: null;
                if (!$sid) { $db->prepare('INSERT INTO services (name,date,type) VALUES (?,?,?)')->execute([$svcName,$svcDate,'import']); $sid=(int)$db->lastInsertId(); }
                $email=$get('email'); $fn=$get('first_name')?:$get('firstname')?:$get('first'); $ln=$get('last_name')?:$get('lastname')?:$get('last');
                $mid=null;
                if ($email){ $q=$db->prepare('SELECT id FROM members WHERE email=?'); $q->execute([$email]); $mid=$q->fetchColumn()?:null; }
                if (!$mid && ($fn||$ln)){ $q=$db->prepare('SELECT id FROM members WHERE first_name=? AND last_name=?'); $q->execute([$fn,$ln]); $mid=$q->fetchColumn()?:null; }
                if (!$mid){ $skip++; continue; }
                try { $db->prepare('INSERT OR IGNORE INTO attendance (service_id,member_id,checked_in) VALUES (?,?,1)')->execute([$sid,$mid]); $imp++; }
                catch(\Throwable $e){ $skip++; }
            }
            $db->commit();
            logSync($src.'_attendance', $imp, 0, 'ok', "$skip skipped");
            header("Location: ?page=$ret&ok=" . urlencode("Attendance import complete: $imp check-ins added" . ($skip?", $skip skipped":'') . '.')); exit;
        }

        
        $db->beginTransaction();
        foreach ($rows as $row) {
            $get = fn($k)=>isset($map[$k]) ? trim((string)($row[$map[$k]] ?? '')) : '';
            $fn = $get('first_name') ?: $get('firstname') ?: $get('first');
            $ln = $get('last_name')  ?: $get('lastname')  ?: $get('last');
            if (!$fn && !$ln) { $skip++; continue; }
            $res = upsertMember(['first_name'=>$fn,'last_name'=>$ln,'email'=>$get('email'),'phone'=>$get('phone'),'status'=>$get('status') ?: 'active'], $src);
            $res === 'imported' ? $imp++ : $upd++;
        }
        $db->commit();
        logSync($src, $imp, $upd, 'ok');
        header("Location: ?page=$ret&ok=" . urlencode("Import complete: $imp added, $upd updated.")); exit;
    }

    
    if ($action === 'sync_planning_center') {
        $id = getSetting('planning_center_app_id'); $sec = getSetting('planning_center_secret');
        if (!$id || !$sec) jsonOut(['error'=>'Planning Center credentials not set.']);
        $ch = curl_init('https://api.planningcenteronline.com/people/v2/people?per_page=100&include=emails,phone_numbers');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_USERPWD=>"$id:$sec", CURLOPT_TIMEOUT=>25]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('planning_center',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Planning Center API error $code"]); }
        $data = json_decode((string)$res, true); $imp=0; $upd=0;
        foreach ($data['data'] ?? [] as $p) {
            $a = $p['attributes'] ?? [];
            $r = upsertMember(['first_name'=>$a['first_name']??'','last_name'=>$a['last_name']??'','email'=>$a['primary_email_address']??'','external_id'=>(string)$p['id']], 'planning_center');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('planning_center',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_breeze') {
        $key = getSetting('breeze_api_key'); $sub = getSetting('breeze_subdomain');
        if (!$key || !$sub) jsonOut(['error'=>'Breeze credentials not set.']);
        $ch = curl_init("https://$sub.breezechms.com/api/people?details=1");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Api-Key: $key"], CURLOPT_TIMEOUT=>25]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('breeze',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Breeze API error $code"]); }
        $people = json_decode((string)$res, true); $imp=0; $upd=0;
        foreach ($people ?? [] as $p) {
            $r = upsertMember(['first_name'=>$p['first_name']??'','last_name'=>$p['last_name']??'','email'=>$p['email']??($p['email_primary']??''),'phone'=>$p['phone']??'','external_id'=>(string)($p['id']??'')], 'breeze');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('breeze',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_ccb') {
        $sub = getSetting('ccb_subdomain'); $u = getSetting('ccb_username'); $pw = getSetting('ccb_password');
        if (!$sub || !$u) jsonOut(['error'=>'Church Community Builder credentials not set.']);
        $ch = curl_init("https://$sub.ccbchurch.com/api.php?srv=individual_profiles");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_USERPWD=>"$u:$pw", CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('ccb',0,0,'error',"HTTP $code"); jsonOut(['error'=>"CCB API error $code"]); }
        $imp=0; $upd=0; $xml = @simplexml_load_string((string)$res);
        if ($xml) foreach ($xml->response->individuals->individual ?? [] as $ind) {
            $r = upsertMember(['first_name'=>(string)$ind->first_name,'last_name'=>(string)$ind->last_name,'email'=>(string)$ind->email,'phone'=>(string)($ind->phones->phone[0] ?? ''),'external_id'=>(string)$ind['id']], 'ccb');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('ccb',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_elvanto') {
        $key = getSetting('elvanto_api_key'); if (!$key) jsonOut(['error'=>'Elvanto API key not set.']);
        $ch = curl_init('https://api.elvanto.com/v1/people/getAll.json');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_USERPWD=>"$key:x", CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('elvanto',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Elvanto API error $code"]); }
        $data = json_decode((string)$res, true); $imp=0; $upd=0;
        foreach ($data['people']['person'] ?? [] as $p) {
            $r = upsertMember(['first_name'=>$p['firstname']??'','last_name'=>$p['lastname']??'','email'=>$p['email']??'','phone'=>$p['phone']??($p['mobile']??''),'external_id'=>(string)($p['id']??'')], 'elvanto');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('elvanto',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
