    if ($action === 'sync_realm') {
        $cid = getSetting('realm_client_id'); $sec = getSetting('realm_client_secret');
        if (!$cid || !$sec) jsonOut(['error'=>'Realm (ACS) credentials not set.']);
        
        $ch = curl_init('https://api.realmchurch.com/v1/constituents?per_page=100');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Authorization: Bearer $sec","Accept: application/json"], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('realm',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Realm API error $code — confirm OAuth token in Realm client secret."]); }
        $data = json_decode((string)$res, true); $imp=0; $upd=0;
        foreach (($data['results'] ?? $data['data'] ?? []) as $p) {
            $r = upsertMember(['first_name'=>$p['firstName']??($p['first_name']??''),'last_name'=>$p['lastName']??($p['last_name']??''),'email'=>$p['email']??'','external_id'=>(string)($p['id']??'')], 'realm');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('realm',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
