    if ($action === 'sync_shelby') {
        $key = getSetting('shelby_api_key'); $base = rtrim(getSetting('shelby_base'), '/');
        if (!$key || !$base) jsonOut(['error'=>'Shelby Systems credentials/base URL not set.']);
