        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('shelby',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Shelby API error $code"]); }
        $data = json_decode((string)$res, true); $imp=0; $upd=0;
        foreach (($data['individuals'] ?? $data['data'] ?? []) as $p) {
            $r = upsertMember(['first_name'=>$p['firstName']??($p['first_name']??''),'last_name'=>$p['lastName']??($p['last_name']??''),'email'=>$p['email']??'','external_id'=>(string)($p['id']??'')], 'shelby');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('shelby',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_pushpay') {
        $key = getSetting('pushpay_key'); if (!$key) jsonOut(['error'=>'Pushpay key not set.']);
        $ch = curl_init('https://api.pushpay.com/v1/organization/payments?pageSize=100');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Authorization: Bearer $key","Accept: application/json"], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('pushpay',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Pushpay API error $code"]); }
        $data = json_decode((string)$res, true); $n = importGifts($data['items'] ?? $data['data'] ?? [], 'pushpay');
        logSync('pushpay',$n,0,'ok'); jsonOut(['success'=>true,'imported'=>$n]);
    }
    if ($action === 'sync_tithely') {
        $key = getSetting('tithely_key'); if (!$key) jsonOut(['error'=>'Tithe.ly key not set.']);
        $ch = curl_init('https://tithe.ly/api/v1/giving');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Authorization: $key","Accept: application/json"], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('tithely',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Tithe.ly API error $code"]); }
        $data = json_decode((string)$res, true); $n = importGifts($data['data'] ?? $data['giving'] ?? [], 'tithely');
        logSync('tithely',$n,0,'ok'); jsonOut(['success'=>true,'imported'=>$n]);
