    if ($action === 'sync_stripe') {
        $key = getSetting('stripe_secret_key'); if (!$key) jsonOut(['error'=>'Stripe secret key not set.']);
        $ch = curl_init('https://api.stripe.com/v1/charges?limit=100');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_USERPWD=>"$key:", CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('stripe',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Stripe API error $code"]); }
        $data = json_decode((string)$res, true); $fund = (int)$db->query("SELECT id FROM funds ORDER BY id LIMIT 1")->fetchColumn();
        $n=0; foreach ($data['data'] ?? [] as $c) {
            if (empty($c['paid']) || ($c['refunded']??false)) continue;
            $exists = $db->prepare('SELECT 1 FROM giving WHERE source=? AND external_id=?'); $exists->execute(['stripe',$c['id']]);
            if ($exists->fetch()) continue;
            $db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,source,external_id) VALUES (?,?,?,?,?,?,?)')
               ->execute([0,$fund,($c['amount']??0)/100,date('Y-m-d',$c['created']??time()),'card','stripe',$c['id']]); $n++;
        }
        logSync('stripe',$n,0,'ok'); jsonOut(['success'=>true,'imported'=>$n]);
    }

    if ($action === 'sync_rock') {
        $base = rtrim(getSetting('rock_base_url'), '/'); $tok = getSetting('rock_api_token');
        if (!$base || !$tok) jsonOut(['error'=>'Rock RMS base URL / API token not set.']);
        if (!safeOutboundUrl("$base/api/People")) jsonOut(['error'=>'Rock RMS base URL is not a valid public https endpoint.']);
        $ch = curl_init("$base/api/People?\$top=100&\$select=Id,FirstName,LastName,Email");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Authorization-Token: $tok","Accept: application/json"], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('rock',0,0,'error',"HTTP $code"); jsonOut(['error'=>"Rock RMS API error $code"]); }
        $data = json_decode((string)$res, true); $imp=0;$upd=0;
        foreach (($data ?? []) as $p) { $r = upsertMember(['first_name'=>$p['FirstName']??'','last_name'=>$p['LastName']??'','email'=>$p['Email']??'','external_id'=>(string)($p['Id']??'')], 'rock'); $r==='imported'?$imp++:$upd++; }
        logSync('rock',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_civicrm') {
        
        $url = trim(getSetting('civicrm_rest_url')); $site = getSetting('civicrm_site_key'); $key = getSetting('civicrm_api_key');
        if (!$url || !$site || !$key) jsonOut(['error'=>'CiviCRM REST URL, site key and API key are all required.']);
        if (!safeOutboundUrl($url)) jsonOut(['error'=>'CiviCRM REST URL is not a valid public https endpoint.']);
        $params = json_encode(['sequential'=>1,'contact_type'=>'Individual','return'=>['first_name','last_name','email'],'options'=>['limit'=>500]]);
        $post = http_build_query(['entity'=>'Contact','action'=>'get','api_key'=>$key,'key'=>$site,'json'=>$params]);
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$post,
            CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS, CURLOPT_FOLLOWLOCATION=>false, CURLOPT_TIMEOUT=>30,
            CURLOPT_HTTPHEADER=>['Accept: application/json','Content-Type: application/x-www-form-urlencoded']]);
        $res = curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) { logSync('civicrm',0,0,'error',"HTTP $code"); jsonOut(['error'=>"CiviCRM API error $code — check the REST URL and keys."]); }
        $data = json_decode((string)$res, true);
        if (isset($data['is_error']) && $data['is_error']) { logSync('civicrm',0,0,'error',$data['error_message']??'error'); jsonOut(['error'=>'CiviCRM: '.($data['error_message']??'authentication failed — check your keys.')]); }
        $imp=0;$upd=0;
        foreach (($data['values'] ?? []) as $p) {
            if (empty($p['first_name']) && empty($p['last_name'])) continue;
            $r = upsertMember(['first_name'=>$p['first_name']??'','last_name'=>$p['last_name']??'','email'=>$p['email']??'','external_id'=>(string)($p['contact_id']??($p['id']??''))], 'civicrm');
            $r==='imported'?$imp++:$upd++;
        }
        logSync('civicrm',$imp,$upd,'ok'); jsonOut(['success'=>true,'imported'=>$imp,'updated'=>$upd]);
    }
    if ($action === 'sync_givebutter') {
