        $ch = curl_init('https://api.givebutter.com/v1/transactions?per_page=100');
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["Authorization: Bearer $key","Accept: application/json"], CURLOPT_TIMEOUT=>30]);
        $res = curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
