        $ch = curl_init("$base/$topic"); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>'Test push from Free Church ChMS ✅', CURLOPT_HTTPHEADER=>$hdr, CURLOPT_TIMEOUT=>15]);
        curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
