function parseCsvFile(string $path): array {
    $rows = []; $fh = fopen($path, 'r'); if (!$fh) return [];
    $MAX = 100000; 
    while (($r = fgetcsv($fh)) !== false) { $rows[] = $r; if (count($rows) >= $MAX) break; }
    fclose($fh); return $rows;
}

function colIndex(string $letters): int {
    $letters = strtoupper(preg_replace('/[^A-Z]/', '', $letters)); $n = 0;
    for ($i = 0, $L = strlen($letters); $i < $L; $i++) $n = $n * 26 + (ord($letters[$i]) - 64);
    
    
    return max(0, min($n - 1, 16383));
}

function parseXlsx(string $path): array {
    if (!class_exists('ZipArchive')) return [];
    $zip = new ZipArchive(); if ($zip->open($path) !== true) return [];
    
    $MAX_ENTRY = 64 * 1024 * 1024; 
    $safeGet = function(ZipArchive $z, string $name) use ($MAX_ENTRY) {
        $st = $z->statName($name);
        if ($st === false) return false;
        if (($st['size'] ?? 0) > $MAX_ENTRY) return false; 
        return $z->getFromName($name);
    };
    $shared = [];
    if (($ss = $safeGet($zip, 'xl/sharedStrings.xml')) !== false) {
        $xml = @simplexml_load_string($ss);
        if ($xml) foreach ($xml->si as $si) {
            if (isset($si->t)) $shared[] = (string)$si->t;
            else { $t = ''; foreach ($si->r as $r) $t .= (string)$r->t; $shared[] = $t; }
        }
    }
    
    $sheetXml = $safeGet($zip, 'xl/worksheets/sheet1.xml');
    if ($sheetXml === false) { for ($i=1;$i<=20;$i++){ $sheetXml=$safeGet($zip, "xl/worksheets/sheet$i.xml"); if($sheetXml!==false) break; } }
    $zip->close();
    if (!$sheetXml) return [];
    $xml = @simplexml_load_string($sheetXml); if (!$xml || !isset($xml->sheetData)) return [];
    $rows = []; $MAX = 100000;
    foreach ($xml->sheetData->row as $row) {
        if (count($rows) >= $MAX) break; 
        $cells = []; $maxCol = 0;
        foreach ($row->c as $c) {
            $col = colIndex((string)$c['r']); $type = (string)$c['t']; $v = (string)$c->v;
            if ($type === 's') $v = $shared[(int)$v] ?? '';
            elseif ($type === 'inlineStr') $v = (string)($c->is->t ?? '');
            $cells[$col] = $v; $maxCol = max($maxCol, $col);
        }
        $line = []; for ($i = 0; $i <= $maxCol; $i++) $line[] = $cells[$i] ?? '';
        $rows[] = $line;
    }
    return $rows;
}


function importGifts(array $items, string $source): int {
    $db = getDB(); $fund = (int)$db->query("SELECT id FROM funds ORDER BY id LIMIT 1")->fetchColumn(); $n = 0;
    foreach ($items as $it) {
        $ext = (string)($it['transactionId'] ?? $it['id'] ?? $it['transaction_id'] ?? '');
        if ($ext) { $e = $db->prepare('SELECT 1 FROM giving WHERE source=? AND external_id=?'); $e->execute([$source,$ext]); if ($e->fetch()) continue; }
        $amt = (float)($it['amount']['amount'] ?? $it['amount'] ?? $it['total'] ?? 0);
        $date = substr((string)($it['createdOn'] ?? $it['date'] ?? $it['created_at'] ?? date('Y-m-d')), 0, 10);
        if ($amt <= 0) continue;
        $db->prepare('INSERT INTO giving (member_id,fund_id,amount,date,method,source,external_id) VALUES (?,?,?,?,?,?,?)')
           ->execute([0,$fund,$amt,$date,'online',$source,$ext]); $n++;
    }
    return $n;
}




