}
[data-theme="dark"] body{background-color:#0e1426;background-image:linear-gradient(rgba(12,17,32,.85),rgba(8,11,22,.93)),url('assets/theme-dark.webp');background-attachment:fixed;background-size:cover;color:var(--gray-700)}
[data-theme="dark"] .sidebar-logo{background:rgba(20,27,46,.96)}
