.lang-switch{display:inline-flex;align-items:center;gap:6px;color:var(--gray-400);margin-left:var(--sp-3)}
.lang-switch i{font-size:var(--text-sm)}
.lang-switch select{font:inherit;font-size:var(--text-xs);font-weight:700;color:var(--gray-600);border:1px solid var(--gray-200);background:#fff;border-radius:var(--radius-sm);padding:4px 6px;cursor:pointer}
.theme-picker{display:flex;gap:var(--sp-3);flex-wrap:wrap}
.theme-dot{appearance:none;border:none;background:none;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;padding:0}
.theme-dot>span{width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,var(--d1),var(--d2));box-shadow:0 2px 8px rgba(16,24,64,.15);border:3px solid #fff;outline:2px solid transparent;transition:transform var(--t-base),outline-color var(--t-base)}
.theme-dot:hover>span{transform:translateY(-2px) scale(1.06)}
.theme-dot.selected>span{outline-color:var(--d1)}
.theme-dot.selected>em{color:var(--gray-800);font-weight:700}
.theme-dot>em{font-style:normal;font-size:var(--text-2xs);color:var(--gray-500)}

.theme-mini{--mini-dot:15px;display:flex;justify-content:center;align-items:center;gap:9px;padding:7px var(--sp-4) 11px;margin:2px var(--sp-3) 0}
.theme-mini-dot{position:relative;appearance:none;cursor:pointer;width:var(--mini-dot);height:var(--mini-dot);border-radius:50%;padding:0;background:linear-gradient(135deg,var(--d1),var(--d2));border:2px solid #fff;box-shadow:0 1px 4px rgba(16,24,64,.18);outline:1.5px solid transparent;outline-offset:1.5px;transition:transform var(--t-base),outline-color var(--t-base)}
.theme-mini-dot:hover{transform:scale(1.18)}
.theme-mini-dot.selected{outline-color:var(--d1)}

.theme-mini-dot::after{content:attr(data-name);position:absolute;top:calc(100% + 9px);left:50%;transform:translateX(-50%) translateY(3px);background:#0b1020;color:#eef2ff;font-size:10.5px;font-weight:600;letter-spacing:.01em;white-space:nowrap;padding:5px 9px;border-radius:7px;box-shadow:0 8px 22px rgba(0,0,0,.34);opacity:0;visibility:hidden;pointer-events:none;transition:opacity var(--t-base),transform var(--t-base);z-index:80}
.theme-mini-dot::before{content:"";position:absolute;top:calc(100% + 3px);left:50%;transform:translateX(-50%);border:5px solid transparent;border-bottom-color:#0b1020;opacity:0;visibility:hidden;transition:opacity var(--t-base);z-index:80}
.theme-mini-dot:hover::after,.theme-mini-dot:focus-visible::after{opacity:1;visibility:visible;transform:translateX(-50%) translateY(0)}
.theme-mini-dot:hover::before,.theme-mini-dot:focus-visible::before{opacity:1;visibility:visible}
@media print{.theme-mini{display:none}}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;font-size:16px}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;background:var(--gray-50);color:var(--gray-800);display:flex;min-height:100vh;min-height:100dvh;font-size:var(--text-base);line-height:1.6;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
