::selection{background:rgba(46,91,255,.16)}
.bloom-overlay{position:fixed;top:-25%;right:-15%;width:55vw;height:55vw;background:radial-gradient(circle at center,rgba(111,61,232,.10),transparent 62%);pointer-events:none;z-index:0;animation:bloom-drift 22s ease-in-out infinite alternate}
@keyframes bloom-drift{from{transform:translate(0,0) scale(1)}to{transform:translate(-3%,5%) scale(1.12)}}


.sidebar{width:var(--sidebar-w);background:var(--white);border-right:1px solid var(--gray-100);display:flex;flex-direction:column;position:fixed;inset:0 auto 0 0;height:100vh;height:100dvh;z-index:200;overflow-y:auto;scrollbar-width:thin;transition:transform var(--t-slow)}
.sidebar::-webkit-scrollbar{width:5px}.sidebar::-webkit-scrollbar-thumb{background:var(--gray-200);border-radius:3px}
.sidebar-logo{padding:var(--sp-5) var(--sp-4) var(--sp-3);position:sticky;top:0;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);z-index:10;border-bottom:1px solid var(--gray-100)}
