.brand-mark{width:clamp(34px,3vw,46px);height:clamp(34px,3vw,46px);background:linear-gradient(135deg,#2E5BFF,#7C3AED);border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:900;font-size:var(--text-md);box-shadow:var(--shadow-blue);position:relative;overflow:hidden;flex-shrink:0}
.brand-mark::after{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.3),transparent 60%)}
.brand-name{font-size:var(--text-md);font-weight:800;color:var(--gray-900);line-height:1.1}
.brand-sub{font-size:var(--text-2xs);color:var(--gray-400);letter-spacing:.04em;text-transform:uppercase}
.sidebar-church{margin:var(--sp-3);padding:var(--sp-2) var(--sp-3);background:var(--blue-50);border:1px solid var(--blue-100);border-radius:var(--radius-sm);font-size:var(--text-xs);color:var(--blue-700);font-weight:600;display:flex;gap:var(--sp-2);align-items:center}
.sidebar-nav{flex:1;padding:var(--sp-2) 0 var(--sp-4)}
.nav-label{padding:var(--sp-4) var(--sp-4) var(--sp-1);font-size:var(--text-2xs);font-weight:700;color:var(--gray-400);text-transform:uppercase;letter-spacing:.11em}
.nav-link{display:flex;align-items:center;gap:var(--sp-3);padding:var(--sp-2) var(--sp-4);margin:1px var(--sp-2);border-radius:var(--radius-sm);color:var(--gray-600);font-size:var(--text-sm);font-weight:500;transition:all var(--t-base);position:relative;overflow:hidden}
.nav-link::before{content:'';position:absolute;left:0;top:50%;transform:translateY(-50%) scaleY(0);width:3px;height:60%;background:var(--blue-600);border-radius:0 2px 2px 0;transition:transform var(--t-base)}
.nav-link:hover{background:var(--gray-50);color:var(--gray-900);transform:translateX(2px)}
.nav-link:hover::before{transform:translateY(-50%) scaleY(1)}
.nav-link.active{background:var(--blue-50);color:var(--blue-700);font-weight:600}
.nav-link.active::before{transform:translateY(-50%) scaleY(1)}
.nav-link i{width:clamp(16px,1.4vw,20px);text-align:center;font-size:var(--text-sm);flex-shrink:0}
.nav-badge{margin-left:auto;background:var(--red);color:#fff;font-size:var(--text-2xs);font-weight:700;padding:2px 7px;border-radius:10px;min-width:18px;text-align:center;animation:pulse-badge 2s ease infinite}
@keyframes pulse-badge{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.4)}50%{box-shadow:0 0 0 5px rgba(239,68,68,0)}}
.sidebar-foot{padding:var(--sp-4);border-top:1px solid var(--gray-100);position:sticky;bottom:0;background:rgba(255,255,255,.96);backdrop-filter:blur(8px)}
.user-pill{display:flex;align-items:center;gap:var(--sp-3);padding:var(--sp-2) var(--sp-3);background:var(--gray-50);border:1px solid var(--gray-100);border-radius:var(--radius);transition:background var(--t-fast)}
.user-pill:hover{background:var(--blue-50)}
.user-av{width:clamp(30px,2.5vw,38px);height:clamp(30px,2.5vw,38px);background:linear-gradient(135deg,var(--blue-600),var(--violet));border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-size:var(--text-sm);font-weight:800;flex-shrink:0}
.user-name{font-size:var(--text-sm);font-weight:600;color:var(--gray-800);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.user-role{font-size:var(--text-2xs);color:var(--gray-400);text-transform:capitalize}
.user-logout{color:var(--gray-400);margin-left:auto;transition:color var(--t-fast)}.user-logout:hover{color:var(--red)}
.hamburger{display:none;background:none;border:none;font-size:var(--text-xl);color:var(--gray-700);cursor:pointer;padding:var(--sp-2)}
.sidebar-overlay{display:none;position:fixed;inset:0;background:rgba(10,20,50,.42);z-index:190;backdrop-filter:blur(3px)}


.main{margin-left:var(--sidebar-w);flex:1;display:flex;flex-direction:column;min-height:100vh;min-height:100dvh;position:relative;z-index:1}
.topbar{height:var(--header-h);background:rgba(255,255,255,.9);backdrop-filter:blur(16px) saturate(1.4);border-bottom:1px solid var(--gray-100);display:flex;align-items:center;padding:0 var(--sp-8);gap:var(--sp-4);position:sticky;top:0;z-index:100}
.topbar-title{font-size:var(--text-xl);font-weight:800;color:var(--gray-900);flex:1;letter-spacing:-.02em}
.topbar-date{font-size:var(--text-sm);color:var(--gray-400);font-weight:500}
.content{padding:var(--sp-8);flex:1;min-width:0;max-width:100%}
.main{min-width:0}
.card,.stat-card{overflow-wrap:break-word}
.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--sp-4);flex-wrap:wrap;margin-bottom:var(--sp-6)}
.page-title{font-size:var(--text-2xl);font-weight:800;color:var(--gray-900);letter-spacing:-.03em}
.page-sub{font-size:var(--text-sm);color:var(--gray-500);margin-top:2px}
.no-print{}


.qr-cal{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,210px),1fr));gap:var(--sp-4)}
.qr-card{border:1px solid var(--gray-100);border-radius:var(--radius-lg);background:#fff;padding:var(--sp-4);text-align:center;cursor:pointer;box-shadow:var(--shadow-sm);transition:transform var(--t-base),box-shadow var(--t-base);position:relative;break-inside:avoid}
.qr-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);border-color:var(--blue-200)}
.qr-card:active{transform:scale(.98)}
.qr-card .qr-brand{min-height:34px;display:flex;align-items:center;justify-content:center;margin-bottom:var(--sp-2)}
.qr-card .qr-brand img{max-height:40px;max-width:160px;object-fit:contain}
.qr-card .qr-cn{font-weight:800;font-size:var(--text-sm);color:var(--navy);line-height:1.2}
.qr-card .qr-date{display:inline-flex;flex-direction:column;line-height:1;color:var(--blue-600);font-weight:800}
.qr-card .qr-date b{font-size:var(--text-xl)}.qr-card .qr-date i{font-style:normal;font-size:var(--text-2xs);letter-spacing:.12em}
.qr-card .qr-svc{display:block;font-size:var(--text-sm);font-weight:700;color:var(--gray-800);margin-top:4px;line-height:1.3}
.qr-card .qr-code{margin:var(--sp-3) auto 0;width:140px;height:140px}
.qr-card .qr-code svg{width:140px;height:140px}
.qr-card .qr-tag{margin-top:var(--sp-3);font-size:var(--text-2xs);font-weight:700;color:var(--blue-600);background:var(--blue-50);border-radius:999px;padding:5px 12px;display:inline-block}
@media print{.no-print{display:none!important}.qr-section .card-head .no-print{display:none}.qr-cal{grid-template-columns:repeat(2,1fr);gap:18px}.qr-card{cursor:default;box-shadow:none;border:1px solid #e5e7eb;page-break-inside:avoid}.qr-card:hover{transform:none}}


.pulse-hero{position:relative;overflow:hidden;border-radius:var(--radius-xl);padding:var(--sp-7) var(--sp-7);margin-bottom:var(--sp-6);color:#fff;background:linear-gradient(105deg,rgba(15,23,58,.94) 0%,rgba(20,33,86,.80) 42%,rgba(46,30,110,.55) 72%,rgba(36,60,150,.42) 100%),var(--ph-img,linear-gradient(135deg,#1a2b6b,#3b2d80)) center/cover no-repeat,#10204e;box-shadow:var(--shadow-lg)}
.pulse-hero::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 82% 18%,rgba(120,150,255,.22),transparent 55%);pointer-events:none}
.pulse-hero-row{position:relative;z-index:1;display:flex;justify-content:space-between;align-items:flex-start;gap:var(--sp-5);flex-wrap:wrap}
.pulse-hero-in{position:relative;z-index:1;flex:1 1 320px;max-width:640px;min-width:0}
.ph-eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:var(--text-xs);font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#cfe0ff;background:rgba(255,255,255,.12);padding:5px 12px;border-radius:999px;margin-bottom:var(--sp-3)}
.pulse-hero h2{font-size:clamp(1.45rem,3vw,2.05rem);font-weight:800;letter-spacing:-.02em;margin:0 0 var(--sp-2);line-height:1.22;padding-bottom:2px;overflow-wrap:break-word}
.pulse-hero p{font-size:var(--text-md);color:#dde6fb;margin:0;line-height:1.55}
.ph-actions{display:flex;gap:var(--sp-2);flex-wrap:wrap;justify-content:flex-end;align-items:center;margin-left:auto}
@media(max-width:760px){.ph-actions{margin-left:0;justify-content:flex-start;margin-top:var(--sp-4);width:100%}}
.btn-light{background:rgba(255,255,255,.95);color:var(--navy);border:none}
.btn-light:hover{background:#fff}
.pulse-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,250px),1fr));gap:var(--sp-4);margin-bottom:var(--sp-2)}
.pulse-card{background:var(--white);border:1px solid var(--gray-100);border-radius:var(--radius-lg);padding:var(--sp-5);box-shadow:var(--shadow-sm);position:relative;overflow:hidden;display:flex;flex-direction:column;min-height:196px;transition:transform var(--t-base),box-shadow var(--t-base);animation:card-rise .45s cubic-bezier(.34,1.56,.64,1) both}
.pulse-card::before{content:'';position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--acc,#2E5BFF);opacity:.9}
.pulse-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg)}
.pulse-clickable{cursor:pointer}
.pulse-clickable:focus-visible{outline:2px solid var(--blue-500);outline-offset:2px}
.pulse-expand{position:absolute;top:12px;right:12px;font-size:11px;color:var(--gray-300);opacity:0;transition:opacity var(--t-base),color var(--t-base);z-index:2}
.pulse-clickable:hover .pulse-expand,.pulse-clickable:focus .pulse-expand{opacity:1;color:var(--acc,#2E5BFF)}

.mx-val{font-size:clamp(2rem,5vw,2.8rem);font-weight:900;letter-spacing:-.02em;display:flex;align-items:center;gap:12px;flex-wrap:wrap;line-height:1.1}
.mx-sub{color:var(--gray-500);font-size:var(--text-sm);margin:4px 0 var(--sp-4)}
.mx-note{background:var(--blue-50);border:1px solid var(--blue-100);border-radius:12px;padding:12px 14px;font-size:var(--text-sm);color:var(--gray-700);margin:var(--sp-4) 0;line-height:1.6}
.mx-note i{color:var(--blue-600);margin-right:5px}
.mx-det{margin-top:var(--sp-4)}
.mx-det h4{font-size:var(--text-2xs);text-transform:uppercase;letter-spacing:.06em;color:var(--gray-400);font-weight:800;margin-bottom:4px}
.mx-det p{color:var(--gray-700);font-size:var(--text-sm);line-height:1.65}
.mx-ai{margin-top:var(--sp-5);border-top:1px dashed var(--gray-200);padding-top:var(--sp-4)}
.mx-ai-head{display:inline-flex;align-items:center;gap:7px;font-weight:800;font-size:var(--text-xs);color:#a4502f;background:linear-gradient(135deg,rgba(204,120,92,.13),rgba(111,61,232,.10));border:1px solid rgba(204,120,92,.32);padding:4px 11px;border-radius:20px;margin-bottom:var(--sp-3)}
.mx-ai-body{font-size:var(--text-sm);line-height:1.7;color:var(--gray-700)}
.mx-ai-off{margin-top:var(--sp-5);border-top:1px dashed var(--gray-200);padding-top:var(--sp-4);font-size:var(--text-xs);color:var(--gray-500)}
.mx-ai-off i{color:#cc785c}.mx-ai-off a{color:var(--blue-600);font-weight:600}
.pulse-grid .pulse-card:nth-child(1){animation-delay:.03s}.pulse-grid .pulse-card:nth-child(2){animation-delay:.07s}.pulse-grid .pulse-card:nth-child(3){animation-delay:.11s}.pulse-grid .pulse-card:nth-child(4){animation-delay:.15s}.pulse-grid .pulse-card:nth-child(5){animation-delay:.19s}.pulse-grid .pulse-card:nth-child(6){animation-delay:.23s}.pulse-grid .pulse-card:nth-child(7){animation-delay:.27s}.pulse-grid .pulse-card:nth-child(8){animation-delay:.31s}
.pulse-top{display:flex;align-items:center;gap:var(--sp-2);margin-bottom:var(--sp-3)}
.pulse-ic{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0}
.pulse-label{font-size:var(--text-sm);font-weight:700;color:var(--gray-600);flex:1;line-height:1.2}
.pulse-delta{font-size:var(--text-2xs);font-weight:800;padding:3px 8px;border-radius:999px;white-space:nowrap}
.pulse-delta.up{color:var(--green-dark);background:var(--green-light)}
.pulse-delta.down{color:var(--red-dark);background:var(--red-light)}
.pulse-delta.flat{color:var(--gray-500);background:var(--gray-100)}
.pulse-val{font-size:clamp(1.7rem,3.4vw,2.05rem);font-weight:800;color:var(--gray-900);letter-spacing:-.02em;line-height:1}
.pulse-sub{font-size:var(--text-2xs);color:var(--gray-400);margin-top:5px}
.pulse-spark{height:48px;margin:var(--sp-3) 0 auto;position:relative}
.pulse-spark canvas{position:absolute;inset:0;width:100%!important;height:48px!important}
.pulse-gauge{height:9px;border-radius:999px;background:var(--gray-100);margin:var(--sp-4) 0 8px;overflow:hidden}
.pulse-gauge-fill{height:100%;border-radius:999px;transition:width .9s cubic-bezier(.22,1,.36,1)}
.pulse-gauge.strong .pulse-gauge-fill{background:linear-gradient(90deg,#34d399,#10b981)}
.pulse-gauge.watch .pulse-gauge-fill{background:linear-gradient(90deg,#fbbf24,#f59e0b)}
.pulse-gauge.action .pulse-gauge-fill{background:linear-gradient(90deg,#fb7185,#ef4444)}
.pulse-band{font-size:var(--text-2xs);font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px}
.pulse-band.strong{color:var(--green-dark)}.pulse-band.watch{color:var(--amber-dark)}.pulse-band.action{color:var(--red-dark)}
.pulse-note{font-size:var(--text-2xs);color:var(--gray-500);line-height:1.45;margin-top:var(--sp-3);padding-top:var(--sp-3);border-top:1px solid var(--gray-50)}
.pulse-note i{color:var(--blue-500);opacity:.7;margin-right:3px}
.pulse-dl{display:block;color:var(--gray-400);margin-top:2px}
.skeleton{position:relative;overflow:hidden}
.skeleton .sk-line{height:12px;border-radius:6px;background:var(--gray-100)}
.skeleton::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);animation:sk 1.3s infinite}
@keyframes sk{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
@media print{.pulse-hero{background:#10204e!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}.pulse-card{box-shadow:none;border:1px solid #e5e7eb;break-inside:avoid}.ph-actions{display:none}}


.wt-controls{display:flex;flex-wrap:wrap;gap:var(--sp-5);align-items:flex-start;margin-bottom:var(--sp-4)}
.wt-ctrl > .wt-lbl{display:block;font-size:var(--text-xs);font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--gray-500);margin-bottom:9px}
.seg{display:inline-flex;background:var(--gray-100);border-radius:999px;padding:5px;gap:3px;flex-wrap:wrap}
.seg button{border:none;background:transparent;padding:10px 20px;border-radius:999px;font-weight:700;font-size:15px;color:var(--gray-600);cursor:pointer;transition:all var(--t-base);font-family:inherit}
.seg button.on{background:#fff;color:var(--blue-700);box-shadow:0 2px 9px rgba(15,23,42,.14)}
.seg button:active{transform:scale(.95)}
.wt-verses{display:flex;flex-wrap:wrap;gap:10px}
.wt-verse{border:1.5px solid var(--gray-200);background:var(--white);border-radius:14px;padding:11px 16px;cursor:pointer;text-align:left;transition:all var(--t-base);font-family:inherit;min-width:0}
.wt-verse:hover{border-color:var(--blue-300);transform:translateY(-1px)}
.wt-verse.on{border-color:var(--blue-600);background:var(--blue-50);box-shadow:0 5px 16px var(--shadow-blue,rgba(46,91,255,.2))}
.wt-verse:active{transform:scale(.97)}
.wt-verse .vr{font-weight:800;font-size:15px;color:var(--blue-700)}
.wt-verse .vt{font-size:12.5px;color:var(--gray-500);margin-top:1px}

.wcard-wrap{display:flex;justify-content:center}
.wcard{width:min(100%,650px);border-radius:26px;overflow:hidden;background:#fff;box-shadow:0 26px 72px rgba(15,23,42,.20);border:1px solid #eef1f6}
.wcard-top{padding:32px 34px 28px;color:#fff;text-align:center;background:linear-gradient(135deg,#0f1f4e 0%,#2347d9 60%,#6f3de8 100%)}
.wcard-logo{max-height:78px;max-width:240px;object-fit:contain;margin:0 auto 14px;display:block;filter:drop-shadow(0 4px 14px rgba(0,0,0,.28))}
.wcard-church{font-size:23px;font-weight:900;letter-spacing:-.01em;line-height:1.2}
.wcard-trad{font-size:13.5px;font-weight:600;opacity:.88;margin-top:6px;letter-spacing:.02em}
.wcard-body{padding:34px 38px}
.wcard-ref{text-align:center;color:#1d4ed8;font-weight:800;font-size:17px;letter-spacing:.04em}
.wcard-verse{font-size:24px;line-height:1.5;font-weight:600;color:#0f172a;text-align:center;margin:11px 0 0;font-style:italic}
.wcard-rule{width:66px;height:4px;border-radius:3px;background:linear-gradient(90deg,#2E5BFF,#6f3de8);margin:26px auto}
.wcard-headline{font-size:27px;font-weight:900;color:#0f172a;text-align:center;margin:0 0 16px;letter-spacing:-.01em;line-height:1.25}
.wcard-reflection{font-size:18px;line-height:1.78;color:#1f2937;margin:0}
.wcard-block{margin-top:22px;font-size:17px;line-height:1.72;color:#1f2937}
.wcard-block b,.wcard-prayer b{display:block;color:#1d4ed8;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px;font-weight:800}
.wcard-prayer{margin-top:24px;background:linear-gradient(135deg,#eef4ff,#f6f0ff);border-radius:18px;padding:20px 22px;font-size:17px;line-height:1.72;color:#1f2937;font-style:italic}
.wcard-prayer b{color:#6f3de8;font-style:normal}
.wcard-foot{padding:18px 30px;text-align:center;background:#f8fafc;color:#475569;font-size:13.5px;font-weight:600;border-top:1px solid #eef1f6}
.wcard-foot .cx{color:#6f3de8;margin:0 9px;font-size:15px}
.wcard[data-format=pocket]{width:min(100%,430px)}
.wcard[data-format=pocket] .wcard-reflection,.wcard[data-format=pocket] .wcard-meaning{display:none}
.wcard[data-format=pocket] .wcard-body{padding:26px 28px}
.wcard[data-format=pocket] .wcard-top{padding:26px 26px 22px}
.wcard[data-format=pocket] .wcard-verse{font-size:21px}
.wcard[data-format=pocket] .wcard-headline{font-size:23px;margin-bottom:12px}
.wcard[data-format=pocket] .wcard-rule{margin:18px auto}
.wt-ai-note{text-align:center;color:#6f3de8;font-weight:700;font-size:13px;margin-top:12px}
@media(max-width:560px){.wcard-body{padding:26px 22px}.wcard-verse{font-size:21px}.wcard-headline{font-size:23px}.wcard-reflection{font-size:16.5px}.wt-controls{gap:var(--sp-4)}}


.mig-inside{display:flex;gap:var(--sp-3);align-items:flex-start;padding:var(--sp-3) 0;border-bottom:1px solid var(--gray-50)}
.mig-inside:last-of-type{border-bottom:none}
.mig-inside>i{width:22px;text-align:center;font-size:16px;margin-top:2px;flex-shrink:0}
.mig-inside strong{display:block;color:var(--gray-800);font-size:var(--text-sm)}
.mig-inside span{display:block;color:var(--gray-500);font-size:var(--text-xs);line-height:1.5;margin-top:2px}
.mig-steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:var(--sp-3)}
.mig-steps li{display:flex;gap:var(--sp-3);align-items:flex-start}
.mig-num{flex-shrink:0;width:26px;height:26px;border-radius:50%;background:var(--blue-50);color:var(--blue-700);font-weight:800;font-size:var(--text-xs);display:flex;align-items:center;justify-content:center}
.mig-step-t{font-size:var(--text-sm);font-weight:700;color:var(--gray-800)}
.mig-step-d{font-size:var(--text-xs);color:var(--gray-500);line-height:1.5;margin-top:2px}


.grid{display:grid;gap:var(--sp-4)}
.grid-2{grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))}
.grid-3{grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr))}
.grid-auto{grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr))}

.int-masonry{columns:3 320px;column-gap:var(--sp-4)}
.int-masonry>.card{break-inside:avoid;-webkit-column-break-inside:avoid;page-break-inside:avoid;margin-bottom:var(--sp-4);width:100%}
@media(max-width:1100px){.int-masonry{columns:2 300px}}
@media(max-width:680px){.int-masonry{columns:1}}

.set-sec{margin:var(--sp-6) 0 var(--sp-3)}
.set-sec.first{margin-top:var(--sp-2)}
.set-sec h3{font-size:var(--text-md);font-weight:700;color:var(--gray-800);display:flex;align-items:center;gap:var(--sp-2);margin:0;letter-spacing:-.01em}
.set-sec h3 i{color:var(--blue-600)}
.set-sec p{font-size:var(--text-sm);color:var(--gray-500);margin:4px 0 0}
.diag-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,290px),1fr));gap:0 var(--sp-6)}
.diag-row{display:flex;align-items:flex-start;gap:var(--sp-3);padding:var(--sp-2) 0;border-bottom:1px solid var(--gray-50)}
.diag-ic{flex:0 0 auto;width:18px;text-align:center;margin-top:1px;font-size:var(--text-sm)}
.diag-ok .diag-ic{color:var(--green)}.diag-bad .diag-ic{color:var(--red)}.diag-opt .diag-ic{color:var(--gray-300)}
.diag-row .d-lbl{font-weight:600;color:var(--gray-800);font-size:var(--text-sm)}
.diag-row .d-det{font-size:var(--text-xs);color:var(--gray-500);line-height:1.4}

.int-row{padding:var(--sp-4) 0;border-top:1px solid var(--gray-100)}
.int-row:first-child{border-top:none;padding-top:0}
.int-row-head{display:flex;align-items:center;gap:var(--sp-2);margin-bottom:var(--sp-2);flex-wrap:wrap}
.int-row-head i{width:18px;text-align:center;flex-shrink:0}
.int-name{font-weight:700;color:var(--gray-800);font-size:var(--text-sm)}
.int-desc{font-weight:400;color:var(--gray-400);font-size:var(--text-xs)}
.int-actions{display:flex;align-items:center;gap:var(--sp-2);margin-top:var(--sp-3);flex-wrap:wrap}
.smtp-providers{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:var(--sp-3)}
.smtp-prov-label{font-size:var(--text-xs);font-weight:700;color:var(--gray-500)}
.smtp-prov-label i{color:var(--amber)}
.prov-btn{display:inline-flex;align-items:center;gap:6px;font-size:var(--text-xs);font-weight:600;padding:6px 11px;border-radius:9px;border:1px solid var(--gray-200);background:var(--white);color:var(--gray-700);cursor:pointer;transition:border-color var(--t-base),color var(--t-base),background var(--t-base),transform var(--t-base)}
.prov-btn:hover{border-color:var(--blue-200);color:var(--blue-700);background:var(--blue-50);transform:translateY(-1px)}
.prov-btn:active{transform:scale(.96)}
.prov-btn i{color:var(--blue-600)}
.smtp-hint{font-size:var(--text-xs);line-height:1.65;color:var(--gray-600);background:var(--blue-50);border:1px solid var(--blue-100);border-radius:10px;padding:10px 13px;margin-bottom:var(--sp-3)}
.smtp-hint a{color:var(--blue-700);font-weight:600}.smtp-hint i{color:var(--blue-600)}

.tabs{display:flex;gap:4px;border-bottom:1px solid var(--gray-100);flex-wrap:wrap}
.tab{padding:9px 16px;font-size:var(--text-sm);font-weight:600;color:var(--gray-500);text-decoration:none;border-bottom:2px solid transparent;transition:color var(--t-base),border-color var(--t-base)}
.tab:hover{color:var(--blue-600)}
.tab.active{color:var(--blue-700);border-bottom-color:var(--blue-600)}
.icon-btn{appearance:none;border:1px solid var(--gray-200);background:var(--white);color:var(--gray-500);width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:12px;transition:color var(--t-base),border-color var(--t-base),background var(--t-base)}
.icon-btn:hover{color:var(--blue-600);border-color:var(--blue-200);background:var(--blue-50)}
.plan-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--gray-100)}
.plan-type{font-size:var(--text-2xs);text-transform:uppercase;letter-spacing:.04em;font-weight:700;color:var(--gray-400);min-width:84px}
.plan-type-song{color:var(--blue-600)}.plan-type-sermon{color:var(--violet)}
.plan-add{margin-top:var(--sp-4);padding-top:var(--sp-4);border-top:1px dashed var(--gray-200)}
.team-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid var(--gray-100)}
.plan-card{text-decoration:none;color:inherit;transition:transform var(--t-base),box-shadow var(--t-base)}
.plan-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg)}
.acct-bar{height:8px;border-radius:5px;background:var(--gray-100);overflow:hidden;margin-top:5px}
.acct-bar>span{display:block;height:100%;background:linear-gradient(90deg,var(--blue-500),var(--blue-600))}
.acct-bar.over>span{background:linear-gradient(90deg,#f59e0b,#ef4444)}
.int-out{font-size:var(--text-xs)}
.int-ok{color:var(--green-dark);font-weight:600}
.int-err{color:var(--red-dark);font-weight:600}


.card{background:var(--white);border-radius:var(--radius-lg);border:1px solid var(--gray-100);box-shadow:var(--shadow-sm);transition:box-shadow var(--t-base),transform var(--t-base);overflow:hidden}
.card:hover{box-shadow:var(--shadow-md)}
.card-head{padding:var(--sp-4) var(--sp-6);border-bottom:1px solid var(--gray-100);display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3)}
.card-title{font-size:var(--text-md);font-weight:700;color:var(--gray-800)}
.card-body{padding:var(--sp-6)}.card-body-0{padding:0}


.stat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(clamp(160px,18vw,224px),1fr));gap:var(--sp-4);margin-bottom:var(--sp-6)}
.stat-card{background:var(--white);border-radius:var(--radius-lg);border:1px solid var(--gray-100);padding:var(--sp-5);box-shadow:var(--shadow-sm);display:flex;gap:var(--sp-4);align-items:flex-start;position:relative;overflow:hidden;transition:all var(--t-base);animation:card-rise .45s cubic-bezier(.34,1.56,.64,1) both}
.stat-card::after{content:'';position:absolute;inset:0;background:linear-gradient(135deg,transparent 60%,rgba(46,91,255,.045));pointer-events:none}
.stat-card:hover{box-shadow:var(--shadow-lg);transform:translateY(-3px)}
.stat-card:hover,.stat-card:focus-within{overflow:visible}
.stat-card:nth-child(1){animation-delay:.04s}.stat-card:nth-child(2){animation-delay:.09s}.stat-card:nth-child(3){animation-delay:.14s}.stat-card:nth-child(4){animation-delay:.19s}.stat-card:nth-child(5){animation-delay:.24s}.stat-card:nth-child(6){animation-delay:.29s}.stat-card:nth-child(7){animation-delay:.34s}.stat-card:nth-child(8){animation-delay:.39s}
@keyframes card-rise{from{opacity:0;transform:translateY(16px) scale(.97)}to{opacity:1;transform:none}}
.stat-icon{width:clamp(40px,3.5vw,52px);height:clamp(40px,3.5vw,52px);border-radius:var(--radius);display:flex;align-items:center;justify-content:center;font-size:clamp(16px,1.5vw,21px);line-height:1;text-align:center;flex-shrink:0}
.stat-icon i{line-height:1;display:block}
.stat-icon.blue{background:var(--blue-50);color:var(--blue-600)}.stat-icon.green{background:var(--green-light);color:var(--green-dark)}.stat-icon.amber{background:var(--amber-light);color:var(--amber-dark)}.stat-icon.red{background:var(--red-light);color:var(--red-dark)}.stat-icon.purple{background:var(--purple-light);color:var(--purple)}.stat-icon.navy{background:#e8ecf8;color:var(--navy)}
.stat-value{font-size:var(--text-2xl);font-weight:800;color:var(--gray-900);line-height:1.05;letter-spacing:-.03em}
.stat-label{font-size:var(--text-xs);color:var(--gray-500);margin-top:var(--sp-1);font-weight:500}

.stat-card>div{min-width:0;max-width:100%}
.stat-value{white-space:nowrap}

.stat-grid-stack .stat-card{flex-direction:column;align-items:stretch;gap:var(--sp-3)}
.stat-grid-stack .stat-top{display:flex;align-items:center;gap:var(--sp-3);min-width:0;width:100%}
.stat-grid-stack .stat-label{margin-top:0;flex:1 1 auto;min-width:0}
.stat-grid-stack .stat-value{margin-top:auto;line-height:1;align-self:flex-start}

.stat-value,.pulse-val,.mx-val,.pulse-delta,.pulse-sub,.stat-chip,[data-countup]{font-variant-numeric:tabular-nums;font-feature-settings:'tnum' 1,'lnum' 1}
.stat-trend{font-size:var(--text-xs);margin-top:var(--sp-2);font-weight:600;display:flex;gap:3px;align-items:center}
.stat-trend.up{color:var(--green-dark)}.stat-trend.down{color:var(--red-dark)}


.table-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
.data-table{width:100%;border-collapse:collapse}
.data-table th{background:var(--gray-50);padding:var(--sp-2) var(--sp-4);text-align:left;font-size:var(--text-2xs);font-weight:700;color:var(--gray-500);text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid var(--gray-200);white-space:nowrap}
.data-table td{padding:var(--sp-3) var(--sp-4);border-bottom:1px solid var(--gray-100);font-size:var(--text-sm);color:var(--gray-700);vertical-align:middle}
.data-table tr:last-child td{border-bottom:none}
.data-table tbody tr{transition:background var(--t-fast);animation:row-fade .28s ease both}
@keyframes row-fade{from{opacity:0;transform:translateX(-4px)}to{opacity:1;transform:none}}
.data-table tbody tr:hover td{background:var(--blue-50)}


.badge{display:inline-flex;align-items:center;gap:var(--sp-1);padding:3px var(--sp-2);border-radius:20px;font-size:var(--text-2xs);font-weight:700;letter-spacing:.02em;white-space:nowrap;text-transform:capitalize}
.badge-active,.badge-healthy{background:var(--green-light);color:#065f46}
.badge-inactive{background:var(--gray-100);color:var(--gray-500)}
.badge-watch{background:var(--amber-light);color:#92400e}
.badge-atrisk,.badge-at_risk{background:var(--red-light);color:#991b1b;animation:pulse-red 2.2s ease infinite}
.badge-critical{background:#7f1d1d;color:#fff;animation:pulse-red 1.6s ease infinite}
.badge-visitor{background:var(--blue-50);color:var(--blue-700)}
@keyframes pulse-red{0%,100%{opacity:1}50%{opacity:.74}}


.eng-wrap{display:flex;align-items:center;gap:var(--sp-2)}
.eng-bar{height:6px;border-radius:3px;background:var(--gray-200);overflow:hidden;flex:1;max-width:90px}
