function acFitStat(el){
  if(!el||!el.classList||!el.classList.contains('stat-value'))return;
  var card=el.closest('.stat-card'); if(!card)return;
  var cs=getComputedStyle(card), icon=card.querySelector('.stat-icon');
  var gap=parseFloat(cs.columnGap||cs.gap)||0;
  var isStack=!!el.closest('.stat-grid-stack');            // main dashboard: number spans the FULL card width (below the icon)
  var avail=card.clientWidth-(parseFloat(cs.paddingLeft)||0)-(parseFloat(cs.paddingRight)||0)-(isStack?0:((icon?icon.getBoundingClientRect().width:0)+gap));
  if(!(avail>8)){el.style.fontSize='';return;}
  var MIN=14, MAX=56, target=avail*0.97, fs, guard=0;     // a hair of breathing room so it stays contained
  if(isStack){                                             // main dashboard: grow to fill...
    fs=MAX; el.style.fontSize=fs+'px';
    while(el.scrollWidth>target&&fs>MIN&&guard++<160){fs-=0.5;el.style.fontSize=fs+'px';} // ...shrink long numbers to fit
  } else {                                                  // other pages: keep the CSS base size, shrink only if needed
    el.style.fontSize=''; fs=parseFloat(getComputedStyle(el).fontSize)||24;
    while(el.scrollWidth>target&&fs>MIN&&guard++<120){fs-=0.5;el.style.fontSize=fs+'px';}
  }
}
function countUp(el,target,dur=1500,prefix='',suffix=''){
  var fin=prefix+Math.round(target).toLocaleString()+suffix;
  el.textContent=fin; acFitStat(el); // render the FINAL figure once + scale it to one line, then animate at that fitted size
  if((window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches)||!(target>0)){return;}
  var start=performance.now();
  function step(ts){var p=Math.min((ts-start)/dur,1);var e=1-Math.pow(1-p,4); // ease-out-quart: a soft, buttery deceleration
    el.textContent=prefix+Math.round(target*e).toLocaleString()+suffix;
    if(p<1)requestAnimationFrame(step);else el.textContent=fin;}
  requestAnimationFrame(step);
}
const _io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.1});
document.querySelectorAll('.fade-in').forEach(el=>_io.observe(el));
document.querySelectorAll('[data-countup]').forEach(el=>countUp(el,parseFloat(el.dataset.countup),1400,el.dataset.prefix||'',el.dataset.suffix||''));
document.querySelectorAll('.stat-value:not([data-countup])').forEach(acFitStat); // fit static (non-animated) stat numbers too
addEventListener('resize',function(){clearTimeout(window._acFitT);window._acFitT=setTimeout(function(){document.querySelectorAll('.stat-value').forEach(acFitStat);},150);});
function fillEng(){document.querySelectorAll('.eng-fill[data-w]').forEach(el=>{requestAnimationFrame(()=>el.style.width=el.dataset.w+'%')})}
fillEng();
window.acMD=function(t){try{return DOMPurify.sanitize(marked.parse(t||''))}catch(e){return (t||'').replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}};
try{var ac=JSON.parse(localStorage.getItem('ac.prefs')||'{}');ac.lastPage=location.search;localStorage.setItem('ac.prefs',JSON.stringify(ac));}catch(e){}
if('serviceWorker'in navigator){navigator.serviceWorker.register('?action=sw').catch(()=>{});}
document.querySelectorAll('textarea[data-draft],input[data-draft]').forEach(el=>{const k='ac.draft.'+el.dataset.draft;try{if(!el.value&&localStorage.getItem(k))el.value=localStorage.getItem(k);}catch(e){}
  el.addEventListener('input',()=>{try{localStorage.setItem(k,el.value)}catch(e){}});
  const f=el.closest('form');if(f)f.addEventListener('submit',()=>{try{localStorage.removeItem(k)}catch(e){}});});


