const HELP_START=["How do I add a new member?","How do I record a gift or donation?","How do I print a year-end giving statement?","How do I import members from Excel or a CSV?","Who needs follow-up this week?","How do I run or export a report?"];
function helpToggle(){var p=document.getElementById('helpPanel');var open=p.style.display==='flex';p.style.display=open?'none':'flex';if(!open&&!p.dataset.greeted){p.dataset.greeted='1';helpBubble("Hi there! 👋 I'm your Office Helper. Ask me anything about Free Church ChMS — I'll point you to the right guide instantly"+(AC_CLAUDE?", and <b>Claude</b> can give you a tailored answer too.":"."),"bot");helpChips(HELP_START);}}
try{if(new URLSearchParams(location.search).get('help'))setTimeout(helpToggle,150);}catch(e){}
function helpBubble(html,who){var log=document.getElementById('helpLog');var d=document.createElement('div');
 d.style.cssText='max-width:88%;padding:10px 13px;border-radius:14px;font-size:13px;line-height:1.55;'+(who==='me'?'align-self:flex-end;background:linear-gradient(135deg,var(--blue-600),var(--violet));color:#fff;border-bottom-right-radius:4px':'align-self:flex-start;background:#fff;border:1px solid var(--gray-100);color:var(--gray-800);border-bottom-left-radius:4px');
 d.innerHTML=html;log.appendChild(d);log.scrollTop=log.scrollHeight;return d;}
function helpChips(list){var c=document.getElementById('helpChips');c.innerHTML='';list.forEach(function(q){var b=document.createElement('button');b.className='quick-chip';b.textContent=q;b.onclick=function(){helpAsk(q)};c.appendChild(b);});}
function helpMatch(t){t=(t||'').toLowerCase();var best=null,score=0;HELP_KB.forEach(function(e){var s=0;e.k.forEach(function(kw){if(t.indexOf(kw)>=0)s+=kw.length;});if(s>score){score=s;best=e;}});return score>0?best:null;}
function kbSearch(t){t=(t||'').toLowerCase();var sc=[];KBASE.forEach(function(a){var hay=(a.title+' '+a.summary+' '+a.category).toLowerCase(),s=0;t.split(/[^a-z0-9]+/).forEach(function(w){if(w.length>2&&hay.indexOf(w)>=0)s+=w.length;});if(s>0)sc.push([s,a]);});sc.sort(function(a,b){return b[0]-a[0];});return sc.slice(0,3).map(function(x){return x[1];});}
function kbLinks(arts){if(!arts||!arts.length)return'';return'<div style="margin-top:8px;display:flex;flex-direction:column;gap:5px">'+arts.map(function(a){return '<a href="https://freechms.org/kb/#'+a.slug+'" target="_blank" rel="noopener" class="quick-chip" style="text-decoration:none;display:inline-flex;gap:6px;align-items:center"><i class="fa-solid '+(a.icon||'fa-book')+'" style="color:var(--blue-600)"></i> '+acEsc(a.title)+'</a>';}).join('')+'</div>';}
function askClaudeBtn(){return AC_CLAUDE?'<button class="quick-chip" style="margin-top:8px;border-color:rgba(204,120,92,.55);color:#a4502f;font-weight:700" onclick="helpClaude(lastQ)">✦ Ask Claude for a fuller answer</button>':'';}
function helpClaude(q){q=(q||lastQ||'').trim();if(!q)return;
 if(!AC_CLAUDE){helpBubble('✦ <b>AI answers with Claude</b> switch on once your church connects an Anthropic Claude key — your key stays on your server.<div style="margin-top:8px"><a href="?page=settings" class="btn btn-primary btn-xs" style="text-decoration:none">Connect Claude →</a></div>','bot');return;}
 var t=helpBubble('<span style="opacity:.65">✦ Claude is thinking…</span>','bot');var fd=new FormData();fd.append('q',q);
 fetch('?action=helper_ai',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(d){
   if(d.error){t.innerHTML=(d.error==='no_key')?'✦ Connect a Claude key in <b>Settings</b> to enable AI answers.':'⚠ '+acEsc(d.error);return;}
   t.innerHTML='<div style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:800;color:#a4502f;margin-bottom:5px">✦ Claude</div>'+acMD(d.answer);
   document.getElementById('helpLog').scrollTop=999999;
 }).catch(function(){t.textContent='⚠ Request failed.';});}
function helpAsk(text){text=(text||'').trim();if(!text)return;lastQ=text;document.getElementById('helpIn').value='';helpBubble(acEsc(text),'me');
 var m=helpMatch(text);
 if(m){var html=m.a;if(m.link){var _ext=/^(kb\/|https?:)/.test(m.link[1]);html+='<div style="margin-top:8px"><a href="'+m.link[1]+'"'+(_ext?' target="_blank" rel="noopener"':'')+' class="btn btn-primary btn-xs" style="text-decoration:none">'+acEsc(m.link[0])+' →</a></div>';}
   html+=kbLinks(kbSearch(text))+askClaudeBtn();helpBubble(html,'bot');
   helpChips(HELP_KB.filter(function(e){return e!==m;}).slice(0,3).map(function(e){return e.q;}));}
 else{var arts=kbSearch(text);
   if(arts.length){helpBubble("Here are the guides that best match"+(AC_CLAUDE?" — or ask Claude for a tailored answer":"")+":"+kbLinks(arts)+askClaudeBtn(),"bot");}
   else{helpBubble("I couldn't pin that to one guide. Browse the full <b>Knowledge Base</b>"+(AC_CLAUDE?", or let Claude help":"")+":<div style=\"margin-top:8px\"><a href=\"https://freechms.org/kb/\" target=\"_blank\" rel=\"noopener\" class=\"btn btn-primary btn-xs\" style=\"text-decoration:none\">Open Knowledge Base →</a></div>"+askClaudeBtn(),"bot");}
   helpChips(HELP_START);}}
</script>
</body></html><?php
}




function isFirstRun(): bool {
    $db = getDB();
    $users = $db->query("SELECT email,password FROM users WHERE role IN ('admin','superadmin')")->fetchAll();
    if (empty($users)) return true;
    foreach ($users as $u) {
        if (!in_array($u['email'], ['admin@aichurch.com','admin@sermonassist.com',OWNER_EMAIL], true)) return false;
        if (!password_verify('admin123', $u['password'])) return false;
    }
    return true;
}

function renderLogin(): void {
    $stage = $_GET['stage'] ?? 'login';
    $err = $_GET['err'] ?? '';
    $msg = match($err) {
        'bad'         => 'Invalid email or password.',
        'locked'      => 'Too many sign-in attempts. Please wait about 15 minutes and try again.',
        'code'        => 'Invalid authenticator code — try again.',
        'setup_pw'    => 'Passwords do not match.',
        'setup_short' => 'Password must be at least 8 characters.',
        'setup_email' => 'Please enter a valid email address.',
        'setup_exists'=> 'That email is already registered.',
        'default'     => 'This account still uses the default password and is locked for security. Complete first-time setup or reset it via another administrator.',
        'regclosed'   => 'New-account registration is by request. Use the “Request access” button below.',
        'reqfields'   => 'Please fill in your name, a valid email, and your church or organization.',
        'reqrate'     => 'We’ve received several requests from your network — please try again a little later.',
        default       => ''
    };
    $firstRun    = isFirstRun();
    
