function renderDashboard(): void {
    $db = getDB(); $s = getStats();
    $atRisk = $db->query("SELECT id,first_name,last_name,engagement_score,engagement_tier,last_attended FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active' ORDER BY engagement_score ASC LIMIT 6")->fetchAll();
    $recent = $db->query("SELECT g.amount,g.date,g.method,m.first_name,m.last_name FROM giving g LEFT JOIN members m ON m.id=g.member_id ORDER BY g.date DESC, g.id DESC LIMIT 6")->fetchAll();
    startPage('Dashboard', 'dashboard');
    $defWeak = false;
    foreach ($db->query("SELECT password FROM users WHERE email IN ('admin@aichurch.com','admin@sermonassist.com',".$db->quote(OWNER_EMAIL).")")->fetchAll(PDO::FETCH_COLUMN) as $hp) { if ($hp && password_verify('admin123', $hp)) { $defWeak = true; break; } }
    if ($defWeak): ?>
    <div class="alert alert-warning"><i class="fa-solid fa-triangle-exclamation"></i> <div>A built-in account still uses the <strong>default password</strong>. Change it now (<a href="?page=settings" style="text-decoration:underline">your password in Settings</a><?php if(isAdmin()): ?>, and others in <a href="?page=admin_users" style="text-decoration:underline">Users &amp; Roles</a><?php endif; ?>) and enable two-factor authentication.</div></div>
    <?php endif; ?>
    <div class="page-head"><div><div class="page-title"><?=h(t(date('G')<12?'Good morning':(date('G')<18?'Good afternoon':'Good evening')))?> 👋</div><div class="page-sub">Here's your church at a glance — <?=date('l, F j, Y')?></div></div>
      <div style="display:flex;gap:var(--sp-2);align-items:center;flex-wrap:wrap">
        <form method="POST" action="?action=recalc_engagement"><input type="hidden" name="return" value="dashboard"><button class="btn btn-outline"><i class="fa-solid fa-arrows-rotate"></i> Recalculate engagement</button></form>
      </div>
    </div>
    <div class="stat-grid stat-grid-stack">
      <?php
      $cards = [
        ['fa-users','blue',(string)$s['members'],'Active members','','','Members currently marked active in your directory'],
        ['fa-dollar-sign','green',number_format($s['ytd_giving'],0),'YTD giving','$','','Total giving received so far this calendar year'],
        ['fa-clipboard-check','navy',number_format($s['avg_attend'],0),'Avg attendance (90d)','','','Average service headcount over the last 90 days'],
        ['fa-triangle-exclamation','red',(string)$s['at_risk'],'At-risk members','','','Active members whose engagement has slipped into the at-risk or critical range'],
        ['fa-calendar-day','purple',number_format($s['this_month'],0),'Giving this month','$','','Total giving received so far this calendar month'],
        ['fa-hands-helping','amber',(string)$s['volunteers'],'Active volunteers','','','People currently serving in a volunteer role'],
        ['fa-people-group','blue',(string)$s['groups'],'Small groups','','','Active small groups and ministries'],
        ['fa-door-open','green',(string)$s['visitors'],'Visitors','','','People marked as visitors — not yet members'],
      ];
      foreach ($cards as [$icon,$col,$val,$label,$pre,$suf,$tip]): ?>
      <div class="stat-card"><div class="stat-top"><div class="stat-icon <?=$col?>"><i class="fa-solid <?=$icon?>"></i></div><div class="stat-label"><?=$label?><?php if($tip): ?> <span class="tip" tabindex="0" data-tip="<?=h($tip)?>"><i class="fa-solid fa-circle-info" style="font-size:11px"></i></span><?php endif; ?></div></div>
        <div class="stat-value" data-countup="<?=h(str_replace(',','',$val))?>" data-prefix="<?=$pre?>" data-suffix="<?=$suf?>"><?=$pre.$val.$suf?></div></div>
      <?php endforeach; ?>
    </div>
    <div class="grid grid-2">
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-chart-area" style="color:var(--blue-600)"></i> Giving trend</div></div><div class="card-body"><div style="height:260px"><canvas id="dashGiving"></canvas></div></div></div>
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-chart-column" style="color:var(--navy)"></i> Attendance</div></div><div class="card-body"><div style="height:260px"><canvas id="dashAttend"></canvas></div></div></div>
    </div>
    <div class="grid grid-2" style="margin-top:var(--sp-4)">
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-heart-pulse" style="color:var(--red)"></i> Needs attention</div><a href="?page=pastoral" class="btn btn-ghost btn-sm">View all</a></div>
        <div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Engagement</th><th>Last seen</th><th></th></tr></thead><tbody>
        <?php if(!$atRisk): ?><tr><td colspan="4"><div class="empty" style="padding:var(--sp-6)"><i class="fa-solid fa-face-smile"></i><div>No one is at risk right now. 🎉</div></div></td></tr><?php endif; ?>
        <?php foreach($atRisk as $m): $sc=(int)$m['engagement_score']; $cl=$sc>=70?'high':($sc>=45?'mid':'low'); ?>
          <tr><td><strong><?=h($m['first_name'].' '.$m['last_name'])?></strong></td>
            <td><div class="eng-wrap"><div class="eng-bar"><div class="eng-fill <?=$cl?>" data-w="<?=$sc?>"></div></div><span class="eng-score"><?=$sc?></span></div></td>
            <td style="color:var(--gray-400)"><?=h($m['last_attended'] ?: '—')?></td>
            <td><a href="?page=pastoral&member=<?=$m['id']?>" class="btn btn-outline btn-xs">Reach out</a></td></tr>
        <?php endforeach; ?>
        </tbody></table></div></div>
      </div>
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-gift" style="color:var(--green)"></i> Recent giving</div><a href="?page=giving" class="btn btn-ghost btn-sm">View all</a></div>
        <div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Giver</th><th>Amount</th><th>Method</th><th>Date</th></tr></thead><tbody>
        <?php if(!$recent): ?><tr><td colspan="4"><div class="empty" style="padding:var(--sp-6)"><i class="fa-solid fa-gift"></i><div>No gifts recorded yet.</div></td></tr><?php endif; ?>
        <?php foreach($recent as $g): ?>
          <tr><td><?=h(trim(($g['first_name']??'').' '.($g['last_name']??'')) ?: 'Anonymous')?></td><td><strong style="color:var(--green-dark)"><?=fmt((float)$g['amount'])?></strong></td><td style="text-transform:capitalize"><?=h($g['method'])?></td><td style="color:var(--gray-400)"><?=h($g['date'])?></td></tr>
        <?php endforeach; ?>
        </tbody></table></div></div>
      </div>
    </div>
    <script>
    fetch('?action=analytics_data').then(r=>r.json()).then(d=>{
      const gv=document.getElementById('dashGiving'), at=document.getElementById('dashAttend');
      const dark=document.documentElement.getAttribute('data-theme')==='dark';
      const gridC=dark?'rgba(255,255,255,.08)':'#f1f3f9', tickC=dark?'#aab4cf':'#64748b';
      const barC=dark?'#22b6f0':'#0f1f4e';   // crisp Lush Cerulean Blue attendance bars in Dark Mode (8:1 on the dark canvas)
      const grad=(c,col)=>{const ctx=c.getContext('2d');const g=ctx.createLinearGradient(0,0,0,260);g.addColorStop(0,col+'55');g.addColorStop(1,col+'00');return g;};
      new Chart(gv,{type:'line',data:{labels:d.giving_trend.labels,datasets:[{data:d.giving_trend.data,borderColor:'#2E5BFF',backgroundColor:grad(gv,'#2E5BFF'),fill:true,tension:.4,borderWidth:2.5,pointRadius:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{color:tickC,callback:v=>'$'+v.toLocaleString()},grid:{color:gridC}},x:{ticks:{color:tickC},grid:{display:false}}}}});
      new Chart(at,{type:'bar',data:{labels:d.attendance_trend.labels,datasets:[{data:d.attendance_trend.data,backgroundColor:barC,borderRadius:6,maxBarThickness:26}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{color:tickC},grid:{color:gridC}},x:{ticks:{color:tickC},grid:{display:false}}}}});
    });
    </script>
    <?php endPage();
}




