    <script>
    var PULSE=null;
    var HAVE_CLAUDE=<?= getSetting('anthropic_api_key') ? 'true' : 'false' ?>;
    var CLAUDE_BADGE=<?= json_encode(claudeSpark(15), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;
    var MX={
      asa:{what:"The average number of people physically gathering each week, across the last four weeks.",why:"Attendance is the truest early-warning signal of church health — it moves before giving or membership do. Steady or rising means people are prioritising being together.",act:"If it is softening, open Pastoral Care to see who has stopped coming and make a few personal calls this week."},
      active:{what:"Everyone currently marked active in your member directory.",why:"This is your committed core. Growth means your welcome and assimilation are working; a plateau means new people aren't sticking yet.",act:"Review everyone who joined in the last 90 days and make sure each has a clear next step — a group, a serving role, a coffee."},
      new_people:{what:"First-time guests and new members added in the last 90 days.",why:"This is your 'front door.' A healthy front door refills what every church quietly loses out the back.",act:"Confirm every newcomer got a welcome within 48 hours — a Visitor Welcome workflow can make that automatic."},
      retention:{what:"The share of people who attended in the prior 90 days who are still attending now.",why:"This is your 'back door.' Keeping the people you already have is far less costly than finding new ones.",act:"For anyone who has dropped off, a warm 'we've missed you' note works wonders — start with the at-risk list."},
      at_risk:{what:"Active members whose behavioural engagement has fallen into the at-risk or critical band.",why:"These are the people most likely to slip away quietly — and caught early, most can be lovingly re-engaged.",act:"Assign each name to a staff member or elder in Pastoral Care and reach out personally this week."},
      giving_month:{what:"Total giving received so far this calendar month, compared with the same month last year.",why:"Giving funds the mission and mirrors engagement. Month-over-year is the fairest read because it controls for seasonality.",act:"If it is behind, a short, gratitude-first giving update from the platform usually helps."},
      participation:{what:"The percentage of your active members who have given at least once this year.",why:"A broad base of givers is far more resilient than a handful of large donors — and it reflects discipleship, not just dollars.",act:"Teach generosity warmly from the front, and keep giving effortless (online + text giving are built in)."},
      engagement:{what:"The average behavioural engagement score across active members — blending attendance, giving, serving and groups.",why:"One number for 'how connected is our church?' It folds every signal into a single health reading.",act:"Focus on nudging the 'watch' group upward; one more touchpoint each lifts the whole average."},
      forecast_giving:{what:"A projection of your full-year giving, blending your year-to-date pace with the 12-month trend.",why:"It lets you steer the budget before year-end instead of reacting after the fact.",act:"If you're tracking behind last year, plan a year-end appeal now; if ahead, consider a faith-stretch goal."},
      giving_at_risk:{what:"The trailing-12-month giving from established givers (3+ gifts) who have now gone quiet for 60+ days.",why:"This is recurring money genuinely in jeopardy — and it is usually recoverable with a personal touch.",act:"Call or visit these givers this week; most lapses are life circumstances, not a decision to leave."},
      donor_concentration:{what:"The share of this year's giving that comes from your top 10% of donors.",why:"High concentration is a budget risk — if one or two families move on, the budget wobbles.",act:"Broaden participation: celebrate gifts of every size and make first-time giving easy."},
      forecast_attendance:{what:"Projected weekly attendance about eight weeks out, from the trend of your last twelve services.",why:"An early heads-up so you can act before a dip hardens into a pattern.",act:"If the trend points down, reach out to recent no-shows now — momentum is easier to keep than to rebuild."}
    };
    function openMetric(key,type){
      var list=(type==='forecast'?(PULSE&&PULSE.forecast):(PULSE&&PULSE.metrics))||[],m=null;
      for(var i=0;i<list.length;i++){if(list[i].key===key){m=list[i];break;}}
      if(!m)return;
      var acc=ACCENT[m.accent]||'#2E5BFF',soft=SOFT[m.accent]||SOFT.blue,det=MX[key]||{};
      document.getElementById('mxTitle').innerHTML='<span class="pulse-ic" style="background:'+soft+';color:'+acc+'"><i class="fa-solid '+m.icon+'"></i></span> '+m.label;
      var chip=(type==='forecast')?((m.delta!=null&&m.delta!==undefined)?deltaChipRaw(m.delta,m.goodUp):''):deltaChip(m);
      var visual='';
      if(m.kind==='gauge'){visual='<div class="pulse-gauge '+m.bandClass+'" style="height:14px;margin-top:6px"><div class="pulse-gauge-fill" style="width:'+Math.max(3,Math.min(100,m.gaugePct))+'%"></div></div><div class="pulse-band '+m.bandClass+'" style="margin-top:8px">'+m.bandLabel+'</div>';}
      else if(m.spark&&m.spark.length){visual='<div style="height:130px;margin-top:8px"><canvas id="mxChart"></canvas></div>';}
      var ai=HAVE_CLAUDE
        ? '<div class="mx-ai"><div class="mx-ai-head">'+CLAUDE_BADGE+' <span>AI Enhanced</span></div><div id="mxAIBody" class="mx-ai-body"><button class="btn btn-primary btn-sm" onclick="explainMetric(\''+key+'\')"><i class="fa-solid fa-wand-magic-sparkles"></i> Explain this metric with Claude</button></div></div>'
        : '<div class="mx-ai-off"><i class="fa-solid fa-wand-magic-sparkles"></i> Connect your <b>Church Anthropic Claude</b> account in <a href="?page=settings">Settings</a> for an AI reading of this metric.</div>';
      document.getElementById('mxBody').innerHTML=
        '<div class="mx-val" style="color:'+acc+'">'+m.value+' '+chip+'</div>'
        +'<div class="mx-sub">'+m.sub+'</div>'+visual
        +'<div class="mx-note"><i class="fa-solid fa-circle-info"></i> '+m.note+'</div>'
        +(det.what?'<div class="mx-det"><h4>What it is</h4><p>'+det.what+'</p></div>':'')
        +(det.why?'<div class="mx-det"><h4>Why it matters</h4><p>'+det.why+'</p></div>':'')
        +(det.act?'<div class="mx-det"><h4>What to do</h4><p>'+det.act+'</p></div>':'')
        +ai;
      showModal('mxModal');
      if(m.kind!=='gauge'&&m.spark&&m.spark.length){var cv=document.getElementById('mxChart');if(cv){new Chart(cv,{type:'line',data:{labels:m.spark.map(function(_,k){return k;}),datasets:[{data:m.spark,borderColor:acc,backgroundColor:soft,fill:true,tension:.4,borderWidth:2.5,pointRadius:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}}}});}}
    }
    function explainMetric(key){var b=document.getElementById('mxAIBody');if(!b)return;b.innerHTML='<div class="typing"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';var fd=new FormData();fd.append('focus',key);fetch('?action=ai_pulse_insight',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(d){b.innerHTML=d.error?('⚠ '+acEsc(d.error)):acMD(d.text);}).catch(function(){b.textContent='⚠ Request failed.';});}
    var ACCENT={blue:'#2E5BFF',green:'#10B981',violet:'#6f3de8',teal:'#0ea5a4',amber:'#F59E0B',navy:'#0f1f4e'};
    var SOFT={blue:'rgba(46,91,255,.13)',green:'rgba(16,185,129,.14)',violet:'rgba(111,61,232,.14)',teal:'rgba(14,165,164,.14)',amber:'rgba(245,158,11,.16)',navy:'rgba(15,31,78,.12)'};
    var COMFORT=['#5B8DEF','#34D399','#A78BFA','#FBBF24','#22D3EE','#F472B6','#94A3B8','#60A5FA'];
    function fmtSpark(arr){return (arr&&arr.length)?arr:[0,0];}
    function deltaChipRaw(d,goodUp){
      d=d||0; var good=(d>0)===goodUp, flat=Math.abs(d)<0.5;
      var cls=flat?'flat':(good?'up':'down'), arrow=flat?'→':(d>0?'▲':'▼');
      return '<span class="pulse-delta '+cls+'">'+arrow+' '+Math.abs(d)+'%</span>';
    }
    function deltaChip(m){ return m.kind==='spark' ? deltaChipRaw(m.delta,m.goodUp) : ''; }
    function fcCardHTML(f){
      var acc=ACCENT[f.accent]||'#2E5BFF';
      var chip = (f.delta!=null && f.delta!==undefined) ? deltaChipRaw(f.delta,f.goodUp) : '';
      return '<div class="pulse-card pulse-clickable" style="--acc:'+acc+'" onclick="openMetric(\''+f.key+'\',\'forecast\')" tabindex="0" role="button" onkeydown="if(event.key===\'Enter\'){openMetric(\''+f.key+'\',\'forecast\')}"><i class="fa-solid fa-up-right-and-down-left-from-center pulse-expand"></i>'
        +'<div class="pulse-top"><span class="pulse-ic" style="background:'+(SOFT[f.accent]||SOFT.blue)+';color:'+acc+'"><i class="fa-solid '+f.icon+'"></i></span>'
        +'<span class="pulse-label">'+f.label+'</span>'+chip+'</div>'
        +'<div class="pulse-val">'+f.value+'</div>'
        +'<div class="pulse-sub">'+f.sub+'</div>'
        +'<div class="pulse-note" style="margin-top:auto"><i class="fa-solid fa-circle-info"></i> '+f.note+(f.deltaLabel?' <span class="pulse-dl">'+f.deltaLabel+'</span>':'')+'</div>'
        +'</div>';
    }
    function cardHTML(m,i){
      var acc=ACCENT[m.accent]||'#2E5BFF';
      var visual = m.kind==='gauge'
        ? '<div class="pulse-gauge '+m.bandClass+'"><div class="pulse-gauge-fill" style="width:'+Math.max(3,Math.min(100,m.gaugePct))+'%"></div></div>'
          +'<div class="pulse-band '+m.bandClass+'">'+m.bandLabel+'</div>'
        : '<div class="pulse-spark"><canvas id="spark'+i+'" height="48"></canvas></div>';
      return '<div class="pulse-card pulse-clickable" style="--acc:'+acc+'" onclick="openMetric(\''+m.key+'\',\'metric\')" tabindex="0" role="button" onkeydown="if(event.key===\'Enter\'){openMetric(\''+m.key+'\',\'metric\')}"><i class="fa-solid fa-up-right-and-down-left-from-center pulse-expand"></i>'
        +'<div class="pulse-top"><span class="pulse-ic" style="background:'+(SOFT[m.accent]||SOFT.blue)+';color:'+acc+'"><i class="fa-solid '+m.icon+'"></i></span>'
        +'<span class="pulse-label">'+m.label+'</span>'+deltaChip(m)+'</div>'
        +'<div class="pulse-val">'+m.value+'</div>'
        +'<div class="pulse-sub">'+m.sub+'</div>'
        +visual
        +'<div class="pulse-note"><i class="fa-solid fa-circle-info"></i> '+m.note+(m.kind==='spark'?' <span class="pulse-dl">'+m.deltaLabel+'</span>':'')+'</div>'
        +'</div>';
    }
    function renderPulse(d){
      PULSE=d;
      var g=document.getElementById('pulseGrid');g.innerHTML=d.metrics.map(cardHTML).join('');
      d.metrics.forEach(function(m,i){ if(m.kind!=='spark')return; var cv=document.getElementById('spark'+i); if(!cv)return;
        var acc=ACCENT[m.accent]||'#2E5BFF';
        new Chart(cv,{type:'line',data:{labels:m.spark.map(function(_,k){return k;}),datasets:[{data:fmtSpark(m.spark),borderColor:acc,backgroundColor:SOFT[m.accent]||'rgba(46,91,255,.13)',fill:true,tension:.42,borderWidth:2,pointRadius:0}]},
          options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}},elements:{line:{capBezierPoints:true}}}});
      });
      var fg=document.getElementById('forecastGrid');
      if(fg&&d.forecast){fg.innerHTML=d.forecast.map(fcCardHTML).join('');}
    }
    fetch('?action=pulse_data').then(function(r){return r.json();}).then(renderPulse).catch(function(){document.getElementById('pulseGrid').innerHTML='<div class="empty" style="grid-column:1/-1"><i class="fa-solid fa-triangle-exclamation"></i><div>Could not load analytics. Please refresh.</div></div>';});

    function explainPulse(){var box=document.getElementById('pulseAI'),body=document.getElementById('pulseAIBody');
      box.style.display='block';box.scrollIntoView({behavior:'smooth',block:'nearest'});
      body.innerHTML='<div class="typing"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
      fetch('?action=ai_pulse_insight',{method:'POST'}).then(function(r){return r.json();}).then(function(d){body.innerHTML=d.error?('⚠ '+acEsc(d.error)):acMD(d.text);}).catch(function(){body.textContent='⚠ Request failed.';});}

    function exportPulseXlsx(){ if(!PULSE){alert('Still loading…');return;}
      var wb=XLSX.utils.book_new();
      var head=[[PULSE.church+' — Membership Vital Signs'],['Generated '+PULSE.generated],[],['Metric','Value','Change','Reading']];
      var rows=PULSE.metrics.map(function(m){return [m.label,m.value,(m.kind==='spark'?((m.delta>0?'+':'')+m.delta+'% '+m.deltaLabel):m.bandLabel),m.note.replace(/<[^>]+>/g,'')];});
      var ws=XLSX.utils.aoa_to_sheet(head.concat(rows));
      ws['!cols']=[{wch:26},{wch:16},{wch:34},{wch:60}];
      ws['!merges']=[{s:{r:0,c:0},e:{r:0,c:3}},{s:{r:1,c:0},e:{r:1,c:3}}];
      XLSX.utils.book_append_sheet(wb,ws,'Vital Signs');
      var tr=[['Month','Giving ($)','Distinct givers','New members','Total membership','Weekly attendance']];
      for(var i=0;i<PULSE.months.length;i++){tr.push([PULSE.months[i],PULSE.series.giving[i]||0,PULSE.series.givers[i]||0,PULSE.series.joins[i]||0,PULSE.series.membership[i]||0,PULSE.series.attendance[i]||'']);}
      var ws2=XLSX.utils.aoa_to_sheet(tr);ws2['!cols']=[{wch:12},{wch:14},{wch:16},{wch:14},{wch:18},{wch:18}];
      XLSX.utils.book_append_sheet(wb,ws2,'Monthly Trends');
      var fr=[['Fund','Giving this year ($)']].concat(PULSE.fund_breakdown.map(function(f){return [f.name,Math.round(f.total)];}));
      var ws3=XLSX.utils.aoa_to_sheet(fr);ws3['!cols']=[{wch:30},{wch:20}];
      XLSX.utils.book_append_sheet(wb,ws3,'Giving by Fund');
      XLSX.writeFile(wb,(PULSE.church.replace(/[^a-z0-9]+/gi,'_'))+'_Analytics.xlsx',{compression:true});
    }
    function exportPulsePdf(){ if(!PULSE){alert('Still loading…');return;}
      var jsPDF=window.jspdf.jsPDF; var doc=new jsPDF('p','mm','a4'); var W=210, M=14;
      doc.setFillColor(15,31,78);doc.rect(0,0,W,34,'F');
      doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text(PULSE.church,M,16);
      doc.setFont('helvetica','normal');doc.setFontSize(11);doc.text('Membership Vital Signs',M,24);
      doc.setFontSize(9);doc.setTextColor(200,210,235);doc.text('Generated '+PULSE.generated,M,30);
      var cols=2, cw=(W-M*2-6)/cols, ch=33, x0=M, y0=42, gap=6;
      var RGB={blue:[46,91,255],green:[16,185,129],violet:[111,61,232],teal:[14,165,164],amber:[245,158,11],navy:[15,31,78]};
      PULSE.metrics.forEach(function(m,i){
        var c=i%cols, r=Math.floor(i/cols); var x=x0+c*(cw+gap), y=y0+r*(ch+gap); var col=RGB[m.accent]||[46,91,255];
        doc.setDrawColor(228,232,240);doc.setFillColor(255,255,255);doc.roundedRect(x,y,cw,ch,2.5,2.5,'FD');
        doc.setFillColor(col[0],col[1],col[2]);doc.roundedRect(x,y,2.2,ch,1,1,'F');
        doc.setTextColor(110,120,140);doc.setFont('helvetica','bold');doc.setFontSize(8.5);doc.text(m.label.toUpperCase(),x+6,y+7);
        doc.setTextColor(20,28,48);doc.setFont('helvetica','bold');doc.setFontSize(17);doc.text(String(m.value),x+6,y+17);
        var chg=(m.kind==='spark')?((m.delta>0?'+':'')+m.delta+'%  '+m.deltaLabel):m.bandLabel;
        doc.setTextColor(col[0],col[1],col[2]);doc.setFont('helvetica','bold');doc.setFontSize(8.5);doc.text(doc.splitTextToSize(chg,cw-12),x+6,y+23);
        doc.setTextColor(90,100,120);doc.setFont('helvetica','normal');doc.setFontSize(8);
        doc.text(doc.splitTextToSize(m.note.replace(/<[^>]+>/g,''),cw-12),x+6,y+28);
      });
      var fy=y0+4*(ch+gap)+4;
      doc.setDrawColor(228,232,240);doc.line(M,fy,W-M,fy);
      doc.setTextColor(140,150,170);doc.setFont('helvetica','normal');doc.setFontSize(7.5);
      doc.text('Free Church ChMS · deterministic analytics — the same data always produces the same numbers. Soli Deo Gloria.',M,fy+5);
      doc.save((PULSE.church.replace(/[^a-z0-9]+/gi,'_'))+'_Vital_Signs.pdf');
    }
    </script>
    <?php endPage();
}




function renderMembers(): void {
    $db = getDB();
    $q = trim($_GET['q'] ?? ''); $status = $_GET['status'] ?? '';
    $where = []; $args = [];
    if ($q) { $where[] = "(first_name LIKE ? OR last_name LIKE ? OR email LIKE ?)"; $args[]="%$q%"; $args[]="%$q%"; $args[]="%$q%"; }
    if ($status) { $where[] = "status=?"; $args[]=$status; }
    $sql = "SELECT * FROM members" . ($where?(' WHERE '.implode(' AND ',$where)):'') . " ORDER BY last_name,first_name LIMIT 300";
    $st = $db->prepare($sql); $st->execute($args); $members = $st->fetchAll();
    $edit = null; if (!empty($_GET['edit'])) { $e=$db->prepare('SELECT * FROM members WHERE id=?'); $e->execute([(int)$_GET['edit']]); $edit=$e->fetch(); }
    startPage('Members', 'members');
    ?>
    <div class="page-head"><div><div class="page-title">Members</div><div class="page-sub"><?=count($members)?> shown</div></div>
      <button class="btn btn-primary" onclick="openMember()"><i class="fa-solid fa-user-plus"></i> Add member</button></div>
    <div class="toolbar">
      <form method="GET" style="display:flex;gap:var(--sp-2);flex:1;flex-wrap:wrap"><input type="hidden" name="page" value="members">
        <div class="search-wrap" style="flex:1;min-width:200px"><i class="fa-solid fa-magnifying-glass search-icon"></i><input class="input" name="q" value="<?=h($q)?>" placeholder="Search name or email…"></div>
        <select class="select" name="status" style="max-width:170px" onchange="this.form.submit()">
          <option value="">All statuses</option>
          <?php foreach(['active','visitor','inactive'] as $s): ?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach; ?>
        </select>
        <button class="btn btn-outline">Search</button>
      </form>
    </div>
    <div class="card"><div class="card-body-0"><div class="table-wrap"><table class="data-table">
      <thead><tr><th>Name</th><th>Contact</th><th>Status</th><th>Engagement</th><th>Last seen</th><th></th></tr></thead><tbody>
      <?php if(!$members): ?><tr><td colspan="6"><div class="empty"><i class="fa-solid fa-users"></i><div>No members yet. Add one or import from your ChMS.</div></div></td></tr><?php endif; ?>
      <?php foreach($members as $m): $sc=(int)$m['engagement_score']; $cl=$sc>=70?'high':($sc>=45?'mid':'low'); $t=$m['engagement_tier']?:'healthy'; ?>
      <tr>
        <td><div style="display:flex;align-items:center;gap:var(--sp-3)"><div class="user-av" style="width:34px;height:34px;font-size:var(--text-xs);background-size:cover;background-position:center;<?=$m['photo_url']?"background-image:url('".h($m['photo_url'])."')":''?>"><?=$m['photo_url']?'':h(strtoupper(($m['first_name'][0]??'').($m['last_name'][0]??'')))?></div><div><strong><?=h($m['first_name'].' '.$m['last_name'])?></strong><?php if($m['source']&&$m['source']!=='manual'): ?> <span class="badge badge-inactive"><?=h($m['source'])?></span><?php endif; ?></div></div></td>
        <td style="color:var(--gray-500)"><?=h($m['email']?:'—')?><?php if($m['phone']): ?><br><span style="font-size:var(--text-xs)"><?=h($m['phone'])?></span><?php endif; ?></td>
        <td><span class="badge badge-<?=h($m['status'])?>"><?=h($m['status'])?></span></td>
        <td><div class="eng-wrap"><div class="eng-bar"><div class="eng-fill <?=$cl?>" data-w="<?=$sc?>"></div></div><span class="eng-score"><?=$sc?></span></div></td>
        <td style="color:var(--gray-400)"><?=h($m['last_attended']?:'—')?></td>
        <td style="text-align:right;white-space:nowrap"><a class="btn btn-ghost btn-xs" target="_blank" title="Print giving statement" href="?page=print&type=giving_statement&id=<?=$m['id']?>"><i class="fa-solid fa-file-invoice-dollar"></i></a><a class="btn btn-ghost btn-xs" href="?page=members&edit=<?=$m['id']?>"><i class="fa-solid fa-pen"></i></a>
          <form method="POST" action="?action=delete_member" style="display:inline" onsubmit="return confirm('Delete this member?')"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-ghost btn-xs" style="color:var(--red)"><i class="fa-solid fa-trash"></i></button></form></td>
      </tr>
      <?php endforeach; ?>
      </tbody></table></div></div></div>

    <div class="modal-bg" id="memberModal"><div class="modal-card"><div class="modal-hd"><div class="modal-title"><?=$edit?'Edit member':'Add member'?></div><button class="modal-close" onclick="hideModal('memberModal')">&times;</button></div>
      <?php if($edit): ?>
      <div class="modal-bd" style="padding-bottom:0"><form method="POST" action="?action=upload_member_photo" enctype="multipart/form-data" id="photoForm"><input type="hidden" name="id" value="<?=$edit['id']?>">
        <div style="display:flex;gap:var(--sp-4);align-items:center">
          <div id="photoPrev" style="width:72px;height:72px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg,var(--blue-600),var(--violet));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:var(--text-lg);background-size:cover;background-position:center;<?=$edit['photo_url']?"background-image:url('".h($edit['photo_url'])."')":''?>"><?=$edit['photo_url']?'':h(strtoupper(($edit['first_name'][0]??'').($edit['last_name'][0]??'')))?></div>
          <div id="photoDrop" style="flex:1;border:2px dashed var(--gray-200);border-radius:var(--radius);padding:var(--sp-3);text-align:center;font-size:var(--text-xs);color:var(--gray-500);cursor:pointer;transition:all var(--t-fast)"><i class="fa-solid fa-image"></i> Drag a photo here or click to upload<input type="file" name="photo" accept="image/*" hidden id="photoInput"></div>
        </div></form></div>
      <?php endif; ?>
      <form method="POST" action="?action=save_member"><div class="modal-bd"><input type="hidden" name="id" value="<?=$edit['id']??''?>">
        <div class="form-grid">
          <div class="field"><label>First name</label><input class="input" name="first_name" value="<?=h($edit['first_name']??'')?>" required></div>
          <div class="field"><label>Last name</label><input class="input" name="last_name" value="<?=h($edit['last_name']??'')?>" required></div>
          <div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=h($edit['email']??'')?>"></div>
          <div class="field"><label>Phone</label><input class="input" name="phone" value="<?=h($edit['phone']??'')?>"></div>
          <div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['active','visitor','inactive'] as $s): ?><option value="<?=$s?>" <?=($edit['status']??'active')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach; ?></select></div>
          <div class="field"><label>Membership date</label><input class="input" type="date" name="membership_date" value="<?=h($edit['membership_date']??'')?>"></div>
          <div class="field"><label>Birthdate</label><input class="input" type="date" name="birthdate" value="<?=h($edit['birthdate']??'')?>"></div>
          <div class="field"><label>Gender</label><select class="select" name="gender"><option value="">—</option><?php foreach(['male','female'] as $g): ?><option value="<?=$g?>" <?=($edit['gender']??'')===$g?'selected':''?>><?=ucfirst($g)?></option><?php endforeach; ?></select></div>
          <div class="field span2"><label>Address</label><input class="input" name="address" value="<?=h($edit['address']??'')?>"></div>
          <div class="field"><label>City</label><input class="input" name="city" value="<?=h($edit['city']??'')?>"></div>
          <div class="field"><label>State / ZIP</label><div style="display:flex;gap:8px"><input class="input" name="state" value="<?=h($edit['state']??'')?>" placeholder="State"><input class="input" name="zip" value="<?=h($edit['zip']??'')?>" placeholder="ZIP"></div></div>
          <div class="field span2"><label>Notes</label><textarea class="input" name="notes"><?=h($edit['notes']??'')?></textarea></div>
        </div></div>
        <div class="modal-ft"><a class="btn btn-ghost" href="?page=members">Cancel</a><button class="btn btn-primary">Save member</button></div>
      </form></div></div>
    <script>
    function openMember(){location.href='?page=members&edit=new'}
    (function(){const d=document.getElementById('photoDrop'),i=document.getElementById('photoInput'),f=document.getElementById('photoForm'),p=document.getElementById('photoPrev');
      if(!d)return; d.onclick=()=>i.click();
      i.onchange=()=>{if(i.files[0]){const r=new FileReader();r.onload=e=>{p.style.backgroundImage=`url(${e.target.result})`;p.textContent='';};r.readAsDataURL(i.files[0]);f.submit();}};
      ['dragover','dragenter'].forEach(ev=>d.addEventListener(ev,e=>{e.preventDefault();d.style.borderColor='var(--blue-500)';d.style.background='var(--blue-50)';}));
      ['dragleave','drop'].forEach(ev=>d.addEventListener(ev,e=>{e.preventDefault();d.style.borderColor='var(--gray-200)';d.style.background='';}));
      d.addEventListener('drop',e=>{if(e.dataTransfer.files[0]){i.files=e.dataTransfer.files;i.dispatchEvent(new Event('change'));}});
    })();
    <?php if($edit||($_GET['edit']??'')==='new'): ?>showModal('memberModal');<?php endif; ?></script>
    <?php endPage();
}




