function renderAttendance(): void {
    $db = getDB();
    $services = $db->query("SELECT s.*, (SELECT COUNT(*) FROM attendance a WHERE a.service_id=s.id) recorded FROM services s ORDER BY s.date DESC LIMIT 30")->fetchAll();
    $checkSvc = null; $members = [];
    if (!empty($_GET['service'])) {
        $cs = $db->prepare('SELECT * FROM services WHERE id=?'); $cs->execute([(int)$_GET['service']]); $checkSvc=$cs->fetch();
        $members = $db->query("SELECT id,first_name,last_name FROM members WHERE status IN('active','visitor') ORDER BY last_name")->fetchAll();
        $ps = $db->prepare('SELECT member_id FROM attendance WHERE service_id=?'); $ps->execute([(int)$_GET['service']]); $present = $ps->fetchAll(PDO::FETCH_COLUMN);
    }
    startPage('Attendance', 'attendance');
    if ($checkSvc): ?>
      <div class="page-head"><div><div class="page-title">Check-in: <?=h($checkSvc['name'])?></div><div class="page-sub"><?=h($checkSvc['date'])?></div></div><a class="btn btn-ghost" href="?page=attendance">← Back</a></div>
      <form method="POST" action="?action=record_attendance"><input type="hidden" name="service_id" value="<?=$checkSvc['id']?>">
      <div class="card"><div class="card-body"><div class="grid grid-3">
        <?php foreach($members as $m): $on=in_array($m['id'],$present??[]); ?>
          <label style="display:flex;gap:10px;align-items:center;padding:var(--sp-2) var(--sp-3);border:1.5px solid var(--gray-200);border-radius:var(--radius-sm);cursor:pointer"><input type="checkbox" name="member_ids[]" value="<?=$m['id']?>" <?=$on?'checked':''?> style="width:18px;height:18px"> <?=h($m['first_name'].' '.$m['last_name'])?></label>
        <?php endforeach; ?>
      </div></div></div>
      <div style="margin-top:var(--sp-4)"><button class="btn btn-primary btn-lg"><i class="fa-solid fa-check"></i> Save attendance</button></div></form>
    <?php else: ?>
      <div class="page-head"><div><div class="page-title">Attendance</div><div class="page-sub">Services &amp; check-in</div></div><button class="btn btn-primary" onclick="newSvc()"><i class="fa-solid fa-plus"></i> New service</button></div>
      <div class="card"><div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Date</th><th>Type</th><th>Head count</th><th>Checked in</th><th></th></tr></thead><tbody>
      <?php if(!$services): ?><tr><td colspan="6"><div class="empty"><i class="fa-solid fa-clipboard-check"></i><div>No services yet.</div></div></td></tr><?php endif; ?>
      <?php foreach($services as $s): ?><tr><td><strong><?=h($s['name'])?></strong></td><td><?=h($s['date'])?></td><td style="text-transform:capitalize"><?=h($s['type'])?></td><td><?=$s['head_count']?></td><td><?=$s['recorded']?></td><td style="text-align:right;white-space:nowrap">
        <button class="icon-btn" title="Edit service" onclick='editSvc(<?=htmlspecialchars(json_encode($s),ENT_QUOTES)?>)'><i class="fa-solid fa-pen"></i></button>
        <form method="POST" action="?action=delete_service" style="display:inline" onsubmit="return confirm('Delete this service and its check-ins? This cannot be undone.')"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="icon-btn" title="Delete service"><i class="fa-solid fa-trash"></i></button></form>
        <a class="btn btn-outline btn-sm" href="?page=attendance&amp;service=<?=$s['id']?>">Check in</a></td></tr><?php endforeach; ?>
      </tbody></table></div></div></div>
      <div class="modal-bg" id="svcModal"><div class="modal-card sm"><div class="modal-hd"><div class="modal-title" id="svcModalTitle">New service</div><button class="modal-close" onclick="hideModal('svcModal')">&times;</button></div>
        <form method="POST" action="?action=save_service"><input type="hidden" name="id" id="svc_id"><div class="modal-bd"><div class="field" style="margin-bottom:var(--sp-4)"><label>Name</label><input class="input" id="svc_name" name="name" placeholder="Sunday Service" required></div>
          <div class="form-grid"><div class="field"><label>Date</label><input class="input" id="svc_date" type="date" name="date" value="<?=date('Y-m-d')?>" required></div>
          <div class="field"><label>Type</label><select class="select" id="svc_type" name="type"><?php foreach(['sunday','midweek','special','online'] as $t): ?><option value="<?=$t?>"><?=ucfirst($t)?></option><?php endforeach; ?></select></div>
          <div class="field"><label>Head count</label><input class="input" id="svc_head" type="number" min="0" name="head_count" value="0"></div>
          <div class="field"><label>Notes</label><input class="input" id="svc_notes" name="notes"></div></div></div>
          <div class="modal-ft"><button type="button" class="btn btn-ghost" onclick="hideModal('svcModal')">Cancel</button><button class="btn btn-primary" id="svcSaveBtn">Create</button></div></form></div></div>
      <script>
      function newSvc(){document.getElementById('svcModalTitle').textContent='New service';document.getElementById('svc_id').value='';document.getElementById('svc_name').value='';document.getElementById('svc_date').value='<?=date('Y-m-d')?>';document.getElementById('svc_type').value='sunday';document.getElementById('svc_head').value='0';document.getElementById('svc_notes').value='';document.getElementById('svcSaveBtn').textContent='Create';showModal('svcModal');}
      function editSvc(s){document.getElementById('svcModalTitle').textContent='Edit service';document.getElementById('svc_id').value=s.id;document.getElementById('svc_name').value=s.name||'';document.getElementById('svc_date').value=s.date||'';document.getElementById('svc_type').value=s.type||'sunday';document.getElementById('svc_head').value=(s.head_count!=null?s.head_count:0);document.getElementById('svc_notes').value=s.notes||'';document.getElementById('svcSaveBtn').textContent='Save changes';showModal('svcModal');}
      </script>
    <?php endif; endPage();
}




