function renderPastoral(): void {
    $db = getDB();
    $atRisk = $db->query("SELECT * FROM members WHERE engagement_tier IN ('at_risk','critical') AND status='active' ORDER BY engagement_score ASC LIMIT 50")->fetchAll();
    $prayers = $db->query("SELECT p.*, m.first_name, m.last_name FROM prayer_requests p LEFT JOIN members m ON m.id=p.member_id WHERE p.status='active' ORDER BY p.created_at DESC LIMIT 20")->fetchAll();
    $notes = $db->query("SELECT n.*, m.first_name, m.last_name FROM pastoral_notes n JOIN members m ON m.id=n.member_id ORDER BY n.created_at DESC LIMIT 15")->fetchAll();
    $members = $db->query("SELECT id,first_name,last_name FROM members ORDER BY last_name")->fetchAll();
    startPage('Pastoral Care', 'pastoral');
    ?>
    <?php $muted = getSetting('pastoral_alerts_muted') === '1'; ?>
    <div class="page-head"><div><div class="page-title">Pastoral Care</div><div class="page-sub">Who needs a shepherd's attention this week</div></div>
      <div style="display:flex;gap:var(--sp-2);flex-wrap:wrap">
        <button class="btn btn-outline" id="muteBtn" onclick="togglePastoralMute()" title="Mute or unmute the red pastoral alert badge in the sidebar HUD"><i class="fa-solid <?=$muted?'fa-bell-slash':'fa-bell'?>"></i> <?=$muted?'Alerts muted — unmute':'Mute alerts'?></button>
        <button class="btn btn-outline" onclick="showModal('prayerModal')"><i class="fa-solid fa-hands-praying"></i> Prayer request</button>
        <button class="btn btn-primary" onclick="showModal('noteModal')"><i class="fa-solid fa-pen"></i> Add note</button>
      </div></div>
    <script>
    window.AC_ATRISK = <?=count($atRisk)?>;
    function togglePastoralMute(){
      fetch('?action=mute_pastoral_alerts',{method:'POST'}).then(function(r){return r.json();}).then(function(d){
        if(!d||!d.ok) return;
        var btn=document.getElementById('muteBtn');
        if(btn) btn.innerHTML = d.muted ? '<i class="fa-solid fa-bell-slash"></i> Alerts muted — unmute' : '<i class="fa-solid fa-bell"></i> Mute alerts';
        var b=document.getElementById('pastoralHudBadge');
        if(d.muted){ if(b) b.style.display='none'; }
        else { if(b){ b.style.display=''; } else if(window.AC_ATRISK>0){ location.reload(); } }
      }).catch(function(){});
    }
    </script>
    <div class="grid grid-2">
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-heart-pulse" style="color:var(--red)"></i> At-risk &amp; critical</div></div>
        <div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Tier</th><th>Score</th><th>Contact</th></tr></thead><tbody>
        <?php if(!$atRisk): ?><tr><td colspan="4"><div class="empty" style="padding:var(--sp-6)"><i class="fa-solid fa-face-smile"></i><div>No one at risk. 🎉</div></div></td></tr><?php endif; ?>
        <?php foreach($atRisk as $m): ?><tr><td><strong><?=h($m['first_name'].' '.$m['last_name'])?></strong></td><td><span class="badge badge-<?=h($m['engagement_tier']?:'at_risk')?>"><?=h(str_replace('_',' ',$m['engagement_tier']?:'at risk'))?></span></td><td><?=$m['engagement_score']?></td><td style="color:var(--gray-500);font-size:var(--text-xs)"><?=h($m['email']?:$m['phone']?:'—')?></td></tr><?php endforeach; ?>
        </tbody></table></div></div></div>
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-hands-praying" style="color:var(--violet)"></i> Prayer requests</div></div>
        <div class="card-body"><?php if(!$prayers): ?><div class="empty" style="padding:var(--sp-6)"><i class="fa-solid fa-dove"></i><div>No active prayer requests.</div></div><?php endif; ?>
        <?php foreach($prayers as $p): ?><div class="log-item"><div class="log-dot" style="background:var(--violet)"><i class="fa-solid fa-hands-praying"></i></div><div><strong><?=h($p['subject'])?></strong><?php if($p['private']): ?> <span class="badge badge-inactive">private</span><?php endif; ?><div style="font-size:var(--text-sm);color:var(--gray-600)"><?=h($p['body'])?></div><div style="font-size:var(--text-2xs);color:var(--gray-400)"><?=h(trim(($p['first_name']??'').' '.($p['last_name']??'')) ?: 'General')?> · <?=h($p['created_at'])?></div></div></div><?php endforeach; ?>
        </div></div>
    </div>
    <div class="card" style="margin-top:var(--sp-4)"><div class="card-head"><div class="card-title"><i class="fa-solid fa-note-sticky" style="color:var(--blue-600)"></i> Recent pastoral notes</div></div>
      <div class="card-body"><?php if(!$notes): ?><div class="empty" style="padding:var(--sp-6)"><i class="fa-solid fa-note-sticky"></i><div>No notes yet.</div></div><?php endif; ?>
      <?php foreach($notes as $n): ?><div class="log-item"><div class="log-dot" style="background:var(--blue-600)"><i class="fa-solid fa-user"></i></div><div><strong><?=h($n['first_name'].' '.$n['last_name'])?></strong> <span class="badge badge-visitor"><?=h($n['category'])?></span><div style="font-size:var(--text-sm);color:var(--gray-600)"><?=h($n['note'])?></div><div style="font-size:var(--text-2xs);color:var(--gray-400)"><?=h($n['created_at'])?></div></div></div><?php endforeach; ?>
      </div></div>

    <div class="modal-bg" id="noteModal"><div class="modal-card sm"><div class="modal-hd"><div class="modal-title">Pastoral note</div><button class="modal-close" onclick="hideModal('noteModal')">&times;</button></div>
      <form method="POST" action="?action=add_pastoral_note"><div class="modal-bd">
        <div class="field" style="margin-bottom:var(--sp-4)"><label>Member</label><select class="select" name="member_id" required><option value="">Select…</option><?php foreach($members as $m): ?><option value="<?=$m['id']?>" <?=($_GET['member']??'')==$m['id']?'selected':''?>><?=h($m['first_name'].' '.$m['last_name'])?></option><?php endforeach; ?></select></div>
