function renderGiving(): void {
    $db = getDB();
    $ytd = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y',date)=strftime('%Y','now')")->fetchColumn();
    $mtd = (float)$db->query("SELECT COALESCE(SUM(amount),0) FROM giving WHERE strftime('%Y-%m',date)=strftime('%Y-%m','now')")->fetchColumn();
    $count = (int)$db->query("SELECT COUNT(*) FROM giving WHERE strftime('%Y',date)=strftime('%Y','now')")->fetchColumn();
    $avg = $count ? $ytd/$count : 0;
    $gifts = $db->query("SELECT g.*, m.first_name, m.last_name, f.name fund FROM giving g LEFT JOIN members m ON m.id=g.member_id LEFT JOIN funds f ON f.id=g.fund_id ORDER BY g.date DESC, g.id DESC LIMIT 60")->fetchAll();
    $funds = $db->query("SELECT * FROM funds WHERE active=1 ORDER BY name")->fetchAll();
    $members = $db->query("SELECT id,first_name,last_name FROM members ORDER BY last_name")->fetchAll();
    startPage('Giving', 'giving');
    ?>
    <div class="page-head"><div><div class="page-title">Giving</div><div class="page-sub">Record gifts &amp; manage funds</div></div>
      <div style="display:flex;gap:var(--sp-2)"><button class="btn btn-outline" onclick="showModal('fundModal')"><i class="fa-solid fa-layer-group"></i> New fund</button><button class="btn btn-primary" onclick="showModal('giveModal')"><i class="fa-solid fa-plus"></i> Record gift</button></div></div>
    <div class="stat-grid">
      <div class="stat-card"><div class="stat-icon green"><i class="fa-solid fa-dollar-sign"></i></div><div><div class="stat-value" data-countup="<?=round($ytd)?>" data-prefix="$"><?=fmtK($ytd)?></div><div class="stat-label">YTD giving</div></div></div>
      <div class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-calendar-day"></i></div><div><div class="stat-value" data-countup="<?=round($mtd)?>" data-prefix="$"><?=fmtK($mtd)?></div><div class="stat-label">This month</div></div></div>
      <div class="stat-card"><div class="stat-icon purple"><i class="fa-solid fa-gift"></i></div><div><div class="stat-value" data-countup="<?=$count?>"><?=$count?></div><div class="stat-label">Gifts YTD</div></div></div>
      <div class="stat-card"><div class="stat-icon navy"><i class="fa-solid fa-chart-simple"></i></div><div><div class="stat-value" data-countup="<?=round($avg)?>" data-prefix="$"><?=fmt($avg)?></div><div class="stat-label">Average gift</div></div></div>
    </div>
    <div class="card"><div class="card-head"><div class="card-title">Recent gifts</div></div><div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Giver</th><th>Amount</th><th>Fund</th><th>Method</th><th>Date</th></tr></thead><tbody>
    <?php if(!$gifts): ?><tr><td colspan="5"><div class="empty"><i class="fa-solid fa-gift"></i><div>No gifts recorded yet.</div></div></td></tr><?php endif; ?>
    <?php foreach($gifts as $g): ?><tr><td><?=h(trim(($g['first_name']??'').' '.($g['last_name']??'')) ?: 'Anonymous')?></td><td><strong style="color:var(--green-dark)"><?=fmt((float)$g['amount'])?></strong></td><td><?=h($g['fund']?:'—')?></td><td style="text-transform:capitalize"><?=h($g['method'])?></td><td style="color:var(--gray-400)"><?=h($g['date'])?></td></tr><?php endforeach; ?>
    </tbody></table></div></div></div>
    <div class="modal-bg" id="giveModal"><div class="modal-card"><div class="modal-hd"><div class="modal-title">Record gift</div><button class="modal-close" onclick="hideModal('giveModal')">&times;</button></div>
      <form method="POST" action="?action=save_giving"><div class="modal-bd"><div class="form-grid">
        <div class="field"><label>Giver</label><select class="select" name="member_id"><option value="0">Anonymous</option><?php foreach($members as $m): ?><option value="<?=$m['id']?>"><?=h($m['first_name'].' '.$m['last_name'])?></option><?php endforeach; ?></select></div>
        <div class="field"><label>Fund</label><select class="select" name="fund_id"><?php foreach($funds as $f): ?><option value="<?=$f['id']?>"><?=h($f['name'])?></option><?php endforeach; ?></select></div>
        <div class="field"><label>Amount</label><input class="input" type="number" step="0.01" name="amount" required></div>
        <div class="field"><label>Date</label><input class="input" type="date" name="date" value="<?=date('Y-m-d')?>" required></div>
        <div class="field"><label>Method</label><select class="select" name="method"><?php foreach(['check','cash','card','online','ach'] as $m): ?><option value="<?=$m?>"><?=ucfirst($m)?></option><?php endforeach; ?></select></div>
        <div class="field"><label>Check #</label><input class="input" name="check_number"></div>
        <div class="field span2"><label>Notes</label><input class="input" name="notes"></div>
      </div></div><div class="modal-ft"><button type="button" class="btn btn-ghost" onclick="hideModal('giveModal')">Cancel</button><button class="btn btn-primary">Record</button></div></form></div></div>
