    <?php endPage();
}




function renderDonors(): void {
    $seg = donorSegments();
    $defs = [
        ['first_time','First-time givers','fa-seedling','green','Given once — perfect for a thank-you + next-step.'],
        ['consistent','Consistent givers','fa-repeat','blue','3+ gifts in the last 90 days.'],
        ['lapsing','Lapsing givers','fa-arrow-trend-down','amber','No gift in 45+ days despite prior pattern.'],
        ['high_potential','High-potential','fa-arrow-up-right-dots','purple','Highly engaged but giving little or nothing.'],
        ['major','Major donor candidates','fa-crown','navy','$1,000+ this year with strong engagement.'],
    ];
    startPage('Donor Intelligence', 'donors');
