    </tbody></table></div></div></div>
    <script>
    function genContent(){const b=document.getElementById('genBtn'),o=document.getElementById('cout');b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Generating…';o.innerHTML='<div class="typing"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
      const fd=new FormData();fd.append('action','ai_generate_content');fd.append('type',document.getElementById('ctype').value);fd.append('topic',document.getElementById('ctopic').value);
      fetch('?action=ai_generate_content',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{o.innerHTML=d.error?('⚠ '+acEsc(d.error)):acMD(d.body);window._lastGen=d.body||'';b.disabled=false;b.innerHTML='<i class="fa-solid fa-wand-magic-sparkles"></i> Generate';}).catch(()=>{o.textContent='⚠ Request failed.';b.disabled=false;b.innerHTML='Generate';});}
    function copyOut(){navigator.clipboard.writeText(window._lastGen||document.getElementById('cout').textContent)}
    function dlDoc(){if(!window._lastGen){alert('Generate something first');return;}var html='<html><head><meta charset="utf-8"></head><body style="font-family:Calibri,Arial,sans-serif">'+acMD(window._lastGen)+'</body></html>';var b=new Blob(['﻿'+html],{type:'application/msword'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='ai-church-'+(document.getElementById('ctype').value)+'.doc';a.click();}
    function dlPdf(){if(!window._lastGen){alert('Generate something first');return;}var s=document.createElement('script');s.src='?asset=jspdf_js';s.onload=function(){var J=window.jspdf.jsPDF;var doc=new J();doc.setFontSize(11);doc.text(doc.splitTextToSize(window._lastGen,180),15,18);doc.save('ai-church-'+(document.getElementById('ctype').value)+'.pdf');};document.body.appendChild(s);}
    </script>
    <?php endPage();
}




