function isBrandIcon(string $icon): bool {
    return in_array($icon, ['fa-stripe-s','fa-paypal','fa-vimeo','fa-youtube','fa-google','fa-mailchimp','fa-b'], true);
}

function brandSvg(string $key): string {
    if ($key === 'square') 
        return '<svg viewBox="0 0 24 24" width="1em" height="1em" fill="none" aria-hidden="true" style="vertical-align:-.12em"><rect x="3" y="3" width="18" height="18" rx="4.6" stroke="currentColor" stroke-width="2.5"/><rect x="8.7" y="8.7" width="6.6" height="6.6" rx="1.5" fill="currentColor"/></svg>';
    return '';
}

function intIcon(string $icon, string $color, bool $onBg = false): string {
    if (str_starts_with($icon, 'svg:')) {
        $c = $onBg ? '#fff' : $color;
        return '<span style="color:'.h($c).';display:inline-flex;line-height:1">'.brandSvg(substr($icon, 4)).'</span>';
    }
    $cls = 'fa-' . (isBrandIcon($icon) ? 'brands' : 'solid') . ' ' . h($icon);
    return $onBg ? '<i class="'.$cls.'"></i>' : '<i class="'.$cls.'" style="color:'.h($color).'"></i>';
}
