function systemDiagnostics(): array {
    $w = is_writable(__DIR__);
    $up = __DIR__.'/uploads';
    $rows = [
        ['PHP runtime', version_compare(PHP_VERSION,'7.4','>='), 'v'.PHP_VERSION.' — 7.4 or newer required', true],
        ['SQLite database (PDO)', extension_loaded('pdo_sqlite'), 'stores every member, gift and setting', true],
        ['cURL', function_exists('curl_init'), 'powers all integration syncs, Claude AI, Twilio SMS & giving APIs', true],
        ['OpenSSL / TLS', extension_loaded('openssl'), 'encrypts SMTP email and every outbound HTTPS API call', true],
        ['JSON', function_exists('json_encode'), 'settings, the JSON API and AI payloads', true],
        ['Secure random', function_exists('random_bytes'), 'CSRF tokens, API keys & 2-factor secrets', true],
        ['Hashing', function_exists('hash_equals') && function_exists('password_hash'), 'password storage & constant-time token checks', true],
        ['Writable storage', $w, 'so the database & uploads can be created', true],
        ['Multibyte strings', extension_loaded('mbstring'), 'accurate handling of names & messages', false],
        ['ZIP archive', class_exists('ZipArchive'), 'Excel (.xlsx) import & export', false],
        ['SimpleXML', function_exists('simplexml_load_string'), 'reading .xlsx spreadsheets on import', false],
        ['GD image library', extension_loaded('gd'), 'member-photo processing', false],
        ['Fileinfo', extension_loaded('fileinfo'), 'validating uploaded file types', false],
        ['Uploads folder writable', is_dir($up) ? is_writable($up) : $w, 'storing member photos', false],
    ];
    return $rows;
}

function renderSettings(): void {
    requireAdmin();
    $db = getDB();
    $user = currentUser();
    $totpOn = (bool)($user['totp_enabled'] ?? false);
    $pending = $_SESSION['totp_pending_secret'] ?? '';
    $S = fn($k)=>getSetting($k);
