    <script>
    function _intFD(k){var fd=new FormData();document.querySelectorAll('.int-row[data-int="'+k+'"] .int-field').forEach(function(f){fd.append(f.name,f.value);});return fd;}
    function applyInt(k){var o=document.getElementById('intout-'+k);o.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving…';
      fetch('?action=save_integration',{method:'POST',body:_intFD(k)}).then(function(r){return r.json();}).then(function(d){
        o.innerHTML=d.ok?'<span class="int-ok"><i class="fa-solid fa-circle-check"></i> Saved</span>':'<span class="int-err">'+(d.error||'Save failed')+'</span>';
      }).catch(function(){o.innerHTML='<span class="int-err">⚠ Save failed</span>';});}
    function testInt(k,action){var o=document.getElementById('intout-'+k);o.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving &amp; testing…';
      fetch('?action=save_integration',{method:'POST',body:_intFD(k)}).then(function(){return fetch('?action='+action,{method:'POST',body:new FormData()});}).then(function(r){return r.json();}).then(function(d){
        if(d.success||d.ok){var x=(d.imported!=null)?(' — imported '+d.imported+', updated '+d.updated):(d.message?(' — '+d.message):(d.reply?(' — '+d.reply):''));
          o.innerHTML='<span class="int-ok"><i class="fa-solid fa-plug-circle-check"></i> Connected'+x+'</span>';}
        else o.innerHTML='<span class="int-err"><i class="fa-solid fa-plug-circle-xmark"></i> '+(d.error||'Connection failed')+'</span>';
      }).catch(function(){o.innerHTML='<span class="int-err">⚠ Request failed</span>';});}
    </script>

    <div class="set-sec"><h3><i class="fa-solid fa-paper-plane"></i> Communications</h3><p>Send real email (SMTP) and text messages (Twilio) to your people. Use <strong>Apply</strong> to save a card on its own, and <strong>Test</strong> to send yourself a live message.</p></div>
    <div class="grid grid-2">
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-envelope" style="color:var(--blue-600)"></i> Email (SMTP)</div><span class="badge badge-<?=$S('smtp_host')?'active':'inactive'?>"><?=$S('smtp_host')?'Configured':'Not configured'?></span></div><div class="card-body">
        <div class="smtp-providers">
          <span class="smtp-prov-label"><i class="fa-solid fa-bolt"></i> Sign-in auto-setup:</span>
          <button type="button" class="prov-btn" onclick="smtpPreset('gmail')"><i class="fa-brands fa-google"></i> Gmail</button>
          <button type="button" class="prov-btn" onclick="smtpPreset('m365')"><i class="fa-brands fa-microsoft"></i> Microsoft 365</button>
          <button type="button" class="prov-btn" onclick="smtpPreset('outlook')"><i class="fa-brands fa-windows"></i> Outlook.com</button>
          <button type="button" class="prov-btn" onclick="smtpPreset('yahoo')"><i class="fa-brands fa-yahoo"></i> Yahoo</button>
          <button type="button" class="prov-btn" onclick="smtpPreset('icloud')"><i class="fa-brands fa-apple"></i> iCloud</button>
