        <div class="field"><label>Host</label><input class="input" name="smtp_host" value="<?=h($S('smtp_host'))?>" placeholder="mail.infomaniak.com"></div>
        <div class="field"><label>Port</label><input class="input" name="smtp_port" value="<?=h($S('smtp_port')?:'587')?>"></div>
        <div class="field"><label>Username</label><input class="input" name="smtp_user" value="<?=h($S('smtp_user'))?>"></div>
        <div class="field"><label>Password</label><input class="input" type="password" name="smtp_pass" value="<?=h($S('smtp_pass'))?>"></div>
        <div class="field"><label>From address</label><input class="input" type="email" name="smtp_from" value="<?=h($S('smtp_from'))?>"></div>
