        <div class="field"><label>Security</label><select class="select" name="smtp_secure"><?php foreach(['tls'=>'STARTTLS (587)','ssl'=>'SSL (465)','none'=>'None'] as $k=>$v): ?><option value="<?=$k?>" <?=$S('smtp_secure')===$k?'selected':''?>><?=$v?></option><?php endforeach; ?></select></div>
        <div class="field span2"><label>Send a test email to</label><input class="input" type="email" id="emailTestTo" value="<?=h($S('church_email'))?>" placeholder="you@church.org"></div>
      </div>
        <div class="int-actions" style="margin-top:var(--sp-3)">
          <button type="button" class="btn btn-outline btn-sm" onclick="applyComm('email')"><i class="fa-solid fa-floppy-disk"></i> Apply</button>
          <button type="button" class="btn btn-outline btn-sm" onclick="testComm('email')"><i class="fa-solid fa-paper-plane"></i> Test</button>
          <span class="int-out" id="commout-email"></span>
        </div>
      </div></div>
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-comment-sms" style="color:var(--green)"></i> SMS (Twilio)</div><span class="badge badge-<?=$S('twilio_sid')?'active':'inactive'?>"><?=$S('twilio_sid')?'Configured':'Not configured'?></span></div><div class="card-body"><div class="form-grid">
        <div class="field span2"><label>Account SID</label><input class="input" name="twilio_sid" value="<?=h($S('twilio_sid'))?>"></div>
        <div class="field span2"><label>Auth token</label><input class="input" type="password" name="twilio_token" value="<?=h($S('twilio_token'))?>"></div>
        <div class="field span2"><label>From number</label><input class="input" name="twilio_from" value="<?=h($S('twilio_from'))?>" placeholder="+15551234567"></div>
        <div class="field span2"><label>Send a test text to</label><input class="input" id="smsTestTo" value="<?=h($S('church_phone'))?>" placeholder="+15551234567"></div>
      </div>
        <div class="int-actions" style="margin-top:var(--sp-3)">
          <button type="button" class="btn btn-outline btn-sm" onclick="applyComm('sms')"><i class="fa-solid fa-floppy-disk"></i> Apply</button>
          <button type="button" class="btn btn-outline btn-sm" onclick="testComm('sms')"><i class="fa-solid fa-paper-plane"></i> Test</button>
          <span class="int-out" id="commout-sms"></span>
        </div>
      </div></div>
    </div>
    <script>
    
    var SMTP_PRESETS={
      gmail:{host:'smtp.gmail.com',port:'587',secure:'tls',name:'Gmail',hint:'Gmail needs an <b>App Password</b> (not your normal password): turn on 2-Step Verification, create one at <a href="https://myaccount.google.com/apppasswords" target="_blank" rel="noopener">myaccount.google.com/apppasswords</a>, and paste it as the Password. Use your full Gmail address as Username &amp; From.'},
      m365:{host:'smtp.office365.com',port:'587',secure:'tls',name:'Microsoft 365',hint:'Microsoft 365 / Exchange Online. Use your full work email as Username &amp; From. If MFA is on, create an <b>app password</b> in Microsoft account security. Your admin may need to enable SMTP AUTH for the mailbox.'},
      outlook:{host:'smtp-mail.outlook.com',port:'587',secure:'tls',name:'Outlook.com',hint:'Personal Outlook.com / Hotmail / Live. Use your full address as Username &amp; From. With 2-step on, create an <b>app password</b> at <a href="https://account.live.com/proofs/AppPassword" target="_blank" rel="noopener">account.live.com</a>.'},
      yahoo:{host:'smtp.mail.yahoo.com',port:'465',secure:'ssl',name:'Yahoo',hint:'Yahoo Mail requires an <b>app password</b> from Account Security. Use your full Yahoo address as Username &amp; From.'},
      icloud:{host:'smtp.mail.me.com',port:'587',secure:'tls',name:'iCloud',hint:'iCloud Mail requires an <b>app-specific password</b> from appleid.apple.com. Use your iCloud address as Username &amp; From.'},
      infomaniak:{host:'mail.infomaniak.com',port:'587',secure:'tls',name:'Infomaniak',hint:'Infomaniak mail hosting. Use your full mailbox address as Username &amp; From, and your mailbox password.'}
    };
    function smtpPreset(p){var s=SMTP_PRESETS[p];if(!s)return;
      function set(n,v){var el=document.querySelector('[name="'+n+'"]');if(el)el.value=v;}
      set('smtp_host',s.host);set('smtp_port',s.port);set('smtp_secure',s.secure);
      var u=document.querySelector('[name="smtp_user"]'),f=document.querySelector('[name="smtp_from"]'),fn=document.querySelector('[name="smtp_from_name"]');
      if(u&&!u.value&&f&&f.value)u.value=f.value;
      if(fn&&!fn.value)fn.value=<?=json_encode(getSetting('church_name')?:'Free Church ChMS')?>;
      var h=document.getElementById('smtpHint');h.style.display='block';
      h.innerHTML='<i class="fa-solid fa-circle-info"></i> <b>'+s.name+'</b> server settings filled in — now add your email address &amp; password below, then <b>Apply</b> and <b>Test</b>. '+s.hint;
      var pw=document.querySelector('[name="smtp_pass"]');if(f&&!f.value){f.focus();}else if(pw){pw.focus();}
    }
    var COMM_KEYS={email:['smtp_host','smtp_port','smtp_user','smtp_pass','smtp_from','smtp_from_name','smtp_secure'],sms:['twilio_sid','twilio_token','twilio_from']};
    function _commFD(kind){var fd=new FormData();COMM_KEYS[kind].forEach(function(n){var el=document.querySelector('[name="'+n+'"]');if(el)fd.append(n,el.value);});return fd;}
    function applyComm(kind){var o=document.getElementById('commout-'+kind);o.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving…';
      fetch('?action=save_comm',{method:'POST',body:_commFD(kind)}).then(function(r){return r.json();}).then(function(d){
        o.innerHTML=d.ok?'<span class="int-ok"><i class="fa-solid fa-circle-check"></i> Saved</span>':'<span class="int-err">'+(d.error||'Save failed')+'</span>';
      }).catch(function(){o.innerHTML='<span class="int-err">⚠ Save failed</span>';});}
    function testComm(kind){var o=document.getElementById('commout-'+kind);
      var to=document.getElementById(kind==='email'?'emailTestTo':'smsTestTo').value.trim();
      if(!to){o.innerHTML='<span class="int-err">Enter a '+(kind==='email'?'test email address':'phone number')+' first.</span>';return;}
      o.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving &amp; sending…';
      fetch('?action=save_comm',{method:'POST',body:_commFD(kind)}).then(function(){var fd=_commFD(kind);fd.append('to',to);fd.append('ajax','1');return fetch('?action='+(kind==='email'?'test_email':'test_sms'),{method:'POST',body:fd});}).then(function(r){return r.json();}).then(function(d){
        o.innerHTML=d.ok?'<span class="int-ok"><i class="fa-solid fa-circle-check"></i> '+(d.message||'Sent')+'</span>':'<span class="int-err"><i class="fa-solid fa-circle-xmark"></i> '+(d.error||'Failed')+'</span>';
      }).catch(function(){o.innerHTML='<span class="int-err">⚠ Request failed</span>';});}
    </script>
