function renderMigrate(): void {
    requireAdmin();
    $db = getDB();
    $cnt = fn($t) => (int)$db->query("SELECT COUNT(*) FROM $t")->fetchColumn();
    $hsize = function (float $b) { if ($b >= 1073741824) return number_format($b/1073741824,2).' GB'; if ($b >= 1048576) return number_format($b/1048576,1).' MB'; if ($b >= 1024) return number_format($b/1024,0).' KB'; return $b.' B'; };
    $dbSize = (float)(@filesize(__DIR__.'/aichurch.db') ?: 0);
    $upBytes = 0.0; $upFiles = 0; $updir = __DIR__.'/uploads';
    if (is_dir($updir)) { $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($updir, FilesystemIterator::SKIP_DOTS)); foreach ($it as $f) { if ($f->isFile()) { $upFiles++; $upBytes += $f->getSize(); } } }
    $hero = file_exists(__DIR__.'/assets/migrate-hero.webp') ? 'assets/migrate-hero.webp' : 'assets/network.webp';
    $steps = [
        ['fa-cloud-arrow-down','Download your backup','One click below packages your whole church — database, photos and logo — into a single file. Nothing is left behind.'],
        ['fa-folder-tree','Put the app on your new host','Upload app.php — the single file that is your whole Free Church ChMS — into an empty folder on your new PHP host. Nothing else needs to go with it.'],
        ['fa-database','Restore your data','Drop the aichurch.db file and the uploads/ folder from your backup into that same folder, and make it writable.'],
        ['fa-heart','Open your new home','Visit the site. Every member, gift, setting and login is exactly where you left it. That\'s the whole move.'],
    ];
    startPage('Backup & Migration', 'migrate');
    ?>
    <div class="pulse-hero fade-in" style="--ph-img:url('<?=h($hero)?>')">
      <div class="pulse-hero-in">
        <div class="ph-eyebrow"><i class="fa-solid fa-truck-fast"></i> Your data, your freedom</div>
        <h2>Take Free Church ChMS anywhere — in one click</h2>
        <p>Your church owns its data, completely. Whenever you move to a new web host, this packages everything into one file and walks you through a calm, simple restore. No lock-in, ever.</p>
        <div class="ph-actions">
          <a class="btn btn-light" href="?action=export_backup&amp;csrf=<?=h(csrfToken())?>"><i class="fa-solid fa-download"></i> Download full backup</a>
          <a class="btn btn-light btn-sm" href="DEPLOYMENT-GUIDE.html" target="_blank" rel="noopener"><i class="fa-solid fa-book-open"></i> Deployment Guide</a>
        </div>
      </div>
    </div>

    <div class="stat-grid">
      <div class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-users"></i></div><div><div class="stat-value"><?=number_format($cnt('members'))?></div><div class="stat-label">Members</div></div></div>
      <div class="stat-card"><div class="stat-icon green"><i class="fa-solid fa-gift"></i></div><div><div class="stat-value"><?=number_format($cnt('giving'))?></div><div class="stat-label">Gift records</div></div></div>
      <div class="stat-card"><div class="stat-icon purple"><i class="fa-solid fa-database"></i></div><div><div class="stat-value"><?=$hsize($dbSize)?></div><div class="stat-label">Database size</div></div></div>
      <div class="stat-card"><div class="stat-icon amber"><i class="fa-solid fa-image"></i></div><div><div class="stat-value"><?=number_format($upFiles)?></div><div class="stat-label">Uploaded files · <?=$hsize($upBytes)?></div></div></div>
    </div>

    <div class="grid grid-2" style="margin-top:var(--sp-5)">
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-box-archive" style="color:var(--blue-600)"></i> What's in your backup</div></div><div class="card-body">
        <div class="mig-inside"><i class="fa-solid fa-database" style="color:var(--violet)"></i><div><strong>aichurch.db</strong><span>Your complete database — members, giving, attendance, groups, pledges, settings, users and 2FA. A clean, consistent point-in-time snapshot.</span></div></div>
        <div class="mig-inside"><i class="fa-solid fa-images" style="color:var(--green-dark)"></i><div><strong>uploads/</strong><span>Every member photo and your church logo, kept in their original folders.</span></div></div>
        <div class="mig-inside"><i class="fa-solid fa-file-lines" style="color:var(--blue-600)"></i><div><strong>RESTORE-README.txt</strong><span>Plain-English restore steps tucked right inside the package, so anyone can follow them.</span></div></div>
        <div class="alert alert-warning" style="margin-top:var(--sp-4)"><i class="fa-solid fa-lock"></i><div>Your backup contains API keys and password hashes. Keep the file private and remove it from shared drives once your move is finished.</div></div>
      </div></div>
      <div class="card"><div class="card-head"><div class="card-title"><i class="fa-solid fa-route" style="color:var(--blue-600)"></i> Moving to a new host</div></div><div class="card-body">
        <ol class="mig-steps">
          <?php foreach ($steps as $n=>[$icon,$t,$d]): ?>
          <li><span class="mig-num"><?=$n+1?></span><div><div class="mig-step-t"><i class="fa-solid <?=$icon?>" style="color:var(--blue-600)"></i> <?=h($t)?></div><div class="mig-step-d"><?=h($d)?></div></div></li>
          <?php endforeach; ?>
        </ol>
        <a class="btn btn-primary" href="?action=export_backup&amp;csrf=<?=h(csrfToken())?>" style="margin-top:var(--sp-2)"><i class="fa-solid fa-download"></i> Download full backup</a>
      </div></div>
    </div>
    <p style="font-size:var(--text-xs);color:var(--gray-400);margin-top:var(--sp-5)"><i class="fa-solid fa-shield-heart" style="color:var(--green)"></i> Want a hand? Your data is yours and we'll help you move it for free — ask through the Knowledge Base. We say yes to every church.</p>
    <?php endPage();
}




