    <script src="?asset=qrcode_js"></script>
    <script src="?asset=xlsx_js"></script>
    <script src="?asset=jspdf_js"></script>
    <script src="?asset=jspdf_at_js"></script>
    <script>
    const APPBASE="<?=h($base)?>";
    const QR_SERVICES=<?=json_encode(array_map(fn($s)=>['id'=>(int)$s['id'],'name'=>$s['name'],'date'=>$s['date'],'type'=>$s['type']],$services))?>;
    const CHURCH_LOGO=<?=json_encode($logo)?>;
    const CHURCH_NAME=<?=json_encode($church)?>;
    const CHECKIN_TOKEN=<?=json_encode(getSetting('checkin_token'))?>;
    const IMPORT_HINTS={
      members:"Columns we read: <b>first_name</b>, <b>last_name</b>, <b>email</b>, <b>phone</b>, <b>status</b>. Existing people are matched by email and updated; new ones are added.",
      giving:"Columns we read: <b>email</b> (or first_name + last_name) to match the giver, <b>amount</b>, <b>date</b>, <b>fund</b>, <b>method</b>, <b>check_number</b>, <b>notes</b>. Unknown givers and funds are created automatically so nothing is lost.",
      attendance:"Columns we read: <b>service</b> (or service_name) &amp; <b>date</b> for the gathering, plus <b>email</b> (or first_name + last_name) to match each person. The service is created if it doesn't exist; duplicate check-ins are ignored."
    };
    function importHint(){var t=document.getElementById('importType').value;document.getElementById('importHint').innerHTML=IMPORT_HINTS[t]||'';}
    importHint();
    function exportPDF(type,label){const fd=new FormData();fd.append('action','generate_report');fd.append('type',type);
      fetch('?action=generate_report',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(!d.rows||!d.rows.length){alert('No data for '+label);return;}
        const {jsPDF}=window.jspdf;const doc=new jsPDF();doc.setFontSize(16);doc.text(<?=json_encode(getSetting('church_name')?:'Free Church ChMS')?>+' — '+label,14,16);
        doc.autoTable({startY:22,head:[Object.keys(d.rows[0]).map(k=>k.replace(/_/g,' '))],body:d.rows.map(r=>Object.values(r).map(v=>v==null?'':v)),styles:{fontSize:8},headStyles:{fillColor:[46,91,255]}});
        doc.save(label.replace(/ /g,'_')+'.pdf');});}
    const QR_MON=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
    function qrSvg(url,cell){var q=qrcode(0,'M');q.addData(url);q.make();return q.createSvgTag({cellSize:cell||4,margin:0,scalable:false});}
    function qrPoster(s){
      var d=new Date(String(s.date||'').replace(/-/g,'/')); var dd=isNaN(d)?'':d.getDate(); var mm=isNaN(d)?'':QR_MON[d.getMonth()];
      var url=APPBASE+'?action=selfcheckin&service='+s.id+'&t='+encodeURIComponent(CHECKIN_TOKEN);
      var brand=CHURCH_LOGO?('<img src="'+CHURCH_LOGO+'" alt="">'):('<span class="qr-cn">'+acEsc(CHURCH_NAME)+'</span>');
      return '<div class="qr-brand">'+brand+'</div>'+
        '<div class="qr-meta"><span class="qr-date"><b>'+dd+'</b><i>'+mm+'</i></span><span class="qr-svc">'+acEsc(s.name)+'</span></div>'+
        '<div class="qr-code">'+qrSvg(url,4)+'</div>'+
        '<div class="qr-tag"><i class="fa-solid fa-mobile-screen-button"></i> Scan to check in</div>';
    }
    (function(){var cal=document.getElementById('qrCal');if(!cal)return;
      if(!QR_SERVICES.length){cal.style.display='none';var e=document.getElementById('qrEmpty');if(e)e.style.display='block';return;}
      QR_SERVICES.forEach(function(s){var c=document.createElement('div');c.className='qr-card';c.innerHTML=qrPoster(s);
        c.title='Click to print this check-in code';c.onclick=function(){qrPrintOne(s);};cal.appendChild(c);});})();
    var QG_LOGO=<?=json_encode($logo ?: '')?>;
    function qgBuild(){var ecc=(document.getElementById('qg_ecc')||{}).value||'M';var txt=(document.getElementById('qg_text')||{}).value||' ';var qr=qrcode(0,ecc);qr.addData(txt);qr.make();return qr;}
    function qgRender(canvas,px){var qr=qgBuild();var n=qr.getModuleCount();var color=(document.getElementById('qg_color')||{}).value||'#0f1f4e';
      var quiet=4,total=n+quiet*2,scale=Math.max(1,Math.floor(px/total)),size=total*scale;
      canvas.width=size;canvas.height=size;var ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,size,size);ctx.fillStyle=color;
      for(var r=0;r<n;r++)for(var c=0;c<n;c++){if(qr.isDark(r,c))ctx.fillRect((c+quiet)*scale,(r+quiet)*scale,scale,scale);}
      return canvas;}
    function qgLogo(canvas,cb){var sel=document.getElementById('qg_logo');var use=sel&&sel.value==='1'&&QG_LOGO;if(!use){cb();return;}
      var img=new Image();img.onload=function(){var ctx=canvas.getContext('2d'),s=canvas.width,box=Math.round(s*0.20),x=Math.round((s-box)/2),pad=Math.round(box*0.12);
        ctx.fillStyle='#fff';ctx.fillRect(x-pad,x-pad,box+pad*2,box+pad*2);ctx.drawImage(img,x,x,box,box);cb();};img.onerror=cb;img.src=QG_LOGO;}
    function qgUpdate(){var c=document.getElementById('qg_canvas');if(!c)return;qgRender(c,240);qgLogo(c,function(){});c.style.width='240px';
      document.getElementById('qg_lbl').textContent=(document.getElementById('qg_label')||{}).value||'';}
    function qgDownload(){var px=parseInt((document.getElementById('qg_size')||{}).value,10)||600;var t=document.createElement('canvas');qgRender(t,px);
      qgLogo(t,function(){t.toBlob(function(b){var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='qr-code.png';a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},2000);});});}
    function qgPrint(){var px=parseInt((document.getElementById('qg_size')||{}).value,10)||600;var t=document.createElement('canvas');qgRender(t,px);
      qgLogo(t,function(){var url=t.toDataURL('image/png');var lbl=((document.getElementById('qg_label')||{}).value||'').replace(/[<>&]/g,'');var w=window.open('','_blank','width=520,height=640');if(!w)return;
        w.document.write('<!doctype html><title>QR code</title><body style="margin:0;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:Inter,system-ui,sans-serif"><img src="'+url+'" style="width:360px;height:360px"><div style="margin-top:14px;font-size:18px;color:#111;font-weight:700">'+lbl+'</div></body>');w.document.close();setTimeout(function(){w.focus();w.print();},350);});}
    qgUpdate();
    function qrPrintOne(s){var w=window.open('','_blank','width=520,height=720');if(!w)return;
      var css='*{box-sizing:border-box;margin:0;font-family:Inter,system-ui,sans-serif}body{padding:40px;background:#fff;display:flex;justify-content:center}'+
        '.p{width:380px;border:1px solid #e5e7eb;border-radius:18px;padding:30px 26px;text-align:center;box-shadow:0 10px 40px rgba(16,24,64,.10)}'+
        '.qr-brand{min-height:46px;display:flex;align-items:center;justify-content:center;margin-bottom:14px}.qr-brand img{max-height:54px;max-width:230px;object-fit:contain}.qr-cn{font-weight:800;font-size:19px;color:#0f1f4e}'+
        '.qr-meta{margin-bottom:16px}.qr-date{display:inline-flex;flex-direction:column;line-height:1;color:#2E5BFF;font-weight:800;margin-bottom:6px}.qr-date b{font-size:30px}.qr-date i{font-style:normal;font-size:12px;letter-spacing:.12em}'+
        '.qr-svc{display:block;font-size:18px;font-weight:700;color:#111827;margin-top:6px}'+
        '.qr-code svg{width:230px;height:230px}.qr-tag{margin-top:16px;font-size:14px;font-weight:600;color:#2E5BFF;background:#eff4ff;border-radius:999px;padding:8px 16px;display:inline-block}@media print{body{padding:0}.p{border:none;box-shadow:none}}';
      w.document.write('<!doctype html><html><head><title>Check-in code</title><style>'+css+'</style></head><body><div class="p">'+qrPoster(s)+'</div></body></html>');
      w.document.close();setTimeout(function(){w.focus();w.print();},450);}
    function lookupVerse(){const ref=document.getElementById('verseRef').value,o=document.getElementById('verseOut');o.innerHTML='<div class="typing"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
      const fd=new FormData();fd.append('ref',ref);fetch('?action=bible_verse',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{o.innerHTML=d.error?('⚠ '+acEsc(d.error)):('<strong>'+acEsc(d.reference)+'</strong><br>'+acEsc(d.text)+'<div style="font-size:12px;color:#9ca3af;margin-top:6px">'+acEsc(d.translation||'')+'</div>');}).catch(()=>o.textContent='⚠ Lookup failed');}
    function acCellSafe(v){return (typeof v==='string' && /^[=+\-@\t\r]/.test(v)) ? ("'"+v) : v;} // neutralize spreadsheet formula injection
    function exportReport(type,label){const fd=new FormData();fd.append('action','generate_report');fd.append('type',type);
      fetch('?action=generate_report',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(!d.rows||!d.rows.length){alert('No data for '+label);return;}
        const safe=d.rows.map(row=>{const o={};for(const k in row)o[k]=acCellSafe(row[k]);return o;});
        const ws=XLSX.utils.json_to_sheet(safe);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,label.slice(0,28));XLSX.writeFile(wb,label.replace(/ /g,'_')+'.xlsx',{compression:true});});}
    </script>
    <?php endPage();
}




