function renderPrint(): void {
    $db = getDB();
    $type = $_GET['type'] ?? 'directory';
    $church = getSetting('church_name') ?: 'Our Church';
    $addr = getSetting('church_address'); $yr = date('Y');
    $logo = getSetting('church_logo_url');
    ob_start();
    if ($type === 'giving_statement') {
        $mid = (int)($_GET['id'] ?? 0);
        $m = $db->prepare('SELECT * FROM members WHERE id=?'); $m->execute([$mid]); $m = $m->fetch();
        $rows = $db->prepare("SELECT g.date,g.amount,g.method,f.name fund FROM giving g LEFT JOIN funds f ON f.id=g.fund_id WHERE g.member_id=? AND strftime('%Y',g.date)=? ORDER BY g.date");
        $rows->execute([$mid,$yr]); $rows = $rows->fetchAll();
        $total = array_sum(array_column($rows,'amount'));
        $title = "$yr Giving Statement";
        echo "<h1>$yr Contribution Statement</h1>";
        echo "<p class='to'><strong>".h(($m['first_name']??'').' '.($m['last_name']??''))."</strong><br>".h($m['email']??'')."</p>";
        echo "<table><thead><tr><th>Date</th><th>Fund</th><th>Method</th><th class='r'>Amount</th></tr></thead><tbody>";
        foreach ($rows as $r) echo "<tr><td>".h($r['date'])."</td><td>".h($r['fund']?:'General')."</td><td>".h($r['method'])."</td><td class='r'>".fmt((float)$r['amount'])."</td></tr>";
        echo "</tbody><tfoot><tr><td colspan='3'><strong>Total tax-deductible contributions</strong></td><td class='r'><strong>".fmt($total)."</strong></td></tr></tfoot></table>";
        echo "<p class='fine'>No goods or services were provided in exchange for these contributions except intangible religious benefits. Please retain for your tax records.</p>";
    } elseif ($type === 'attendance') {
        $rows = $db->query("SELECT s.date,s.name,s.head_count,(SELECT COUNT(*) FROM attendance a WHERE a.service_id=s.id) recorded FROM services s ORDER BY s.date DESC LIMIT 60")->fetchAll();
        $title = 'Attendance Report';
        echo "<h1>Attendance Report</h1><table><thead><tr><th>Date</th><th>Service</th><th class='r'>Head count</th><th class='r'>Checked in</th></tr></thead><tbody>";
        foreach ($rows as $r) echo "<tr><td>".h($r['date'])."</td><td>".h($r['name'])."</td><td class='r'>".(int)$r['head_count']."</td><td class='r'>".(int)$r['recorded']."</td></tr>";
        echo "</tbody></table>";
    } elseif ($type === 'donors') {
        $rows = $db->query("SELECT m.first_name,m.last_name,SUM(g.amount) total,COUNT(*) gifts FROM giving g JOIN members m ON m.id=g.member_id WHERE strftime('%Y',g.date)='$yr' GROUP BY g.member_id ORDER BY total DESC LIMIT 100")->fetchAll();
        $title = "$yr Donor Report";
        echo "<h1>$yr Donor Report</h1><table><thead><tr><th>Donor</th><th class='r'>Gifts</th><th class='r'>Total</th></tr></thead><tbody>";
        foreach ($rows as $r) echo "<tr><td>".h($r['first_name'].' '.$r['last_name'])."</td><td class='r'>".(int)$r['gifts']."</td><td class='r'>".fmt((float)$r['total'])."</td></tr>";
        echo "</tbody></table>";
    } else { 
        $rows = $db->query("SELECT first_name,last_name,email,phone,city,state FROM members WHERE status='active' ORDER BY last_name,first_name")->fetchAll();
        $title = 'Member Directory';
        echo "<h1>Member Directory</h1><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>City</th></tr></thead><tbody>";
        foreach ($rows as $r) echo "<tr><td>".h($r['last_name'].', '.$r['first_name'])."</td><td>".h($r['email'])."</td><td>".h($r['phone'])."</td><td>".h(trim(($r['city']?:'').' '.($r['state']?:'')))."</td></tr>";
        echo "</tbody></table>";
    }
    $body = ob_get_clean();
    ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title><?=h($title)?></title>
