function leaderCandidates(): array {
    $db = getDB();
    
    $members = $db->query("SELECT m.*,
        (SELECT COUNT(*) FROM attendance a JOIN services s ON s.id=a.service_id WHERE a.member_id=m.id AND s.date>=date('now','-90 days')) att90,
        (SELECT COUNT(DISTINCT gm.group_id) FROM group_members gm WHERE gm.member_id=m.id) grp_count,
        (SELECT COUNT(*) FROM volunteers v WHERE v.member_id=m.id AND v.active=1) vol_count,
        (SELECT COUNT(*) FROM giving g WHERE g.member_id=m.id AND g.date>=date('now','-90 days')) gifts90,
        (SELECT COALESCE(SUM(g.amount),0) FROM giving g WHERE g.member_id=m.id AND strftime('%Y',g.date)=strftime('%Y','now')) ytd_giving
        FROM members m WHERE m.status='active' AND m.engagement_score>=50
        ORDER BY m.engagement_score DESC LIMIT 2000")->fetchAll();
        
        

    $candidates = [];
    foreach ($members as $m) {
        
        if ((int)($m['engagement_score']??0) < 50) continue;
        $att    = min(30, (int)$m['att90'] * 3);                          
        $eng    = (int)round(((int)($m['engagement_score']??0) / 100) * 30); 
        $serve  = min(20, ((int)$m['grp_count'] * 7) + ((int)$m['vol_count'] * 10)); 
        $give   = min(20, (int)$m['gifts90'] >= 3 ? 20 : ((int)$m['gifts90'] * 6));  
        $score  = $att + $eng + $serve + $give;
        if ($score < 35) continue; 
        $m['pipeline_score']  = $score;
        $m['pipeline_att']    = (int)$m['att90'];
        $m['pipeline_groups'] = (int)$m['grp_count'];
        $m['pipeline_vol']    = (int)$m['vol_count'];
        $m['pipeline_gifts']  = (int)$m['gifts90'];
        $m['pipeline_ytd']    = (float)$m['ytd_giving'];
        $candidates[] = $m;
    }
    usort($candidates, fn($a,$b)=>$b['pipeline_score']<=>$a['pipeline_score']);
    
    $seg = ['emerging'=>[],'small_group'=>[],'ministry'=>[],'high_impact'=>[]];
    foreach ($candidates as $c) {
        if ($c['pipeline_ytd'] >= 500 && $c['pipeline_score'] >= 70)       { $seg['high_impact'][] = $c; continue; }
        if ($c['pipeline_vol'] >= 1 && $c['pipeline_score'] >= 65)         { $seg['ministry'][] = $c; continue; }
        if ($c['pipeline_groups'] >= 1 && $c['pipeline_score'] >= 55)      { $seg['small_group'][] = $c; continue; }
        $seg['emerging'][] = $c;
    }
    return $seg;
}

