    <script>
    function updateStreamHelp(){
      var v=document.getElementById('streamPlat').value;
      ['ytHelp','fbHelp','customHelp'].forEach(id=>document.getElementById(id).style.display='none');
      if(v==='youtube')document.getElementById('ytHelp').style.display='';
      else if(v==='facebook')document.getElementById('fbHelp').style.display='';
      else document.getElementById('customHelp').style.display='';
    }
    updateStreamHelp();
    function editRec(r){
      document.getElementById('recId').value=r.id;
      document.getElementById('recTitle').value=r.title||'';
