function parseBankFile(string $raw): array {
    $raw = trim($raw); $out = [];
    if (stripos($raw, '<OFX') !== false || stripos($raw, '<STMTTRN>') !== false) {
        if (preg_match_all('#<STMTTRN>(.*?)</STMTTRN>#is', $raw, $m)) {
            foreach ($m[1] as $blk) {
                $get = function (string $tag) use ($blk) { return preg_match('#<'.$tag.'>([^<\r\n]*)#i', $blk, $x) ? trim($x[1]) : ''; };
                $dt = $get('DTPOSTED'); $y = substr($dt,0,4); $mo = substr($dt,4,2); $d = substr($dt,6,2);
                $out[] = [
                    'date'   => ($y && $mo && $d) ? "$y-$mo-$d" : date('Y-m-d'),
                    'amount' => (float)str_replace(',', '', $get('TRNAMT')),
                    'payee'  => $get('NAME') ?: $get('PAYEE'),
                    'memo'   => $get('MEMO'),
                    'fitid'  => $get('FITID'),
                ];
            }
        }
        return $out;
    }
    
    $lines = preg_split('/\r\n|\r|\n/', $raw); $idx = ['date'=>0,'amount'=>1,'desc'=>2]; $header = null;
    foreach ($lines as $ln) {
        if (trim($ln) === '') continue;
        $cells = str_getcsv($ln);
        if ($header === null) {
            $low = array_map(fn($c)=>strtolower(trim($c)), $cells);
            if (preg_grep('/date|amount|amt|debit|credit|desc|payee|memo/', $low)) {
                foreach ($low as $j=>$hn) {
                    if (preg_match('/date/', $hn)) $idx['date']=$j;
                    elseif (preg_match('/amount|amt|debit|credit/', $hn)) $idx['amount']=$j;
                    elseif (preg_match('/desc|payee|name|memo|detail/', $hn)) $idx['desc']=$j;
                }
                $header = true; continue;   
            }
            $header = false;                
        }
        $date = trim($cells[$idx['date']] ?? ''); $ts = strtotime($date);
        $amount = (float)preg_replace('/[^0-9.\-]/', '', $cells[$idx['amount']] ?? '0');
        $desc = trim($cells[$idx['desc']] ?? '');
        if ($amount == 0.0 && $desc === '') continue;
        $out[] = ['date'=>$ts?date('Y-m-d',$ts):date('Y-m-d'), 'amount'=>$amount, 'payee'=>$desc, 'memo'=>'', 'fitid'=>''];
    }
    return $out;
}


function cleanName(string $s): string {
    $s = trim(preg_replace('/\s+/u', ' ', (string)$s) ?? '');
    $out = preg_replace_callback('/[^\s]+/u', function ($m) {
        $w = $m[0];
        return ($w === strtoupper($w) || $w === strtolower($w)) ? ucfirst(strtolower($w)) : $w;
    }, $s);
    return $out === null ? $s : $out;
}


function selfCheckinForm(array $svc, string $tok, ?array $known, string $step = 'choose', string $err = '', array $vals = [], string $church = 'our church'): string {
    $sid = (int)$svc['id']; $v = fn($k) => h($vals[$k] ?? '');
    $kiosk = !empty($GLOBALS['ac_kiosk']); $kq = $kiosk ? '&amp;kiosk=1' : '';
    $base = '?action=selfcheckin&amp;service='.$sid.'&amp;t='.h($tok).$kq;
    $hidden = '<input type="hidden" name="service" value="'.$sid.'"><input type="hidden" name="t" value="'.h($tok).'"><input type="hidden" name="do" value="1">'.($kiosk?'<input type="hidden" name="kiosk" value="1">':'').'<input class="hp" type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">';
    $errHtml = $err ? '<div class="err">'.h($err).'</div>' : '';
    if ($known) {
        return '<h1>Welcome back, '.h($known['first_name']).'! 👋</h1><p>Tap below to check in for today.</p>'
             .'<form method="POST" action="?action=selfcheckin">'.$hidden.'<input type="hidden" name="mode" value="known"><input type="hidden" name="member_id" value="'.(int)$known['id'].'">'
             .'<button class="btn" type="submit"><i class="fa-solid fa-check"></i> Check me in</button></form>'
             .'<div class="muted"><a href="'.$base.'&amp;new=1">Not '.h($known['first_name']).'? Check in as someone else</a></div>';
    }
    if ($step === 'member') {
        return '<h1>Welcome back!</h1><p>Find your record and we\'ll check you in.</p>'.$errHtml
             .'<form method="POST" action="?action=selfcheckin">'.$hidden.'<input type="hidden" name="mode" value="member">'
             .'<label>Your email or full name</label><input name="lookup" value="'.$v('lookup').'" placeholder="you@email.com — or — Jane Smith" required autocomplete="email">'
             .'<button class="btn" type="submit"><i class="fa-solid fa-check"></i> Find me &amp; check in</button></form>'
             .'<div class="muted"><a href="'.$base.'&amp;as=visitor">First time here? Check in as a guest →</a></div>';
    }
    if ($step === 'visitor') {
        return '<h1>Welcome, guest! 🙌</h1><p>Tell us who you are and we\'ll save your spot.</p>'.$errHtml
             .'<form method="POST" action="?action=selfcheckin">'.$hidden.'<input type="hidden" name="mode" value="visitor">'
             .'<div class="row"><div><label>First name</label><input name="first_name" value="'.$v('first_name').'" required autocomplete="given-name"></div>'
             .'<div><label>Last name</label><input name="last_name" value="'.$v('last_name').'" required autocomplete="family-name"></div></div>'
             .'<label>Email <span class="opt">(optional)</span></label><input type="email" name="email" value="'.$v('email').'" autocomplete="email">'
             .'<label>Mobile <span class="opt">(optional)</span></label><input type="tel" name="phone" value="'.$v('phone').'" autocomplete="tel">'
             .'<label class="chk"><input type="checkbox" name="join" value="1"> I\'d like to become a member of '.h($church).'</label>'
             .'<button class="btn" type="submit"><i class="fa-solid fa-check"></i> Check me in</button></form>'
             .'<div class="muted"><a href="'.$base.'&amp;as=member">Already a member? Find your record →</a></div>';
    }
    
    return '<h1>Welcome! 👋</h1><p>Let\'s get you checked in for today. Which are you?</p>'
         .'<a class="btn" href="'.$base.'&amp;as=member"><i class="fa-solid fa-id-badge"></i> I\'m a member</a>'
         .'<a class="btn btn-alt" href="'.$base.'&amp;as=visitor"><i class="fa-solid fa-hand-sparkles"></i> I\'m a visitor</a>';
}





