    function wtTradLabel(t){return t==='orthodox'?'Orthodox Christian':'Catholic Christian';}
    function wtBlk(label,text){return '<div class="wcard-block'+(label==='What this means for you'?' wcard-meaning':'')+'"><b>'+label+'</b>'+acEsc(text||'')+'</div>';}
    function wtCardHTML(v,c,trad,fmt){
      var logo = WLOGO ? '<img class="wcard-logo" src="'+acEsc(WLOGO)+'" alt="">' : '';
      var refl = WTAI[v.ref+'|'+trad] || c.reflection;
      return ''
       +'<div class="wcard-top">'+logo+'<div class="wcard-church">'+acEsc(WCHURCH)+'</div><div class="wcard-trad">'+acEsc(wtTradLabel(trad))+' &middot; A word of faith</div></div>'
       +'<div class="wcard-body">'
       +'<div class="wcard-ref">'+acEsc(v.ref)+'</div>'
       +'<blockquote class="wcard-verse">&ldquo;'+acEsc(v.verseText)+'&rdquo;</blockquote>'
       +'<div class="wcard-rule"></div>'
       +'<h3 class="wcard-headline">'+acEsc(c.headline)+'</h3>'
       +'<p class="wcard-reflection">'+acEsc(refl)+'</p>'
       +wtBlk('What this means for you',c.meaning)
       +wtBlk('An invitation',c.invitation)
       +'<div class="wcard-prayer"><b>A short prayer</b>'+acEsc(c.prayer)+'</div>'
       +'</div>'
       +'<div class="wcard-foot">'+acEsc(WCHURCH)+'<span class="cx">&#10013;</span>'+acEsc(c.traditionNote)+'</div>';
    }
    function wtRender(){
      var v=WT[wtState.i], c=v[wtState.trad]||{};
      var el=document.getElementById('wcard');
      el.setAttribute('data-format',wtState.fmt); el.setAttribute('data-trad',wtState.trad);
      el.innerHTML=wtCardHTML(v,c,wtState.trad,wtState.fmt);
      var note=document.getElementById('wtAINote'); if(note) note.style.display = WTAI[v.ref+'|'+wtState.trad] ? 'block':'none';
    }
    function wtSetTrad(t){wtState.trad=t;document.querySelectorAll('#wtTrad button').forEach(function(b){b.classList.toggle('on',b.dataset.trad===t);});wtRender();}
    function wtSetFmt(f){wtState.fmt=f;document.querySelectorAll('#wtFmt button').forEach(function(b){b.classList.toggle('on',b.dataset.fmt===f);});wtRender();}
    function wtSetVerse(i){wtState.i=i;document.querySelectorAll('#wtVerses .wt-verse').forEach(function(b){b.classList.toggle('on',(+b.dataset.i)===i);});wtRender();}
    wtRender();

    var WCARD_CSS="*{box-sizing:border-box}.wcard{width:min(100%,650px);border-radius:26px;overflow:hidden;background:#fff;box-shadow:0 26px 72px rgba(15,23,42,.20);border:1px solid #eef1f6;margin:0 auto}.wcard-top{padding:32px 34px 28px;color:#fff;text-align:center;background:linear-gradient(135deg,#0f1f4e,#2347d9 60%,#6f3de8)}.wcard-logo{max-height:78px;max-width:240px;object-fit:contain;margin:0 auto 14px;display:block}.wcard-church{font-size:23px;font-weight:900;line-height:1.2}.wcard-trad{font-size:13.5px;font-weight:600;opacity:.88;margin-top:6px}.wcard-body{padding:34px 38px}.wcard-ref{text-align:center;color:#1d4ed8;font-weight:800;font-size:17px;letter-spacing:.04em}.wcard-verse{font-size:24px;line-height:1.5;font-weight:600;color:#0f172a;text-align:center;margin:11px 0 0;font-style:italic}.wcard-rule{width:66px;height:4px;border-radius:3px;background:linear-gradient(90deg,#2E5BFF,#6f3de8);margin:26px auto}.wcard-headline{font-size:27px;font-weight:900;color:#0f172a;text-align:center;margin:0 0 16px;line-height:1.25}.wcard-reflection{font-size:18px;line-height:1.78;color:#1f2937;margin:0}.wcard-block{margin-top:22px;font-size:17px;line-height:1.72;color:#1f2937}.wcard-block b,.wcard-prayer b{display:block;color:#1d4ed8;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px;font-weight:800}.wcard-prayer{margin-top:24px;background:linear-gradient(135deg,#eef4ff,#f6f0ff);border-radius:18px;padding:20px 22px;font-size:17px;line-height:1.72;color:#1f2937;font-style:italic}.wcard-prayer b{color:#6f3de8;font-style:normal}.wcard-foot{padding:18px 30px;text-align:center;background:#f8fafc;color:#475569;font-size:13.5px;font-weight:600;border-top:1px solid #eef1f6}.wcard-foot .cx{color:#6f3de8;margin:0 9px}.wcard[data-format=pocket]{width:min(100%,430px)}.wcard[data-format=pocket] .wcard-reflection,.wcard[data-format=pocket] .wcard-meaning{display:none}.wcard[data-format=pocket] .wcard-body{padding:26px 28px}.wcard[data-format=pocket] .wcard-verse{font-size:21px}.wcard[data-format=pocket] .wcard-headline{font-size:23px}";
    function witnessPrint(){
      var card=document.getElementById('wcard').outerHTML;
      var w=window.open('','_blank'); if(!w){alert('Please allow pop-ups to print.');return;}
      w.document.write('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+acEsc(WCHURCH)+' — Witness</title>'
        +'<link href="?asset=inter_css" rel="stylesheet">'
        +'<style>'+WCARD_CSS
        +'@page{size:A4;margin:0}'
        +'*{box-sizing:border-box}'
        +'html,body{margin:0;padding:0;background:#fff;font-family:Inter,system-ui,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}'
        +'.a4sheet{width:210mm;height:297mm;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:13mm;background:#fff}'
        +'.a4fit{transform-origin:center center}'
        +'.a4fit .wcard{margin:0;box-shadow:none}'
        +'@media screen{body{background:#5b6472;padding:22px 0}.a4sheet{margin:0 auto;box-shadow:0 12px 44px rgba(0,0,0,.34)}}'
        +'</style></head>'
        +'<body><div class="a4sheet"><div class="a4fit" id="a4fit">'+card+'</div></div>'
        +'<script>window.onload=function(){var mm=96/25.4,availW=(210-26)*mm,availH=(297-26)*mm,el=document.getElementById("a4fit"),r=el.getBoundingClientRect(),s=Math.min(availW/r.width,availH/r.height,1);el.style.transform="scale("+s+")";setTimeout(function(){window.print();},360);};<\/script>'
        +'</body></html>');
      w.document.close();
    }

    function witnessPdf(){
      if(!window.jspdf||!window.jspdf.jsPDF){ witnessPrint(); return; } // graceful fallback if the PDF library isn't ready
      var v=WT[wtState.i], c=v[wtState.trad]||{}, refl=WTAI[v.ref+'|'+wtState.trad]||c.reflection;
      var img=new Image(); img.crossOrigin='anonymous';
      img.onload=function(){ try{var cv=document.createElement('canvas');cv.width=img.naturalWidth;cv.height=img.naturalHeight;cv.getContext('2d').drawImage(img,0,0);buildPdf(cv.toDataURL('image/png'),img.naturalWidth/img.naturalHeight);}catch(e){buildPdf(null,1);} };
      img.onerror=function(){buildPdf(null,1);};
      img.src=WLOGO;
      function buildPdf(logoData,ratio){
        var jsPDF=window.jspdf.jsPDF, d=new jsPDF({unit:'mm',format:'a4'}), W=210, M=20, x=M, cw=W-2*M, y=0;
        d.setFillColor(15,31,78); d.rect(0,0,W,52,'F');
        if(logoData){ var lw=26*(ratio||1), lh=26; if(lw>60){lw=60;lh=60/(ratio||1);} try{d.addImage(logoData,'PNG',(W-lw)/2,9,lw,lh);}catch(e){} }
        d.setTextColor(255,255,255); d.setFont('helvetica','bold'); d.setFontSize(20);
        d.text(WCHURCH,W/2, logoData?44:30,{align:'center'});
        d.setFont('helvetica','normal'); d.setFontSize(10.5);
        d.text(wtTradLabel(wtState.trad)+'  ·  A word of faith', W/2, logoData?50:38,{align:'center'});
        y=68;
        d.setTextColor(29,78,216); d.setFont('helvetica','bold'); d.setFontSize(13);
        d.text(v.ref, W/2, y,{align:'center'}); y+=8;
        d.setTextColor(15,23,42); d.setFont('helvetica','italic'); d.setFontSize(14);
        var vt=d.splitTextToSize('“'+v.verseText+'”', cw); d.text(vt,W/2,y,{align:'center'}); y+=vt.length*7+4;
        d.setDrawColor(111,61,232); d.setLineWidth(1); d.line(W/2-12,y,W/2+12,y); y+=10;
        d.setTextColor(15,23,42); d.setFont('helvetica','bold'); d.setFontSize(17);
        var hl=d.splitTextToSize(c.headline,cw); d.text(hl,W/2,y,{align:'center'}); y+=hl.length*7+4;
        d.setFont('helvetica','normal'); d.setFontSize(11.5); d.setTextColor(31,41,55);
        function para(label,text,gap){
          if(label){ d.setFont('helvetica','bold'); d.setTextColor(29,78,216); d.setFontSize(9.5); d.text(label.toUpperCase(),x,y); y+=5; d.setFont('helvetica','normal'); d.setTextColor(31,41,55); d.setFontSize(11.5);}
          var ls=d.splitTextToSize(text,cw);
          ls.forEach(function(line){ if(y>278){d.addPage();y=22;} d.text(line,x,y); y+=6; });
          y+=(gap||4);
        }
        para('',refl,6);
        para('What this means for you',c.meaning,5);
        para('An invitation',c.invitation,6);
        var pl=d.splitTextToSize(c.prayer,cw-12); var bh=pl.length*6+16; if(y+bh>285){d.addPage();y=22;}
        d.setFillColor(238,244,255); d.roundedRect(x,y,cw,bh,3,3,'F');
        d.setFont('helvetica','bold'); d.setTextColor(111,61,232); d.setFontSize(9.5); d.text('A SHORT PRAYER',x+6,y+8);
        d.setFont('helvetica','italic'); d.setTextColor(31,41,55); d.setFontSize(11.5);
        var py=y+14; pl.forEach(function(line){d.text(line,x+6,py);py+=6;}); y+=bh+10;
        if(y>275){d.addPage();y=22;}
        d.setFont('helvetica','normal'); d.setTextColor(120,130,148); d.setFontSize(9);
        d.text(WCHURCH+'   †   '+c.traditionNote, W/2, 285,{align:'center'});
        d.setFontSize(8); d.setTextColor(150,158,172);
        d.text('Soli Deo Gloria — to God alone be the glory.', W/2, 291,{align:'center'});
        d.save('Witness-'+v.ref.replace(/[^A-Za-z0-9]+/g,'-')+'-'+wtState.trad+'.pdf');
      }
    }

    function witnessAI(){
      var btn=document.getElementById('wtAIBtn'); if(!btn)return;
      var v=WT[wtState.i], trad=wtState.trad, old=btn.innerHTML;
      btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Writing in your voice…';
      var fd=new FormData(); fd.append('ref',v.ref); fd.append('trad',trad);
      fetch('?action=witness_ai',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(dd){
        btn.disabled=false; btn.innerHTML=old;
        if(dd.error){ alert(dd.error); return; }
        if(dd.text){ WTAI[v.ref+'|'+trad]=dd.text.trim(); wtRender(); }
      }).catch(function(){ btn.disabled=false; btn.innerHTML=old; alert('Request failed — please try again.'); });
    }
    </script>
    <?php
    endPage();
}




function renderCheckin(): void {
    $db = getDB();
    $services = $db->query("SELECT id,name,date FROM services ORDER BY date DESC LIMIT 30")->fetchAll();
    $sid = (int)($_GET['service'] ?? ($services[0]['id'] ?? 0));
    $log = [];
    if ($sid) { $st = $db->prepare("SELECT c.*, m.first_name,m.last_name,m.allergies,m.guardian_name,m.guardian_phone FROM checkin_log c JOIN members m ON m.id=c.member_id WHERE c.service_id=? ORDER BY c.checked_in_at DESC"); $st->execute([$sid]); $log = $st->fetchAll(); }
    $allMembers = $db->query("SELECT id,first_name,last_name FROM members WHERE status!='inactive' ORDER BY last_name,first_name LIMIT 2000")->fetchAll();
    $present = count(array_filter($log, fn($r)=>empty($r['checked_out_at'])));
    $church = getSetting('church_name') ?: 'Our Church';
    $review = $db->query("SELECT id,first_name,last_name,email,phone,wants_membership,created_at FROM members WHERE needs_review=1 ORDER BY created_at DESC LIMIT 50")->fetchAll();
    startPage(t('Check-In'), 'checkin');
    ?>
    <div class="page-head"><div><div class="page-title"><i class="fa-solid fa-child-reaching" style="color:var(--blue-600)"></i> <?=h(t('Check-In'))?> &amp; Security</div><div class="page-sub">Secure child &amp; family check-in with allergy alerts, printed name tags and guardian texts.</div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-outline" onclick="showModal('childModal')"><i class="fa-solid fa-notes-medical"></i> Child details</button><button class="btn btn-primary" onclick="showModal('checkinModal')"><i class="fa-solid fa-right-to-bracket"></i> Check someone in</button></div>
    </div>
    <?php if($review): ?>
