      <div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Contact</th><th>Checked in</th><th>Wants to join?</th><th style="text-align:right">Decision</th></tr></thead><tbody>
      <?php foreach($review as $r): ?><tr>
        <td><strong><?=h(trim($r['first_name'].' '.$r['last_name']))?></strong></td>
        <td style="font-size:var(--text-xs);color:var(--gray-500)"><?=h($r['email']?:($r['phone']?:'—'))?></td>
        <td style="font-size:var(--text-xs);color:var(--gray-400)"><?=h(substr((string)$r['created_at'],0,10))?></td>
        <td><?=$r['wants_membership']?'<span class="badge badge-active">Yes — asked to join</span>':'<span style="color:var(--gray-400)">—</span>'?></td>
        <td style="text-align:right;white-space:nowrap">
          <form method="POST" action="?action=checkin_promote" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-primary btn-xs"><i class="fa-solid fa-check"></i> Make member</button></form>
          <form method="POST" action="?action=checkin_keep_visitor" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-outline btn-xs">Keep visitor</button></form>
        </td>
      </tr><?php endforeach; ?>
      </tbody></table></div></div></div>
    <?php endif; ?>
    <div class="card" style="margin-bottom:var(--sp-5)"><div class="card-body" style="display:flex;gap:var(--sp-4);align-items:center;flex-wrap:wrap">
      <form method="GET" style="display:flex;gap:8px;align-items:center"><input type="hidden" name="page" value="checkin">
        <label style="font-weight:700;font-size:var(--text-sm)">Service</label>
        <select class="select" name="service" onchange="this.form.submit()" style="min-width:240px">
          <?php foreach($services as $s): ?><option value="<?=$s['id']?>" <?=$sid==$s['id']?'selected':''?>><?=h($s['name'])?> — <?=h($s['date'])?></option><?php endforeach; ?>
          <?php if(!$services): ?><option>No services yet — create one under Attendance</option><?php endif; ?>
        </select>
      </form>
      <div class="stat-chip"><strong><?=$present?></strong> present now</div>
      <div class="stat-chip"><strong><?=count($log)?></strong> checked in</div>
      <?php if($log): ?><button class="btn btn-light btn-sm" onclick="printAllTags()"><i class="fa-solid fa-print"></i> Print all tags</button><?php endif; ?>
    </div></div>
    <div class="card"><div class="card-body-0"><div class="table-wrap"><table class="data-table">
      <thead><tr><th>Name</th><th>Allergies</th><th>Code</th><th>Guardian</th><th>In / Out</th><th></th></tr></thead><tbody>
      <?php if(!$log): ?><tr><td colspan="6"><div class="empty"><i class="fa-solid fa-child-reaching"></i><div>No one checked in for this service yet.</div></div></td></tr><?php endif; ?>
