        <td><code style="font-weight:700;letter-spacing:1px"><?=h($r['security_code'])?></code></td>
        <td><?=h($r['guardian_name']?:'—')?><?=$r['guardian_notified']?' <i class="fa-solid fa-comment-sms" style="color:var(--green)" title="Texted"></i>':''?></td>
        <td style="font-size:var(--text-xs);color:var(--gray-500)"><?=h(substr((string)$r['checked_in_at'],11,5))?><?=$out?' → '.h(substr((string)$r['checked_out_at'],11,5)):''?></td>
        <td style="white-space:nowrap;text-align:right">
          <button class="icon-btn" onclick='printTag(<?=htmlspecialchars(json_encode(['n'=>$nm,'c'=>$r['security_code'],'a'=>$r['allergies'],'r'=>$r['room'],'s'=>$church]),ENT_QUOTES)?>)' title="Print name tag"><i class="fa-solid fa-tag"></i></button>
          <?php if(!$out): ?>
            <?php if($r['guardian_phone']): ?><form method="POST" action="?action=notify_guardian" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="service_id" value="<?=$sid?>"><button class="icon-btn" title="Text the parent"><i class="fa-solid fa-comment-sms"></i></button></form><?php endif; ?>
            <form method="POST" action="?action=checkout_member" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="service_id" value="<?=$sid?>"><button class="icon-btn" title="Check out"><i class="fa-solid fa-right-from-bracket"></i></button></form>
          <?php endif; ?>
        </td>
      </tr>
      <?php endforeach; ?>
      </tbody></table></div></div></div>

    <div class="modal-bg" id="checkinModal"><div class="modal-card"><div class="modal-hd"><div class="modal-title">Check someone in</div><button class="modal-close" onclick="hideModal('checkinModal')">&times;</button></div>
