        <div class="field span2"><label>Person</label><select class="select" name="member_id" required><option value="">Select…</option><?php foreach($allMembers as $m): ?><option value="<?=$m['id']?>"><?=h($m['first_name'].' '.$m['last_name'])?></option><?php endforeach; ?></select></div>
        <div class="field"><label>Service</label><select class="select" name="service_id" required><?php foreach($services as $s): ?><option value="<?=$s['id']?>" <?=$sid==$s['id']?'selected':''?>><?=h($s['name'])?></option><?php endforeach; ?></select></div>
        <div class="field"><label>Room</label><input class="input" name="room" placeholder="Nursery, K–2…"></div>
        <div class="field span2"><label>Note</label><input class="input" name="note" placeholder="optional"></div>
        <div class="field span2"><label style="display:flex;gap:8px;align-items:center;font-size:var(--text-sm)"><input type="checkbox" name="notify" value="1"> Text the guardian a pickup code (needs Twilio + a guardian phone)</label></div>
      </div></div><div class="modal-ft"><button type="button" class="btn btn-ghost" onclick="hideModal('checkinModal')">Cancel</button><button class="btn btn-primary">Check in</button></div></form></div></div>

    <div class="modal-bg" id="childModal"><div class="modal-card"><div class="modal-hd"><div class="modal-title">Child &amp; guardian details</div><button class="modal-close" onclick="hideModal('childModal')">&times;</button></div>
      <form method="POST" action="?action=save_checkin_member"><div class="modal-bd"><div class="form-grid">
        <div class="field span2"><label>Member</label><select class="select" name="member_id" required><option value="">Select a member…</option><?php foreach($allMembers as $m): ?><option value="<?=$m['id']?>"><?=h($m['first_name'].' '.$m['last_name'])?></option><?php endforeach; ?></select></div>
