function renderAccounting(): void {
    $db = getDB();
    $tab = $_GET['tab'] ?? 'overview';
    $year = (int)($_GET['year'] ?? date('Y'));
    $funds = $db->query("SELECT id,name FROM funds ORDER BY name")->fetchAll();
    startPage(t('Accounting'), 'accounting');
    ?>
    <div class="page-head"><div><div class="page-title"><i class="fa-solid fa-calculator" style="color:var(--blue-600)"></i> <?=h(t('Accounting'))?> &amp; Budgets</div><div class="page-sub">Fund budgets, an expense register, bank-statement import and printable checks — all free.</div></div></div>
    <div class="tabs" style="margin-bottom:var(--sp-5)">
      <a href="?page=accounting&amp;tab=overview" class="tab <?=$tab==='overview'?'active':''?>">Overview</a>
      <a href="?page=accounting&amp;tab=register" class="tab <?=$tab==='register'?'active':''?>">Register</a>
      <a href="?page=accounting&amp;tab=budget" class="tab <?=$tab==='budget'?'active':''?>">Budgets</a>
    </div>
    <?php if ($tab==='register'):
        $tx = $db->query("SELECT l.*, f.name fund FROM ledger l LEFT JOIN funds f ON f.id=l.fund_id ORDER BY l.date DESC, l.id DESC LIMIT 500")->fetchAll();
        $income=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM ledger WHERE type='income'")->fetchColumn();
        $expense=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM ledger WHERE type='expense'")->fetchColumn();
        ?>
        <div class="stat-grid" style="margin-bottom:var(--sp-5)">
          <div class="stat-card"><div class="stat-label">Recorded income</div><div class="stat-value"><?=fmt($income)?></div></div>
          <div class="stat-card"><div class="stat-label">Recorded expense</div><div class="stat-value"><?=fmt($expense)?></div></div>
          <div class="stat-card"><div class="stat-label">Net</div><div class="stat-value"><?=fmt($income-$expense)?></div></div>
        </div>
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-bottom:var(--sp-3);flex-wrap:wrap">
          <button class="btn btn-outline" onclick="showModal('importBank')"><i class="fa-solid fa-building-columns"></i> Import bank file</button>
          <button class="btn btn-primary" onclick="newTx()"><i class="fa-solid fa-plus"></i> New transaction</button>
        </div>
        <div class="card"><div class="card-body-0"><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Fund</th><th>Payee</th><th>Amount</th><th>Method</th><th>✓</th><th></th></tr></thead><tbody>
        <?php if(!$tx): ?><tr><td colspan="9"><div class="empty"><i class="fa-solid fa-receipt"></i><div>No transactions yet. Record one or import a bank file.</div></div></td></tr><?php endif; ?>
        <?php foreach($tx as $t): ?><tr>
          <td><?=h($t['date'])?></td>
          <td><span class="badge badge-<?=$t['type']==='income'?'active':'inactive'?>"><?=h(ucfirst($t['type']))?></span></td>
          <td><?=h($t['category']?:'—')?></td><td><?=h($t['fund']?:'—')?></td><td><?=h($t['payee']?:'—')?></td>
          <td style="font-weight:700;color:<?=$t['type']==='income'?'var(--green)':'var(--gray-800)'?>"><?=fmt((float)$t['amount'])?></td>
          <td style="font-size:var(--text-xs)"><?=h($t['method']?:'—')?><?=$t['check_number']?' #'.h($t['check_number']):''?></td>
          <td><?=$t['reconciled']?'<i class="fa-solid fa-check" style="color:var(--green)"></i>':''?></td>
          <td style="text-align:right;white-space:nowrap">
            <?php if($t['type']==='expense'): ?><button class="icon-btn" title="Print check" onclick='printCheck(<?=htmlspecialchars(json_encode(['p'=>$t['payee'],'a'=>(float)$t['amount'],'d'=>$t['date'],'m'=>$t['memo'],'n'=>$t['check_number'],'c'=>(getSetting('church_name')?:'')]),ENT_QUOTES)?>)'><i class="fa-solid fa-money-check-dollar"></i></button><?php endif; ?>
            <button class="icon-btn" title="Edit" onclick='editTx(<?=htmlspecialchars(json_encode($t),ENT_QUOTES)?>)'><i class="fa-solid fa-pen"></i></button>
            <form method="POST" action="?action=delete_ledger" style="display:inline" onsubmit="return confirm('Delete?')"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="icon-btn"><i class="fa-solid fa-trash"></i></button></form>
          </td>
        </tr><?php endforeach; ?>
        </tbody></table></div></div></div>
        <div class="modal-bg" id="txModal"><div class="modal-card"><div class="modal-hd"><div class="modal-title" id="txTitle">New transaction</div><button class="modal-close" onclick="hideModal('txModal')">&times;</button></div>
