            <div class="field"><label>Date</label><input class="input" type="date" name="date" id="tx_date" value="<?=date('Y-m-d')?>"></div>
            <div class="field"><label>Type</label><select class="select" name="type" id="tx_type"><option value="expense">Expense</option><option value="income">Income</option></select></div>
            <div class="field"><label>Category</label><input class="input" name="category" id="tx_category" placeholder="Utilities, Salaries…"></div>
            <div class="field"><label>Fund</label><select class="select" name="fund_id" id="tx_fund_id"><option value="">—</option><?php foreach($funds as $f): ?><option value="<?=$f['id']?>"><?=h($f['name'])?></option><?php endforeach; ?></select></div>
