function renderConsole(): void {
    requireAdmin();
    startPage(t('Console'), 'console');
    ?>
    <div class="page-head"><div>
      <div class="page-title"><i class="fa-solid fa-terminal" style="color:var(--blue-600)"></i> <?=h(t('Console'))?></div>
      <div class="page-sub">A safe operations terminal. It runs a fixed set of whitelisted commands in-process — it is <strong>not a shell</strong> and cannot run arbitrary code. Type <code>help</code> to begin.</div>
    </div></div>
    <div class="card"><div class="card-body">
      <div class="console-chips">
        <?php foreach (['help','version','tables','schema','indexes','diagnostics','settings','stats','integrations','php','pages','clear'] as $c): ?>
          <button type="button" class="console-chip" onclick="conRun('<?=$c?>')"><?=$c?></button>
        <?php endforeach; ?>
      </div>
      <div id="conOut" class="console-out" aria-live="polite"></div>
      <div class="console-input">
        <span class="console-prompt">aichurch&gt;</span>
        <input id="conIn" class="console-cmd" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g.  select first_name,last_name,engagement_score from members limit 5" onkeydown="conKey(event)">
        <button class="btn btn-primary btn-sm" onclick="conRun()"><i class="fa-solid fa-play"></i> Run</button>
      </div>
    </div></div>
    <style>
    .console-chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:var(--sp-3)}
    .console-chip{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:var(--text-2xs);padding:4px 10px;border-radius:7px;border:1px solid var(--gray-200);background:var(--gray-50);color:var(--gray-700);cursor:pointer;transition:background var(--t-base),color var(--t-base),border-color var(--t-base)}
    .console-chip:hover{background:var(--navy);color:#fff;border-color:var(--navy)}
    .console-out{background:#0c1226;color:#cdd6f4;border-radius:12px;padding:16px 18px;height:min(56vh,520px);overflow-y:auto;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12.5px;line-height:1.6}
    .con-line{margin-bottom:6px;white-space:pre-wrap;word-break:break-word}
    .con-line pre{margin:0;white-space:pre-wrap;font:inherit;color:#cdd6f4}
    .con-ps{color:#a6e3a1;font-weight:700}.con-cmd-echo{color:#7dd3fc}
    .con-err{color:#f38ba8}.con-muted{color:#7782a8}
    .con-table{border-collapse:collapse;width:100%;margin:4px 0 8px;font-size:12px}
    .con-table th{text-align:left;color:#a6adc8;border-bottom:1px solid #313449;padding:4px 12px 4px 0;font-weight:700;white-space:nowrap}
    .con-table td{padding:3px 12px 3px 0;border-bottom:1px solid #1b1f33;color:#cdd6f4;vertical-align:top}
    .console-input{display:flex;align-items:center;gap:8px;margin-top:var(--sp-3)}
    .console-prompt{font-family:ui-monospace,monospace;color:var(--green,#16a34a);font-weight:700}
    .console-cmd{flex:1;min-width:0;font-family:ui-monospace,monospace;font-size:13px;border:1px solid var(--gray-200);border-radius:9px;padding:9px 12px;background:var(--white);color:var(--gray-900)}
    .console-cmd:focus{outline:none;border-color:var(--blue-500);box-shadow:0 0 0 3px rgba(46,91,255,.12)}
    @media print{.console-out{height:auto}}
    </style>
    <script>
    (function(){
      var out=document.getElementById('conOut'), inp=document.getElementById('conIn'), hist=[], hi=0;
      function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
      function add(html,cls){var d=document.createElement('div');d.className='con-line'+(cls?' '+cls:'');d.innerHTML=html;out.appendChild(d);out.scrollTop=out.scrollHeight;}
      function tbl(cols,rows,note){var h='<table class="con-table"><thead><tr>';(cols||[]).forEach(function(c){h+='<th>'+esc(c)+'</th>';});h+='</tr></thead><tbody>';(rows||[]).forEach(function(r){h+='<tr>';r.forEach(function(v){h+='<td>'+esc(v)+'</td>';});h+='</tr>';});h+='</tbody></table>';if(note)h+='<div class="con-muted" style="font-size:11px">'+esc(note)+'</div>';add(h);}
      window.conRun=function(cmd){
        var hasArg=(typeof cmd==='string');
        cmd=(hasArg?cmd:inp.value).trim(); if(!cmd)return;
        add('<span class="con-ps">aichurch&gt;</span> '+esc(cmd),'con-cmd-echo');
        hist.push(cmd); hi=hist.length; if(!hasArg)inp.value='';
        if(cmd==='clear'){out.innerHTML='';return;}
        var fd=new FormData(); fd.append('cmd',cmd);
        fetch('?action=console_exec',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(d){
          if(!d){add('No response','con-err');return;}
          if(d.kind==='clear'){out.innerHTML='';return;}
          if(d.error&&!d.ok){add('<i class="fa-solid fa-circle-xmark"></i> '+esc(d.error),'con-err');return;}
          if(d.kind==='table'){tbl(d.cols,d.rows,d.note);}
          else{add('<pre>'+esc(d.text||'')+'</pre>');}
        }).catch(function(){add('Request failed — please refresh and sign in again.','con-err');});
      };
      window.conKey=function(e){
        if(e.key==='Enter'){conRun();}
        else if(e.key==='ArrowUp'){if(hi>0){hi--;inp.value=hist[hi]||'';}e.preventDefault();}
        else if(e.key==='ArrowDown'){if(hi<hist.length-1){hi++;inp.value=hist[hi]||'';}else{hi=hist.length;inp.value='';}e.preventDefault();}
      };
      add('<span class="con-muted">Free Church ChMS Console — read-only &amp; safe. Type <b>help</b> and press Enter. ↑/↓ recalls history.</span>');
      inp.focus();
    })();
    </script>
    <?php
    endPage();
}
