        case 'pipeline':       renderLeaderPipeline(); break;
        case 'streaming':      renderStreamingHub(); break;
        case 'admin':          renderAdminDashboard(); break;
        case 'admin_requests': renderAdminRequests(); break;
        case 'admin_users':    renderAdminUsers(); break;
        case 'admin_churches': renderAdminChurches(); break;
        case 'admin_licenses': renderAdminLicenses(); break;
        case 'admin_config':   renderAdminConfig(); break;
        case 'admin_audit':    renderAdminAudit(); break;
        case 'migrate':        renderMigrate(); break;
        case 'console':        renderConsole(); break;
        case 'checkin':        renderCheckin(); break;
        case 'worship':        renderWorship(); break;
        case 'witness':        renderWitness(); break;
        case 'accounting':     renderAccounting(); break;
        default:               renderDashboard();
    }
}


$page   = $_GET['page'] ?? 'dashboard';
$action = $_POST['action'] ?? $_GET['action'] ?? '';
if (isset($_GET['asset'])) { standaloneAsset((string)$_GET['asset']); exit; } // [standalone] serve embedded front-end assets, no network



try {
    getDB(); 
    csrfToken(); 
    if ($action) handleAction($page, $action);

    if (!isLoggedIn() && $page !== 'login') { header('Location: ?page=login'); exit; }
    if ($page === 'login') { renderLogin(); exit; }
    renderPage($page);
} catch (\Throwable $e) {
    error_log('AIChurch fatal ['.$action.'/'.$page.']: '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine());
    $isAjax = (stripos($_SERVER['HTTP_ACCEPT'] ?? '', 'json') !== false)
           || (strtolower($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '') === 'xmlhttprequest')
           || in_array($action, ['ai_chat','ai_generate_content','generate_report','ai_explain_metrics','analytics_data','pulse_data','ai_pulse_insight','witness_ai','save_claude','save_integration','save_comm','console_exec','set_theme','mute_pastoral_alerts','upload_church_logo','remove_church_logo','test_anthropic','bible_verse'], true)
           || (bool)preg_match('/^(sync_|test_)/', $action);
    if (!headers_sent()) {
        if ($isAjax) { http_response_code(500); header('Content-Type: application/json'); echo json_encode(['error'=>'Something went wrong on the server — please try again.']); exit; }
        http_response_code(303); header('Location: ?page='.preg_replace('/[^a-z0-9_]/','',$page).'&err='.urlencode('Something went wrong — please try again.')); exit;
    }
    http_response_code(500);
    echo '<div style="max-width:640px;margin:60px auto;padding:24px;font-family:system-ui,-apple-system,sans-serif;text-align:center;color:#374151">'
       . '<h2 style="color:#1f2937">We hit a snag</h2>'
       . '<p>Something went wrong loading this page. Please try again, or return to your <a href="?page=dashboard" style="color:#2E5BFF;font-weight:600">dashboard</a>.</p></div>';
    exit;
}



function standaloneAsset(string $k): void {
    static $A = null;
    if ($A === null) $A = array(
      'chart_js'=>array('text/javascript',''),
      'marked_js'=>array('text/javascript',''),
      'purify_js'=>array('text/javascript',''),
      'qrcode_js'=>array('text/javascript',''),
      'xlsx_js'=>array('text/javascript',''),
      'jspdf_js'=>array('text/javascript',''),
      'jspdf_at_js'=>array('text/javascript',''),
      'fa_solid'=>array('font/woff2',''),
      'fa_brands'=>array('font/woff2',''),
      'fa_regular'=>array('font/woff2',''),
      'fa_v4'=>array('font/woff2',''),
      'inter_latin'=>array('font/woff2',''),
      'inter_latinext'=>array('font/woff2',''),
      'fa_css'=>array('text/css',''),
      'inter_css'=>array('text/css',''),
      'license_txt'=>array('text/plain','')
    );
    if (!isset($A[$k])) { http_response_code(404); header('Content-Type: text/plain'); echo 'Not found'; exit; }
    $mime = $A[$k][0];
    if (!headers_sent()) {
        header('Content-Type: '.$mime.(strpos($mime,'font/')===0 ? '' : '; charset=utf-8'));
        header('Cache-Control: public, max-age=31536000, immutable');
        header('X-Content-Type-Options: nosniff');
    }
    echo base64_decode($A[$k][1]);
    exit;
}
